    "",
    "**Luyện tập 1.** Gọi $S$ là tập nghiệm của phương trình",
    "$x^2 - 24x + 143 = 0$.",
    "Các mệnh đề sau đúng hay sai?",
    "a) $13 \\in S$;          b) $11 \\notin S$;          c) $n(S) = 2$.",
    "",
    "### b. Tập hợp con",
    "",
    "**HĐ3.** Gọi $H$ là tập hợp các bạn tham gia Chuyên đề 2 trong *tình huống mở đầu* có tên bắt đầu bằng chữ H. Các phần tử của tập hợp $H$ có là phần tử của tập hợp $B$ trong HĐ1 không?",
    "",
    "13",
    "> Nếu mọi phần tử của tập hợp $T$ đều là phần tử của tập hợp $S$ thì ta nói $T$ là một **tập hợp con** (tập con) của $S$ và viết là $T \\subset S$ (đọc là $T$ chứa trong $S$ hoặc $T$ là tập con của $S$).",
    "",
    "*(Khung chú thích:",
    "- Thay cho $T \\subset S$, ta còn viết $S \\supset T$ (đọc là $S$ chứa $T$).",
    "- Kí hiệu $T \\not\\subset S$ để chỉ $T$ không là tập con của $S$.)*",
    "",
    "*Nhận xét*",
    "- Từ định nghĩa trên, $T$ là tập con của $S$ nếu mệnh đề sau đúng:",
    "$\\forall x, x \\in T \\Rightarrow x \\in S$.",
    "- Quy ước tập rỗng là tập con của mọi tập hợp.",
    "",
    "[Hình ảnh: Sơ đồ Ven minh hoạ tập hợp bằng đường cong kín, ghi chú là Hình 1.2]",
    "",
    "> Người ta thường minh hoạ một tập hợp bằng một hình phẳng được bao quanh bởi một đường kín, gọi là **biểu đồ Ven** (H.1.2).",
    "",
    "Minh hoạ $T$ là một tập con của $S$ như Hình 1.3.",
    "",
    "[Hình ảnh: Sơ đồ Ven minh hoạ tập hợp T nằm bên trong tập hợp S, ghi chú là Hình 1.3]",
    "",
    "**Ví dụ 2.** Cho tập hợp $S = \\{2; 3; 5\\}$. Những tập hợp nào sau đây là tập con của $S$?",
    "$S_1 = \\{3\\}$;             $S_2 = \\{0; 2\\}$;             $S_3 = \\{3; 5\\}$.",
    "",
    "**Giải**",
    "Các tập hợp $S_1 = \\{3\\}$, $S_3 = \\{3; 5\\}$ là những tập con của $S$ (H.1.4).",
    "",
    "[Hình ảnh: Ba sơ đồ Ven tương ứng: ",
    "- Bên trái: S_1={3} nằm trong S={2, 3, 5}",
    "- Ở giữa: S_2={0, 2} giao với S={2, 3, 5} nhưng không nằm trọn trong S (0 nằm ngoài)",
    "- Bên phải: S_3={3, 5} nằm trong S={2, 3, 5}",
    "ghi chú là Hình 1.4]",
    "",
    "### c. Hai tập hợp bằng nhau",
    "",
    "**HĐ4.** Sơn và Thu viết tập hợp các số chính phương nhỏ hơn 100 như sau:",
    "Sơn: $S = \\{0; 1; 4; 9; 16; 25; 36; 49; 64; 81\\}$;",
    "Thu: $T = \\{n \\in \\mathbb{N} | n \\text{ là số chính phương}; n < 100\\}$.",
    "Hỏi bạn nào viết đúng?",
    "",
    "> Hai tập hợp $S$ và $T$ được gọi là **hai tập hợp bằng nhau** nếu mỗi phần tử của $T$ cũng là phần tử của tập hợp $S$ và ngược lại. Kí hiệu là $S = T$.",
    "",
    "*(Khung chú thích: Nếu $S \\subset T$ và $T \\subset S$ thì $S = T$.)*",
    "",
    "**Ví dụ 3.** Cho hai tập hợp:",
    "$C = \\{n \\in \\mathbb{N} | n \\text{ là bội chung của 2 và 3}; n < 30\\}$;",
    "$D = \\{n \\in \\mathbb{N} | n \\text{ là bội của 6}; n < 30\\}$.",
    "Chứng minh $C = D$.",
    "",
    "14",
    "**Giải**",
    "Ta có: $C = \\{0; 6; 12; 18; 24\\}$;",
    "       $D = \\{0; 6; 12; 18; 24\\}$.",
    "Vậy $C = D$.",
    "",
    "**Luyện tập 2.** Giả sử $C$ là tập hợp các hình bình hành có hai đường chéo vuông góc; $D$ là tập hợp các hình vuông.",
    "Các mệnh đề sau đúng hay sai?",
    "a) $C \\subset D$;          b) $C \\supset D$;          c) $C = D$.",
    "",
    "## 2. CÁC TẬP HỢP SỐ",
    "",
    "### a. Mối quan hệ giữa các tập hợp số",
    "",
    "- *Tập hợp các số tự nhiên* $\\mathbb{N} = \\{0; 1; 2; 3; 4; ...\\}$.",
    "- *Tập hợp các số nguyên* $\\mathbb{Z}$ gồm các số tự nhiên và các số nguyên âm:",
    "$\\mathbb{Z} = \\{...; -3; -2; -1; 0; 1; 2; 3; ...\\}$.",
    "- *Tập hợp các số hữu tỉ* $\\mathbb{Q}$ gồm các số viết được dưới dạng phân số $\\frac{a}{b}$, với $a, b \\in \\mathbb{Z}, b \\neq 0$.",
    "Số hữu tỉ còn được biểu diễn dưới dạng số thập phân hữu hạn hoặc vô hạn tuần hoàn.",
    "- *Tập hợp các số thực* $\\mathbb{R}$ gồm các số hữu tỉ và các số vô tỉ. Số vô tỉ là các số thập phân vô hạn không tuần hoàn.",
    "",
    "**HĐ5.** Các mệnh đề sau đúng hay sai?",
    "a) Mọi số nguyên đều viết được dưới dạng phân số;",
    "b) Tập hợp các số thực chứa tập hợp các số hữu tỉ;",
    "c) Tồn tại một số thực không là số hữu tỉ.",
    "",
    "> Mối quan hệ giữa các tập hợp số: $\\mathbb{N} \\subset \\mathbb{Z} \\subset \\mathbb{Q} \\subset \\mathbb{R}$.",
    "",
    "[Hình ảnh: Sơ đồ Ven lồng nhau minh hoạ tập N nằm trong tập Z, tập Z nằm trong tập Q, tập Q nằm trong tập R. Ghi chú Hình 1.5]",
    "",
    "**Ví dụ 4.** Hãy xác định tính đúng sai của các mệnh đề sau:",
    "a) $3,274 \\in \\mathbb{Q}$;          b) $\\sqrt{2} \\in \\mathbb{R}$;          c) $\\frac{3}{4} \\in \\mathbb{Z}$.",
    "",
    "**Giải**",
    "a) $3,274 \\in \\mathbb{Q}$ là mệnh đề đúng.",
    "b) $\\sqrt{2} \\in \\mathbb{R}$ là mệnh đề đúng.",
    "c) $\\frac{3}{4} \\in \\mathbb{Z}$ là mệnh đề sai.",
    "",
    "**Luyện tập 3.** Cho tập hợp $C = \\{-4; 0; 1; 2\\}$. Các mệnh đề sau đúng hay sai?",
    "a) $C$ là tập con của $\\mathbb{Z}$;          b) $C$ là tập con của $\\mathbb{N}$;          c) $C$ là tập con của $\\mathbb{R}$.",
    "",
    "15",
    "### b. Các tập con thường dùng của $\\mathbb{R}$",
    "",
    "**HĐ6.** Cho hai tập hợp $C = \\{x \\in \\mathbb{R} | x \\ge 3\\}$ và $D = \\{x \\in \\mathbb{R} | x > 3\\}$.",
    "Các mệnh đề sau đúng hay sai?",
    "a) $C, D$ là các tập con của $\\mathbb{R}$;          b) $\\forall x, x \\in C \\Rightarrow x \\in D$;",
    "c) $3 \\in C$ nhưng $3 \\notin D$;          d) $C = D$.",
    "",
    "> Một số tập con thường dùng của tập số thực $\\mathbb{R}$:",
    "> - **Khoảng**",
    ">   $(a; b) = \\{x \\in \\mathbb{R} | a < x < b\\}$  [Hình ảnh: Biểu diễn trên trục số từ a đến b, hai đầu mút đánh ngoặc tròn]",
    ">   $(a; +\\infty) = \\{x \\in \\mathbb{R} | x > a\\}$ [Hình ảnh: Biểu diễn trên trục số từ a đến vô cực, ngoặc tròn ở a]",
    ">   $(-\\infty; b) = \\{x \\in \\mathbb{R} | x < b\\}$ [Hình ảnh: Biểu diễn trên trục số từ âm vô cực đến b, ngoặc tròn ở b]",
    ">   $(-\\infty; +\\infty)$ [Hình ảnh: Trục số thực $\\mathbb{R}$]",
    "> - **Đoạn**",
    ">   $[a; b] = \\{x \\in \\mathbb{R} | a \\le x \\le b\\}$ [Hình ảnh: Biểu diễn trên trục số từ a đến b, hai đầu mút đánh ngoặc vuông]",
    "> - **Nửa khoảng**",
    ">   $[a; b) = \\{x \\in \\mathbb{R} | a \\le x < b\\}$ [Hình ảnh: Biểu diễn trên trục số từ a đến b, ngoặc vuông ở a, tròn ở b]",
    ">   $(a; b] = \\{x \\in \\mathbb{R} | a < x \\le b\\}$ [Hình ảnh: Biểu diễn trên trục số từ a đến b, ngoặc tròn ở a, vuông ở b]",
    ">   $[a; +\\infty) = \\{x \\in \\mathbb{R} | x \\ge a\\}$ [Hình ảnh: Biểu diễn trên trục số từ a đến vô cực, ngoặc vuông ở a]",
    ">   $(-\\infty; b] = \\{x \\in \\mathbb{R} | x \\le b\\}$ [Hình ảnh: Biểu diễn trên trục số từ âm vô cực đến b, ngoặc vuông ở b]",
    "",
    "*(Khung chú thích:",
    "Kí hiệu $+\\infty$: Đọc là dương vô cực (hoặc dương vô cùng).",
    "Kí hiệu $-\\infty$: Đọc là âm vô cực (hoặc âm vô cùng).",
    "$a, b$ gọi là các đầu mút của đoạn, khoảng hay nửa khoảng.)*",
    "",
    "**Ví dụ 5.** Viết các tập hợp sau dưới dạng các khoảng, đoạn, nửa khoảng trong $\\mathbb{R}$ rồi biểu diễn trên trục số: $C = \\{x \\in \\mathbb{R} | 2 \\le x \\le 7\\}$; $D = \\{x \\in \\mathbb{R} | x < 2\\}$.",
    "",
    "**Giải**",
    "$C = [2; 7]$ [Hình ảnh biểu diễn đoạn [2; 7] trên trục số]",
    "$D = (-\\infty; 2)$ [Hình ảnh biểu diễn khoảng (-\\infty; 2) trên trục số]",
    "",
    "**Luyện tập 4.** Hãy ghép mỗi dòng ở cột bên trái với một dòng thích hợp ở cột bên phải.",
    "",
    "| | |",
    "|---|---|",
    "| 1) $x \\in [2; 5]$ | a) $2 < x \\le 5$ |",
    "| 2) $x \\in (2; 5]$ | b) $x \\ge 7$ |",
    "| 3) $x \\in [7; +\\infty)$ | c) $7 < x < 10$ |",
    "| 4) $x \\in (7; 10)$ | d) $2 \\le x \\le 5$ |",
    "| | e) $2 \\le x < 5$ |",
    "",
    "## 3. CÁC PHÉP TOÁN TRÊN TẬP HỢP",
    "",
    "### a. Giao của hai tập hợp",
    "",
    "**HĐ7.** Viết tập hợp $X$ gồm những thành viên tham gia cả hai chuyên đề 1 và 2 trong *tình huống mở đầu*.",
    "Tập $X$ có phải là tập con của tập $A$ không? Tập $X$ có phải là tập con của tập $B$ không? ($A, B$ là các tập hợp trong HĐ1).",
    "",
    "16",
    "> Tập hợp gồm các phần tử thuộc cả hai tập hợp $S$ và $T$ gọi là **giao của hai tập hợp** $S$ và $T$, kí hiệu là $S \\cap T$.",
    "> $S \\cap T = \\{x | x \\in S \\text{ và } x \\in T\\}$.",
    "",
    "[Hình ảnh: Biểu đồ Ven giao của S và T. Phần chung được tô màu đỏ. Ghi chú Hình 1.6]",
    "",
    "**Ví dụ 6**",
    "a) Cho hai tập hợp $C = \\{4; 7; 27\\}$ và $D = \\{2; 4; 9; 27; 36\\}$. Hãy xác định tập hợp $C \\cap D$.",
    "b) Cho hai tập hợp $E = [1; +\\infty)$ và $F = (-\\infty; 3]$. Hãy xác định tập hợp $E \\cap F$.",
    "",
    "**Giải**",
    "a) Giao của hai tập hợp $C$ và $D$ là $C \\cap D = \\{4; 27\\}$.",
    "b) Giao của hai tập hợp $E$ và $F$ là $E \\cap F = [1; 3]$.",
    "[Hình ảnh: Trục số biểu diễn sự giao nhau của $[1; +\\infty)$ và $(-\\infty; 3]$ là $[1; 3]$]",
    "",
    "**Luyện tập 5.** Cho các tập hợp $C = [1; 5]$, $D = [-2; 3]$. Hãy xác định tập hợp $C \\cap D$.",
    "",
    "### b. Hợp của hai tập hợp",
    "",
    "**HĐ8.** Trở lại *tình huống mở đầu*, hãy xác định tập hợp các thành viên tham gia Chuyên đề 1 hoặc Chuyên đề 2.",
    "",
    "> Tập hợp gồm các phần tử thuộc tập hợp $S$ hoặc thuộc tập hợp $T$ gọi là **hợp của hai tập hợp** $S$ và $T$, kí hiệu là $S \\cup T$.",
    "> $S \\cup T = \\{x | x \\in S \\text{ hoặc } x \\in T\\}$.",
    "",
    "[Hình ảnh: Biểu đồ Ven hợp của S và T. Cả hai vòng tròn S và T đều được tô màu xanh lá. Ghi chú Hình 1.7]",
    "",
    "**Ví dụ 7**",
    "a) Cho hai tập hợp $C = \\{2; 3; 4; 7\\}$ và $D = \\{-1; 2; 3; 4; 6\\}$. Hãy xác định tập hợp $C \\cup D$.",
    "b) Cho hai tập hợp $E = (-1; 2]$ và $F = [0; 3]$. Hãy xác định tập hợp $E \\cup F$.",
    "",
    "**Giải**",
    "a) Hợp của hai tập hợp $C$ và $D$ là $C \\cup D = \\{-1; 2; 3; 4; 6; 7\\}$. [Hình ảnh: Biểu đồ Ven cho tập C và D, phần giao là {2, 4, 3}, phần chỉ thuộc C là 7, phần chỉ thuộc D là -1, 6. Ghi chú Hình 1.8]",
    "b) Hợp của hai tập hợp $E$ và $F$ là $E \\cup F = (-1; 3]$.",
    "",
    "**Ví dụ 8.** Trở lại câu hỏi trong *tình huống mở đầu*. Gọi $A$ là tập hợp những thành viên tham gia Chuyên đề 1, $B$ là tập hợp những thành viên tham gia Chuyên đề 2.",
    "Ta có: $A \\cup B = \\{\\text{Nam; Hương; Chi; Tú; Bình; Ngân; Khánh; Hân; Hiền; Lam}\\}$.",
    "Tập $A \\cup B$ có 10 phần tử, tức là có 10 thành viên tham gia một hoặc hai chuyên đề.",
    "Số thành viên vắng mặt trong cả hai chuyên đề là: $12 - 10 = 2$ (thành viên).",
    "",
    "**Luyện tập 6.** Hãy biểu diễn tập hợp $A \\cup B$ bằng biểu đồ Ven, với $A, B$ được cho trong HĐ1.",
    "",
    "17",
    "### c. Hiệu của hai tập hợp",
    "",
    "**HĐ9.** Trở lại *tình huống mở đầu*, hãy xác định tập hợp các thành viên chỉ tham gia Chuyên đề 1 mà không tham gia Chuyên đề 2.",
    "",
    "> - Hiệu của hai tập hợp $S$ và $T$ là tập hợp gồm các phần tử thuộc $S$ nhưng không thuộc $T$, kí hiệu là $S \\setminus T$.",
    ">   $S \\setminus T = \\{x | x \\in S \\text{ và } x \\notin T\\}$.",
    "> - Nếu $T \\subset S$ thì $S \\setminus T$ được gọi là **phần bù** của $T$ trong $S$, kí hiệu là $C_S T$.",
    "",
    "[Hình ảnh trên: Biểu đồ Ven của hiệu S \\ T, phần của S không giao với T được tô màu xanh dương. Ghi chú Hình 1.9]",
    "[Hình ảnh dưới: Biểu đồ Ven của phần bù $C_S T$, tập T nằm trọn trong S, phần của S bên ngoài T được tô màu xanh dương. Ghi chú Hình 1.10]",
    "",
    "*Chú ý.* $C_S S = \\emptyset$.",
    "",
    "**Ví dụ 9.** Cho các tập hợp: $D = \\{-2; 3; 5; 6\\}$; $E = \\{x | x \\text{ là số nguyên tố nhỏ hơn 10}\\}$; $X = \\{x | x \\text{ là số nguyên dương nhỏ hơn 10}\\}$.",
    "a) Tìm $D \\setminus E$ và $E \\setminus D$.",
    "b) $E$ có là tập con của $X$ không? Hãy tìm phần bù của $E$ trong $X$ (nếu có).",
    "",
    "**Giải**",
    "a) Ta có: $E = \\{2; 3; 5; 7\\}$.",
    "Do đó, $D \\setminus E = \\{-2; 6\\}$; $E \\setminus D = \\{2; 7\\}$.",
    "b) Ta có: $X = \\{1; 2; 3; 4; 5; 6; 7; 8; 9\\}$. Vậy $E$ là tập con của $X$.",
    "Phần bù của $E$ trong $X$ là $X \\setminus E = C_X E = \\{1; 4; 6; 8; 9\\}$.",
    "",
    "**Luyện tập 7.** Tìm phần bù của các tập hợp sau trong $\\mathbb{R}$:",
    "a) $(-\\infty; -2)$;           b) $[-5; +\\infty)$.",
    "",
    "**Vận dụng.** Lớp 10A có 24 bạn tham gia thi đấu bóng đá và cầu lông, trong đó có 16 bạn thi đấu bóng đá và 11 bạn thi đấu cầu lông. Giả sử các trận bóng đá và cầu lông không tổ chức đồng thời. Hỏi có bao nhiêu bạn lớp 10A tham gia thi đấu cả bóng đá và cầu lông?",
    "*Gợi ý.* Gọi $x$ là số bạn tham gia thi đấu cả bóng đá và cầu lông.",
    "[Hình ảnh: Biểu đồ Ven hai vòng tròn \"Bóng đá\" và \"Cầu lông\" giao nhau tại $x$. Phần \"Bóng đá\" có $16 - x$, phần \"Cầu lông\" có $11 - x$.]",
    "[Khung chú thích của robot: Ta có: $n(A \\cup B) = n(A) + n(B) - n(A \\cap B)$.]",
    "",
    "18",
    "## BÀI TẬP",
    "",
    "1.8. Gọi $X$ là tập hợp các quốc gia tiếp giáp với Việt Nam. Hãy liệt kê các phần tử của tập hợp $X$ và biểu diễn tập $X$ bằng biểu đồ Ven.",
    "",
    "1.9. Kí hiệu $E$ là tập hợp các quốc gia tại khu vực Đông Nam Á.",
    "a) Nêu ít nhất hai phần tử thuộc tập hợp $E$.",
    "b) Nêu ít nhất hai phần tử không thuộc tập hợp $E$.",
    "c) Liệt kê các phần tử thuộc tập hợp $E$. Tập hợp $E$ có bao nhiêu phần tử?",
    "",
    "1.10. Hãy viết tập hợp sau bằng cách nêu tính chất đặc trưng cho các phần tử của tập hợp:",
    "$A = \\{0; 4; 8; 12; 16\\}$.",
    "",
    "1.11. Trong các tập hợp sau, tập nào là tập rỗng?",
    "$A = \\{x \\in \\mathbb{R} | x^2 - 6 = 0\\}$;",
    "$B = \\{x \\in \\mathbb{Z} | x^2 - 6 = 0\\}$.",
    "",
    "1.12. Cho $X = \\{a; b\\}$. Các cách viết sau đúng hay sai? Giải thích kết luận đưa ra.",
    "a) $a \\subset X$;          b) $\\{a\\} \\subset X$;          c) $\\emptyset \\in X$.",
    "",
    "1.13. Cho $A = \\{2; 5\\}$, $B = \\{5; x\\}$, $C = \\{2; y\\}$. Tìm $x$ và $y$ để $A = B = C$.",
    "",
    "1.14. Cho $A = \\{x \\in \\mathbb{Z} | x < 4\\}$; $B = \\{x \\in \\mathbb{Z} | (5x - 3x^2)(x^2 + 2x - 3) = 0\\}$.",
    "a) Liệt kê các phần tử của hai tập hợp $A$ và $B$.",
    "b) Hãy xác định các tập hợp $A \\cap B, A \\cup B$ và $A \\setminus B$.",
    "",
    "1.15. Xác định các tập hợp sau và biểu diễn chúng trên trục số.",
    "a) $(-4; 1] \\cap [0; 3)$;",
    "b) $(0; 2] \\cup (-3; 1]$;",
    "c) $(-2; 1] \\cap (1; +\\infty)$;",
    "d) $\\mathbb{R} \\setminus (-\\infty; 3]$.",
    "",
    "1.16. Để phục vụ cho một hội nghị quốc tế, ban tổ chức huy động 35 người phiên dịch tiếng Anh, 30 người phiên dịch tiếng Pháp, trong đó có 16 người phiên dịch được cả tiếng Anh và tiếng Pháp. Hãy trả lời các câu hỏi sau:",
    "a) Ban tổ chức đã huy động bao nhiêu người phiên dịch cho hội nghị đó?",
    "b) Có bao nhiêu người chỉ phiên dịch được tiếng Anh?",
    "c) Có bao nhiêu người chỉ phiên dịch được tiếng Pháp?",
    "",
    "19"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'CH1_END', 'Bài tập cuối chương I', 21, 3, $JSON$
{
  "content": [
    "# BÀI TẬP CUỐI CHƯƠNG I",
    "",
    "## A – TRẮC NGHIỆM",
    "",
    "1.17. Câu nào sau đây không là mệnh đề?",
    "A. Tam giác đều là tam giác có ba cạnh bằng nhau.",
    "B. $3 < 1$.",
    "C. $4 - 5 = 1$.",
    "D. Bạn học giỏi quá!",
    "",
    "1.18. Cho định lí: \"Nếu hai tam giác bằng nhau thì diện tích của chúng bằng nhau\".",
    "Mệnh đề nào sau đây là đúng?",
    "A. Hai tam giác bằng nhau là điều kiện cần để diện tích của chúng bằng nhau.",
    "B. Hai tam giác bằng nhau là điều kiện cần và đủ để chúng có diện tích bằng nhau.",
    "C. Hai tam giác có diện tích bằng nhau là điều kiện đủ để chúng bằng nhau.",
    "D. Hai tam giác bằng nhau là điều kiện đủ để diện tích của chúng bằng nhau.",
    "",
    "1.19. Mệnh đề nào sau đây là đúng?",
    "A. $\\forall x \\in \\mathbb{R}, x^2 > 1 \\Rightarrow x > -1$.",
    "B. $\\forall x \\in \\mathbb{R}, x^2 > 1 \\Rightarrow x > 1$.",
    "C. $\\forall x \\in \\mathbb{R}, x > -1 \\Rightarrow x^2 > 1$.",
    "D. $\\forall x \\in \\mathbb{R}, x > 1 \\Rightarrow x^2 > 1$.",
    "",
    "1.20. Cho tập hợp $A = \\{a; b; c\\}$. Tập $A$ có tất cả bao nhiêu tập con?",
    "A. 4.",
    "B. 6.",
    "C. 8.",
    "D. 10.",
    "",
    "1.21. Cho các tập hợp $A, B$ được minh hoạ bằng biểu đồ Ven như hình bên. Phần tô màu xám trong hình là biểu diễn của tập hợp nào sau đây?",
    "A. $A \\cap B$.",
    "B. $A \\setminus B$.",
    "C. $A \\cup B$.",
    "D. $B \\setminus A$.",
    "[Hình ảnh: Biểu đồ Ven hai vòng tròn A và B giao nhau, phần tô màu xám là phần của A và phần của B không nằm trong phần giao (hiệu đối xứng). Wait... The image shows the union? No, let me re-examine the image. Actually, the shaded part is the overlap (intersection). Wait, the image shows A and B intersecting. The intersection part is shaded gray. So it's A ∩ B. Wait, looking closely, the shading is in the intersection region.]",
    "",
    "## B – TỰ LUẬN",
    "",
    "1.22. Biểu diễn các tập hợp sau bằng biểu đồ Ven:",
    "a) $A = \\{0; 1; 2; 3\\}$;",
    "b) $B = \\{\\text{Lan; Huệ; Trang}\\}$.",
    "",
    "1.23. Phần không bị gạch trên trục số dưới đây biểu diễn tập hợp số nào?",
    "[Hình ảnh: Trục số thực, phần bên trái điểm -2 bị gạch (với ngoặc tròn quay sang phải tại -2), phần bên phải điểm 5 bị gạch (với ngoặc vuông quay sang trái tại 5). Tức là phần không bị gạch là khoảng $(-2; 5]$.]",
    "",
    "20",
    "1.24. Cho $A = \\{x \\in \\mathbb{N} | x < 7\\}; B = \\{1; 2; 3; 6; 7; 8\\}$. Xác định các tập hợp sau:",
    "$A \\cup B; A \\cap B; A \\setminus B$.",
    "",
    "1.25. Cho hai tập hợp $A = [-2; 3]$ và $B = (1; +\\infty)$. Xác định các tập hợp sau:",
    "$A \\cap B; B \\setminus A \\text{ và } C_{\\mathbb{R}}B$.",
    "",
    "1.26. Xác định các tập hợp sau và biểu diễn chúng trên trục số.",
    "a) $(-\\infty; 1) \\cap (0; +\\infty)$;",
    "b) $(4; 7] \\cup (-1; 5)$;",
    "c) $(4; 7] \\setminus (-3; 5]$.",
    "",
    "1.27. Một cuộc khảo sát về khách du lịch thăm vịnh Hạ Long cho thấy trong 1 410 khách du lịch được phỏng vấn có 789 khách du lịch đến thăm động Thiên Cung, 690 khách du lịch đến đảo Titop. Toàn bộ khách được phỏng vấn đã đến ít nhất một trong hai địa điểm trên. Hỏi có bao nhiêu khách du lịch vừa đến thăm động Thiên Cung vừa đến thăm đảo Titop ở vịnh Hạ Long?",
    "",
    "**Em có biết?**",
    "Đảo Titop nằm trong vịnh Hạ Long, tỉnh Quảng Ninh, cách cảng tàu du lịch Bãi Cháy khoảng 7 – 8 km về phía đông nam. Dưới chân đảo là một bãi tắm có hình vầng trăng ôm trọn lấy chân đảo, bãi cát tuy nhỏ nhưng rất thoáng đãng và yên tĩnh, bốn mùa nước sạch và trong xanh. Ngày 22-11-1962, Chủ tịch Hồ Chí Minh cùng nhà du hành vũ trụ người Liên Xô G.Titop lên thăm đảo. Để ghi dấu kỉ niệm chuyến đi đó, Chủ tịch Hồ Chí Minh đã đặt tên cho đảo là đảo Titop.",
    "(Theo *tuoitre.vn*)",
    "[Hình ảnh: Ảnh chụp từ trên cao bãi tắm và đảo Titop, vịnh Hạ Long với bãi biển cát trắng uốn cong, tàu thuyền xung quanh.]",
    "Đảo Titop, vịnh Hạ Long",
    "",
    "21"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B3', 'Bài 3. Bất phương trình bậc nhất hai ẩn', 23, 4, $JSON$
{
  "content": [
    "# CHƯƠNG II",
    "# BẤT PHƯƠNG TRÌNH VÀ HỆ BẤT PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN",
    "",
    "Các bất phương trình bậc nhất hai ẩn và hệ bất phương trình bậc nhất hai ẩn xuất hiện trong nhiều bài toán kinh tế, như là những ràng buộc trong các bài toán sản xuất, bài toán phân phối hàng hoá,... Chương này cung cấp cách biểu diễn miền nghiệm của các bất phương trình và hệ bất phương trình bậc nhất hai ẩn trên mặt phẳng toạ độ.",
    "",
    "[Hình ảnh: Nửa mặt phẳng được biểu diễn trên hệ trục toạ độ Oxy, giới hạn bởi đường thẳng $ax + by = c$. Phần tô màu xanh ở nửa dưới mặt phẳng.]",
    "",
    "# Bài 3 BẤT PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN",
    "",
    "**THUẬT NGỮ**",
    "- Bất phương trình bậc nhất hai ẩn",
    "- Miền nghiệm của bất phương trình bậc nhất hai ẩn",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Nhận biết bất phương trình bậc nhất hai ẩn.",
    "- Biết biểu diễn miền nghiệm của bất phương trình bậc nhất hai ẩn trên mặt phẳng toạ độ.",
    "- Vận dụng kiến thức về bất phương trình bậc nhất hai ẩn vào giải quyết bài toán thực tiễn.",
    "",
    "Nhân ngày Quốc tế Thiếu nhi 1-6, một rạp chiếu phim phục vụ các khán giả một bộ phim hoạt hình. Vé được bán ra có hai loại:",
    "Loại 1 (dành cho trẻ từ 6-13 tuổi): 50 000 đồng/vé;",
    "Loại 2 (dành cho người trên 13 tuổi): 100 000 đồng/vé.",
    "Người ta tính toán rằng, để không phải bù lỗ thì số tiền vé thu được ở rạp chiếu phim này phải đạt tối thiểu 20 triệu đồng.",
    "Hỏi số lượng vé bán được trong những trường hợp nào thì rạp chiếu phim phải bù lỗ?",
    "",
    "[Hình ảnh: Khán giả đang xem phim trong rạp chiếu phim]",
    "",
    "## 1. BẤT PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN",
    "",
    "**HĐ1.** Trong *tình huống mở đầu*, gọi $x$ là số vé loại 1 bán được và $y$ là số vé loại 2 bán được. Viết biểu thức tính số tiền bán vé thu được (đơn vị nghìn đồng) ở rạp chiếu phim đó theo $x$ và $y$.",
    "a) Các số nguyên không âm $x$ và $y$ phải thoả mãn điều kiện gì để số tiền bán vé thu được đạt tối thiểu 20 triệu đồng?",
    "b) Nếu số tiền bán vé thu được nhỏ hơn 20 triệu đồng thì $x$ và $y$ thoả mãn điều kiện gì?",
    "",
    "22",
    "Mỗi hệ thức liên hệ giữa $x$ và $y$ thu được trong HĐ1a và HĐ1b được gọi là một *bất phương trình bậc nhất hai ẩn*.",
    "",
    "> **Bất phương trình bậc nhất hai ẩn $x, y$** có dạng tổng quát là:",
    "> $ax + by \\le c$ ($ax + by \\ge c$, $ax + by < c$, $ax + by > c$)",
    "> trong đó $a, b, c$ là những số thực đã cho, $a$ và $b$ không đồng thời bằng 0, $x$ và $y$ là các ẩn số.",
    "",
    "**Ví dụ 1.** Bất phương trình nào sau đây là bất phương trình bậc nhất hai ẩn?",
    "$2x + 3y < 1$;             $2x^2 + 3y < 1$.",
    "",
    "**Giải**",
    "Bất phương trình $2x + 3y < 1$ là bất phương trình bậc nhất hai ẩn.",
    "Bất phương trình $2x^2 + 3y < 1$ không phải là bất phương trình bậc nhất hai ẩn vì chứa $x^2$.",
    "",
    "**HĐ2.** Cặp số $(x; y) = (100; 100)$ thoả mãn bất phương trình bậc nhất hai ẩn nào trong hai bất phương trình thu được ở HĐ1? Từ đó cho biết rạp chiếu phim có phải bù lỗ hay không nếu bán được 100 vé loại 1 và 100 vé loại 2.",
    "Trả lời câu hỏi tương tự với cặp số $(x; y) = (150; 150)$.",
    "",
    "> Cặp số $(x_0; y_0)$ được gọi là một **nghiệm** của bất phương trình bậc nhất hai ẩn $ax + by \\le c$ nếu bất đẳng thức $ax_0 + by_0 \\le c$ đúng.",
    "",
    "**Ví dụ 2.** Cho bất phương trình bậc nhất hai ẩn $x + 2y > 5$. Cặp số nào sau đây là một nghiệm của bất phương trình bậc nhất hai ẩn trên?",
    "a) $(x; y) = (3; 4)$;           b) $(x; y) = (0; -1)$.",
    "",
    "**Giải**",
    "a) Vì $3 + 2 \\cdot 4 = 11 > 5$ nên cặp số $(3; 4)$ là một nghiệm của bất phương trình đã cho.",
    "b) Vì $0 + 2 \\cdot (-1) = -2 < 5$ nên cặp số $(0; -1)$ không phải là một nghiệm của bất phương trình đã cho.",
    "",
    "**Luyện tập 1.** Cho bất phương trình bậc nhất hai ẩn $x + 2y \\ge 0$.",
    "a) Hãy chỉ ra ít nhất hai nghiệm của bất phương trình trên.",
    "b) Với $y = 0$, có bao nhiêu giá trị của $x$ thoả mãn bất phương trình đã cho?",
    "*Nhận xét.* Bất phương trình bậc nhất hai ẩn luôn có vô số nghiệm.",
    "",
    "## 2. BIỂU DIỄN MIỀN NGHIỆM CỦA BẤT PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN TRÊN MẶT PHẲNG TOẠ ĐỘ",
    "",
    "**HĐ3.** Cho đường thẳng $d: 2x - y = 4$ trên mặt phẳng toạ độ $Oxy$ (H.2.1). Đường thẳng này chia mặt phẳng thành hai nửa mặt phẳng.",
    "a) Các điểm $O(0; 0)$, $A(-1; 3)$ và $B(-2; -2)$ có thuộc cùng một nửa mặt phẳng bờ là đường thẳng $d$ không?",
    "Tính giá trị của biểu thức $2x - y$ tại các điểm đó và so sánh với 4.",
    "b) Trả lời câu hỏi tương tự như câu a với các điểm $C(3; 1)$, $D(4; -1)$.",
    "",
    "[Hình ảnh: Đồ thị hàm số trên mặt phẳng toạ độ Oxy. Đường thẳng d đi qua các điểm có toạ độ (2, 0) và (0, -4). Các điểm A(-1; 3), B(-2; -2), O(0; 0) nằm cùng một phía so với đường thẳng d. Điểm C(3; 1), D(4; -1) nằm ở phía còn lại. Ghi chú Hình 2.1]",
    "",
    "23",
    "> - Trong mặt phẳng toạ độ $Oxy$, tập hợp các điểm có toạ độ là nghiệm của bất phương trình $ax + by \\le c$ được gọi là **miền nghiệm** của bất phương trình đó.",
    "> - Người ta chứng minh được rằng đường thẳng $d$ có phương trình $ax + by = c$ chia mặt phẳng toạ độ $Oxy$ thành hai nửa mặt phẳng bờ $d$:",
    ">   - Một nửa mặt phẳng (không kể bờ $d$) gồm các điểm có toạ độ $(x; y)$ thoả mãn $ax + by > c$;",
    ">   - Nửa mặt phẳng còn lại (không kể bờ $d$) gồm các điểm có toạ độ $(x; y)$ thoả mãn $ax + by < c$.",
    "> Bờ $d$ gồm các điểm có toạ độ $(x; y)$ thoả mãn $ax + by = c$.",
    "",
    "**Ví dụ 3.** Biểu diễn miền nghiệm của bất phương trình $x + y \\ge 100$ trên mặt phẳng toạ độ.",
    "",
    "**Giải** (H.2.2)",
    "Ta biểu diễn miền nghiệm của bất phương trình bậc nhất hai ẩn $x + y \\ge 100$ như sau:",
    "*Bước 1.* Vẽ đường thẳng $d: x + y = 100$ trên mặt phẳng toạ độ $Oxy$.",
    "*Bước 2.* Lấy một điểm bất kì không thuộc $d$ trên mặt phẳng rồi thay vào biểu thức $x + y$. Chẳng hạn, lấy $O(0; 0)$, ta có: $0 + 0 < 100$.",
    "Do đó miền nghiệm của bất phương trình đã cho là nửa mặt phẳng bờ $d$ không chứa gốc toạ độ (miền không bị gạch).",
    "",
    "[Hình ảnh: Đồ thị mặt phẳng toạ độ Oxy. Đường thẳng $d: x + y = 100$ đi qua các điểm (100, 0) và (0, 100). Vùng chứa gốc toạ độ O(0, 0) bị gạch chéo. Vùng không bị gạch là miền nghiệm. Ghi chú Hình 2.2]",
    "",
    "> **Cách biểu diễn miền nghiệm của bất phương trình bậc nhất hai ẩn $ax + by \\le c$.**",
    "> - Vẽ đường thẳng $d: ax + by = c$ trên mặt phẳng toạ độ $Oxy$.",
    "> - Lấy một điểm $M_0(x_0; y_0)$ không thuộc $d$.",
    "> - Tính $ax_0 + by_0$ và so sánh với $c$.",
    "> - Nếu $ax_0 + by_0 < c$ thì nửa mặt phẳng bờ $d$ chứa $M_0$ là miền nghiệm của bất phương trình. Nếu $ax_0 + by_0 > c$ thì nửa mặt phẳng bờ $d$ không chứa $M_0$ là miền nghiệm của bất phương trình.",
    "",
    "*(Khung chú thích:",
    "- Nếu $c \\neq 0$, ta thường chọn $M_0$ chính là gốc toạ độ.",
    "- Nếu $c = 0$, ta thường chọn $M_0$ có toạ độ $(1; 0)$ hoặc $(0; 1)$.)*",
    "",
    "**Ví dụ 4.** Biểu diễn miền nghiệm của bất phương trình $5x - 7y \\le 0$ trên mặt phẳng toạ độ.",
    "",
    "**Giải** (H.2.3)",
    "*Bước 1.* Vẽ đường thẳng $d: 5x - 7y = 0$ trên mặt phẳng toạ độ $Oxy$.",
    "*Bước 2.* Lấy điểm $M_0(0; 1)$ không thuộc $d$ và thay $x = 0, y = 1$ vào biểu thức $5x - 7y$ ta được: $5 \\cdot 0 - 7 \\cdot 1 = -7 < 0$.",
    "Do đó miền nghiệm của bất phương trình là nửa mặt phẳng bờ $d$ chứa điểm $M_0$ (miền không bị gạch).",
    "",
    "*Chú ý.* Miền nghiệm của bất phương trình $ax + by < c$ là miền nghiệm của bất phương trình $ax + by \\le c$ bỏ đi đường thẳng $ax + by = c$ và được biểu diễn bởi đường thẳng bằng nét đứt.",
    "",
    "[Hình ảnh: Đồ thị mặt phẳng toạ độ Oxy. Đường thẳng $d: 5x - 7y = 0$ nét đứt đi qua gốc toạ độ. Điểm $M_0(0; 1)$ nằm ở nửa trên đường thẳng. Nửa dưới đường thẳng bị gạch chéo. Ghi chú Hình 2.3]",
    "",
    "**Luyện tập 2.** Biểu diễn miền nghiệm của bất phương trình $2x + y < 200$ trên mặt phẳng toạ độ.",
    "",
    "24",
    "**Ví dụ 5.** Giải bài toán ở *tình huống mở đầu*.",
    "**Giải**",
    "Gọi $x$ là số lượng vé loại 1 bán được ($x \\in \\mathbb{N}$) và $y$ là số lượng vé loại 2 bán được ($y \\in \\mathbb{N}$) thì số tiền bán vé thu được là $50x + 100y$ (nghìn đồng). Người ta sẽ phải bù lỗ trong trường hợp số tiền bán vé nhỏ hơn 20 triệu đồng, tức là: $50x + 100y < 20~000$ hay $x + 2y < 400$.",
    "Như vậy, việc giải quyết bài toán mở đầu dẫn đến việc đi tìm miền nghiệm của bất phương trình $x + 2y < 400$.",
    "Miền nghiệm của bất phương trình bậc nhất hai ẩn này được xác định như sau:",
    "- Vẽ đường thẳng $d: x + 2y = 400$.",
    "- Ta lấy gốc toạ độ $O(0; 0)$ và tính $0 + 2 \\cdot 0 = 0 < 400$.",
    "Do đó, miền nghiệm của bất phương trình là nửa mặt phẳng bờ $d$ chứa gốc toạ độ không kể đường thẳng $d$ (H.2.4).",
    "Vậy, nếu bán được số vé loại 1 là $x$ và số vé loại 2 là $y$ mà điểm $(x; y)$ nằm trong miền tam giác $OAB$ không kể cạnh $AB$ thì rạp chiếu phim sẽ phải bù lỗ.",
    "Nếu điểm $(x; y)$ nằm trên đoạn thẳng $AB$ thì rạp chiếu phim hoà vốn.",
    "",
    "[Hình ảnh: Đồ thị trục toạ độ Oxy. Đường thẳng nét đứt $x + 2y = 400$ cắt trục tung tại A(0, 200) và trục hoành tại B(400, 0). Vùng nửa mặt phẳng phía trên đường thẳng bị gạch chéo. Ghi chú Hình 2.4]",
    "*(Khung chú thích: Miền tam giác gồm các điểm bên trong và các điểm trên ba cạnh của tam giác.)*",
    "",
    "*Nhận xét*",
    "- Nếu bán được 150 vé loại 1 và 150 vé loại 2 thì rạp chiếu phim có lãi.",
    "- Nếu bán được 200 vé loại 1 và 100 vé loại 2 thì rạp chiếu phim hoà vốn.",
    "- Nếu bán được 100 vé loại 1 và 100 vé loại 2 thì rạp chiếu phim phải bù lỗ.",
    "",
    "**Vận dụng.** Một công ty viễn thông tính phí 1 nghìn đồng mỗi phút gọi nội mạng và 2 nghìn đồng mỗi phút gọi ngoại mạng. Em có thể sử dụng bao nhiêu phút gọi nội mạng và bao nhiêu phút gọi ngoại mạng trong một tháng nếu em muốn số tiền phải trả ít hơn 200 nghìn đồng?",
    "",
    "## BÀI TẬP",
    "",
    "2.1. Bất phương trình nào sau đây là bất phương trình bậc nhất hai ẩn?",
    "a) $2x + 3y > 6$;          b) $2^2x + y \\le 0$;          c) $2x^2 - y \\ge 1$.",
    "",
    "2.2. Biểu diễn miền nghiệm của mỗi bất phương trình sau trên mặt phẳng toạ độ:",
    "a) $3x + 2y \\ge 300$;          b) $7x + 20y < 0$.",
    "",
    "2.3. Ông An muốn thuê một chiếc ô tô (có lái xe) trong một tuần. Giá thuê xe được cho như bảng sau:",
    "",
    "| | Phí cố định (nghìn đồng/ngày) | Phí tính theo quãng đường di chuyển (nghìn đồng/kilômét) |",
    "|---|---|---|",
    "| Từ thứ Hai đến thứ Sáu | 900 | 8 |",
    "| Thứ Bảy và Chủ nhật | 1 500 | 10 |",
    "",
    "a) Gọi $x$ và $y$ lần lượt là số kilômét ông An đi trong các ngày từ thứ Hai đến thứ Sáu và trong hai ngày cuối tuần. Viết bất phương trình biểu thị mối liên hệ giữa $x$ và $y$ sao cho tổng số tiền ông An phải trả không quá 14 triệu đồng.",
    "b) Biểu diễn miền nghiệm của bất phương trình ở câu a trên mặt phẳng toạ độ.",
    "",
    "25"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

