{
  "content": [
    "# Bài 4 HỆ BẤT PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN",
    "",
    "**THUẬT NGỮ**",
    "- Hệ bất phương trình bậc nhất hai ẩn",
    "- Miền nghiệm của hệ bất phương trình bậc nhất hai ẩn",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Nhận biết hệ bất phương trình bậc nhất hai ẩn.",
    "- Biết biểu diễn miền nghiệm của hệ bất phương trình bậc nhất hai ẩn trên mặt phẳng toạ độ.",
    "- Vận dụng kiến thức hệ bất phương trình bậc nhất hai ẩn vào giải quyết bài toán thực tiễn.",
    "",
    "Trong năm nay, một cửa hàng điện lạnh dự định kinh doanh hai loại máy điều hoà: điều hoà hai chiều và điều hoà một chiều với số vốn ban đầu không vượt quá 1,2 tỉ đồng.",
    "",
    "| | Điều hoà hai chiều | Điều hoà một chiều |",
    "|---|---|---|",
    "| Giá mua vào | 20 triệu đồng/1 máy | 10 triệu đồng/1 máy |",
    "| Lợi nhuận dự kiến | 3,5 triệu đồng/1 máy | 2 triệu đồng/1 máy |",
    "",
    "Cửa hàng ước tính rằng tổng nhu cầu của thị trường sẽ không vượt quá 100 máy cả hai loại. Nếu là chủ cửa hàng thì em cần đầu tư kinh doanh mỗi loại bao nhiêu máy để lợi nhuận thu được là lớn nhất?",
    "",
    "## 1. HỆ BẤT PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN",
    "",
    "**HĐ1.** Trong *tình huống mở đầu*, gọi $x$ và $y$ lần lượt là số máy điều hoà loại hai chiều và một chiều mà cửa hàng cần nhập. Tính số tiền vốn mà cửa hàng phải bỏ ra để nhập hai loại máy điều hoà theo $x$ và $y$.",
    "a) Do nhu cầu của thị trường không quá 100 máy nên $x$ và $y$ cần thoả mãn điều kiện gì?",
    "b) Vì số vốn mà chủ cửa hàng có thể đầu tư không vượt quá 1,2 tỉ đồng nên $x$ và $y$ phải thoả mãn điều kiện gì?",
    "c) Tính số tiền lãi mà cửa hàng dự kiến thu được theo $x$ và $y$.",
    "",
    "Như vậy, $x$ và $y$ trong HĐ1 phải thoả mãn một số bất phương trình bậc nhất hai ẩn.",
    "",
    "> - **Hệ bất phương trình bậc nhất hai ẩn** là một hệ gồm hai hay nhiều bất phương trình bậc nhất hai ẩn.",
    "> - Cặp số $(x_0; y_0)$ là **nghiệm** của một hệ bất phương trình bậc nhất hai ẩn khi $(x_0; y_0)$ đồng thời là nghiệm của tất cả các bất phương trình trong hệ đó.",
    "",
    "26",
    "**Ví dụ 1.** Cho hệ bất phương trình",
    "$\\begin{cases} x \\ge 0 \\\\ y \\ge 0 \\\\ x + y \\le 150. \\end{cases}$",
    "a) Hệ trên có phải là một hệ bất phương trình bậc nhất hai ẩn không?",
    "b) Kiểm tra xem cặp số $(x; y) = (0; 0)$ có phải là một nghiệm của hệ bất phương trình trên không.",
    "",
    "**Giải**",
    "a) Hệ bất phương trình đã cho là một hệ bất phương trình bậc nhất hai ẩn $x$ và $y$.",
    "b) Cặp số $(x; y) = (0; 0)$ thoả mãn cả ba bất phương trình của hệ nên nó là một nghiệm của hệ bất phương trình bậc nhất hai ẩn đã cho.",
    "",
    "**Luyện tập 1.** Trong *tình huống mở đầu*, gọi $x$ và $y$ lần lượt là số máy điều hoà loại hai chiều và một chiều mà cửa hàng cần nhập. Từ HĐ1, viết hệ bất phương trình hai ẩn $x, y$ và chỉ ra một nghiệm của hệ này.",
    "",
    "## 2. BIỂU DIỄN MIỀN NGHIỆM CỦA HỆ BẤT PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN TRÊN MẶT PHẲNG TOẠ ĐỘ",
    "",
    "**HĐ2.** Cho đường thẳng $d: x + y = 150$ trên mặt phẳng toạ độ $Oxy$. Đường thẳng này cắt hai trục toạ độ $Ox$ và $Oy$ tại hai điểm $A$ và $B$.",
    "a) Xác định các miền nghiệm $D_1, D_2, D_3$ của các bất phương trình tương ứng $x \\ge 0; y \\ge 0$ và $x + y \\le 150$.",
    "b) Miền tam giác $OAB$ (H.2.5) có phải là giao của các miền $D_1, D_2$ và $D_3$ hay không?",
    "c) Lấy một điểm trong tam giác $OAB$ (chẳng hạn điểm $(1; 2)$) hoặc một điểm trên cạnh nào đó của tam giác $OAB$ (chẳng hạn điểm $(1; 149)$) và kiểm tra xem toạ độ của các điểm đó có phải là nghiệm của hệ bất phương trình sau hay không:",
    "$\\begin{cases} x \\ge 0 \\\\ y \\ge 0 \\\\ x + y \\le 150. \\end{cases}$",
    "",
    "*(Khung chú thích: Phương trình của trục $Ox$ là $y = 0$ và phương trình của trục $Oy$ là $x = 0$.)*",
    "",
    "[Hình ảnh: Đồ thị trục toạ độ Oxy. Đường thẳng $d: x + y = 150$ đi qua các điểm A(150, 0) và B(0, 150). Phần mặt phẳng giới hạn bởi các tia Ox, Oy và đoạn AB (tạo thành tam giác OAB) được tô màu xanh dương nhạt. Ghi chú Hình 2.5]",
    "",
    "> - Trong mặt phẳng toạ độ, tập hợp các điểm có toạ độ là nghiệm của hệ bất phương trình bậc nhất hai ẩn là **miền nghiệm** của hệ bất phương trình đó.",
    "> - Miền nghiệm của hệ là giao các miền nghiệm của các bất phương trình trong hệ.",
    "",
    "**Ví dụ 2.** Biểu diễn miền nghiệm của hệ bất phương trình sau trên mặt phẳng toạ độ:",
    "$\\begin{cases} 7x + 4y \\le 2~400 \\\\ x + y \\le 100 \\\\ x \\ge 0. \\end{cases}$",
    "",
    "27",
    "**Giải** (H.2.6)",
    "*Bước 1.* Xác định miền nghiệm $D_1$ của bất phương trình $7x + 4y \\le 2~400$ và gạch bỏ miền còn lại.",
    "- Vẽ đường thẳng $d: 7x + 4y = 2~400$.",
    "- Vì $7 \\cdot 0 + 4 \\cdot 0 = 0 < 2~400$ nên toạ độ điểm $O(0; 0)$ thoả mãn bất phương trình $7x + 4y \\le 2~400$.",
    "Do đó, miền nghiệm $D_1$ của bất phương trình $7x + 4y \\le 2~400$ là nửa mặt phẳng bờ $d$ chứa gốc toạ độ $O$.",
    "",
    "*Bước 2.* Tương tự, miền nghiệm $D_2$ của bất phương trình $x + y \\le 100$ là nửa mặt phẳng bờ $d'$ chứa gốc toạ độ $O$.",
    "",
    "*Bước 3.* Tương tự, miền nghiệm $D_3$ của bất phương trình $x \\ge 0$ là nửa mặt phẳng bờ $Oy$ chứa điểm $(1; 0)$.",
    "Khi đó, miền không bị gạch chính là giao các miền nghiệm của các bất phương trình trong hệ. Vậy miền nghiệm của hệ là miền không bị gạch trong Hình 2.6.",
    "",
    "[Hình ảnh: Đồ thị mặt phẳng toạ độ Oxy. Trục tung y hướng lên, trục hoành x hướng sang phải.",
    "Có hai đường thẳng:",
    "- Đường d: $7x + 4y = 2400$, đi qua (0, 600) và (~342.8, 0).",
    "- Đường d': $x + y = 100$, đi qua (0, 100) và (100, 0).",
    "Miền x < 0 bị gạch.",
    "Miền nằm trên/bên phải d bị gạch.",
    "Miền nằm trên/bên phải d' bị gạch.",
    "Miền nghiệm là phần tư giác (gồm một phần thuộc y < 0) không bị gạch chứa gốc tọa độ.",
    "Ghi chú Hình 2.6]",
    "",
    "> Cách xác định miền nghiệm của một hệ bất phương trình bậc nhất hai ẩn:",
    "> - Trên cùng một mặt phẳng toạ độ, xác định miền nghiệm của mỗi bất phương trình bậc nhất hai ẩn trong hệ và gạch bỏ miền còn lại.",
    "> - Miền không bị gạch là miền nghiệm của hệ bất phương trình đã cho.",
    "",
    "*Chú ý.* Nếu trong HĐ2, hệ được thay bởi $\\begin{cases} x \\ge 0 \\\\ y \\ge 0 \\\\ x + y < 150 \\end{cases}$ thì miền nghiệm sẽ là miền tam giác $OAB$ bỏ đi cạnh $AB$.",
    "",
    "**Luyện tập 2.** Biểu diễn miền nghiệm của hệ bất phương trình bậc nhất hai ẩn sau trên mặt phẳng toạ độ:",
    "$\\begin{cases} x \\ge 0 \\\\ y > 0 \\\\ x + y \\le 100 \\\\ 2x + y < 120. \\end{cases}$",
    "",
    "## 3. ỨNG DỤNG CỦA HỆ BẤT PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN",
    "",
    "**HĐ3.** Xét biểu thức $F(x; y) = 2x + 3y$ với $(x; y)$ thuộc miền tam giác $OAB$ ở HĐ2. Toạ độ ba đỉnh là $O(0; 0)$, $A(150; 0)$ và $B(0; 150)$ (H.2.5).",
    "a) Tính giá trị của biểu thức $F(x; y)$ tại mỗi đỉnh $O, A$ và $B$.",
    "b) Nêu nhận xét về dấu của hoành độ $x$ và tung độ $y$ của điểm $(x; y)$ nằm trong miền tam giác $OAB$. Từ đó suy ra giá trị nhỏ nhất của $F(x; y)$ trên miền tam giác $OAB$.",
    "",
    "28",
    "c) Nêu nhận xét về tổng $x + y$ của điểm $(x; y)$ nằm trong miền tam giác $OAB$. Từ đó suy ra giá trị lớn nhất của $F(x; y)$ trên miền tam giác $OAB$.",
    "",
    "*Nhận xét.* Tổng quát, người ta chứng minh được rằng giá trị lớn nhất (hay nhỏ nhất) của biểu thức $F(x; y) = ax + by$, với $(x; y)$ là toạ độ các điểm thuộc miền đa giác $A_1A_2...A_n$, tức là các điểm nằm bên trong hay nằm trên các cạnh của đa giác, đạt được tại một trong các đỉnh của đa giác đó.",
    "",
    "**Ví dụ 3.** Giải bài toán ở *tình huống mở đầu*.",
    "",
    "**Giải**",
    "Giả sử cửa hàng cần nhập số máy điều hoà hai chiều là $x$ và số máy điều hoà một chiều là $y$. Khi đó ta có $x \\ge 0, y \\ge 0$.",
    "Vì nhu cầu của thị trường không quá 100 máy nên $x + y \\le 100$.",
    "Số tiền để nhập hai loại máy điều hoà với số lượng như trên là: $20x + 10y$ (triệu đồng).",
    "Số tiền tối đa để đầu tư cho hai loại máy là 1,2 tỉ đồng, nên ta có $20x + 10y \\le 1~200$ hay $2x + y \\le 120$.",
    "Từ đó ta thu được hệ bất phương trình bậc nhất hai ẩn sau:",
    "$\\begin{cases} x \\ge 0 \\\\ y \\ge 0 \\\\ x + y \\le 100 \\\\ 2x + y \\le 120. \\end{cases}$",
    "",
    "[Hình ảnh: Đồ thị toạ độ Oxy. Hai đường thẳng cắt nhau tạo miền tứ giác.",
    "Đường $2x + y = 120$ đi qua (0, 120) và (60, 0).",
    "Đường $x + y = 100$ đi qua (0, 100) và (100, 0).",
    "Miền nghiệm là tứ giác OABC với các đỉnh $O(0, 0), A(0, 100), B(20, 80), C(60, 0)$. Vùng này được tô màu xanh dương. Ghi chú Hình 2.7]",
    "",
    "Lợi nhuận thu được khi bán $x$ máy điều hoà hai chiều và $y$ máy điều hoà một chiều là $F(x; y) = 3,5x + 2y$.",
    "Ta cần tìm giá trị lớn nhất của $F(x; y)$ khi $(x; y)$ thoả mãn hệ bất phương trình trên.",
    "",
    "*Bước 1.* Xác định miền nghiệm của hệ bất phương trình trên.",
    "Miền nghiệm là miền tứ giác $OABC$ với toạ độ các đỉnh $O(0; 0), A(0; 100), B(20; 80)$ và $C(60; 0)$ (H.2.7).",
    "",
    "*(Khung chú thích của robot: Giá trị lớn nhất (hoặc nhỏ nhất) của $F(x; y)$ đạt tại một trong các đỉnh của tứ giác $OABC$.)*",
    "",
    "*Bước 2.* Tính giá trị của biểu thức $F$ tại các đỉnh của tứ giác này:",
    "$F(0; 0) = 0$, $F(0; 100) = 200$, $F(20; 80) = 230$, $F(60; 0) = 210$.",
    "*Bước 3.* So sánh các giá trị thu được của $F$ ở Bước 2, ta được giá trị lớn nhất cần tìm là $F(20; 80) = 230$.",
    "Vậy cửa hàng cần đầu tư kinh doanh 20 máy điều hoà hai chiều và 80 máy điều hoà một chiều để lợi nhuận thu được là lớn nhất.",
    "",
    "29"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'CH2_END', 'Bài tập cuối chương II', 31, 6, $JSON$
{
  "content": [
    "**Vận dụng.** Một cửa hàng có kế hoạch nhập về hai loại máy tính $A$ và $B$, giá mỗi chiếc lần lượt là 10 triệu đồng và 20 triệu đồng với số vốn ban đầu không vượt quá 4 tỉ đồng. Loại máy $A$ mang lại lợi nhuận 2,5 triệu đồng cho mỗi máy bán được và loại máy $B$ mang lại lợi nhuận là 4 triệu đồng cho mỗi máy bán được. Cửa hàng ước tính rằng tổng nhu cầu hằng tháng sẽ không vượt quá 250 máy. Giả sử trong một tháng cửa hàng cần nhập số máy tính loại $A$ là $x$ và số máy tính loại $B$ là $y$.",
    "a) Viết các bất phương trình biểu thị các điều kiện của bài toán thành một hệ bất phương trình rồi xác định miền nghiệm của hệ đó.",
    "b) Gọi $F$ (triệu đồng) là lợi nhuận mà cửa hàng thu được trong tháng đó khi bán $x$ máy tính loại $A$ và $y$ máy tính loại $B$. Hãy biểu diễn $F$ theo $x$ và $y$.",
    "c) Tìm số lượng máy tính mỗi loại cửa hàng cần nhập về trong tháng đó để lợi nhuận thu được là lớn nhất.",
    "",
    "## BÀI TẬP",
    "",
    "2.4. Hệ bất phương trình nào sau đây là hệ bất phương trình bậc nhất hai ẩn?",
    "a) $\\begin{cases} x < 0 \\\\ y \\ge 0; \\end{cases}$          b) $\\begin{cases} x + y^2 < 0 \\\\ y - x > 1; \\end{cases}$          c) $\\begin{cases} x + y + z < 0 \\\\ y < 0; \\end{cases}$          d) $\\begin{cases} -2x + y < 3^2 \\\\ 4^2x + 3y < 1. \\end{cases}$",
    "",
    "2.5. Biểu diễn miền nghiệm của mỗi hệ bất phương trình sau trên mặt phẳng toạ độ:",
    "a) $\\begin{cases} y - x < -1 \\\\ x > 0 \\\\ y < 0; \\end{cases}$          b) $\\begin{cases} x \\ge 0 \\\\ y \\ge 0 \\\\ 2x + y \\le 4; \\end{cases}$          c) $\\begin{cases} x \\ge 0 \\\\ x + y > 5 \\\\ x - y < 0. \\end{cases}$",
    "",
    "2.6. Một gia đình cần ít nhất 900 đơn vị protein và 400 đơn vị lipid trong thức ăn mỗi ngày. Mỗi kilôgam thịt bò chứa 800 đơn vị protein và 200 đơn vị lipid. Mỗi kilôgam thịt lợn chứa 600 đơn vị protein và 400 đơn vị lipid. Biết rằng gia đình này chỉ mua nhiều nhất là 1,6 kg thịt bò và 1,1 kg thịt lợn; giá 1 kg thịt bò là 250 nghìn đồng; giá 1 kg thịt lợn là 160 nghìn đồng. Giả sử gia đình đó mua $x$ kilôgam thịt bò và $y$ kilôgam thịt lợn.",
    "a) Viết các bất phương trình biểu thị các điều kiện của bài toán thành một hệ bất phương trình rồi xác định miền nghiệm của hệ đó.",
    "b) Gọi $F$ (nghìn đồng) là số tiền phải trả cho $x$ kilôgam thịt bò và $y$ kilôgam thịt lợn. Hãy biểu diễn $F$ theo $x$ và $y$.",
    "c) Tìm số kilôgam thịt mỗi loại mà gia đình đó cần mua để chi phí là ít nhất.",
    "",
    "30",
    "2.11. Cho hệ bất phương trình $\\begin{cases} x - y < -3 \\\\ 2y \\ge -4 \\end{cases}$. Điểm nào sau đây thuộc miền nghiệm của hệ bất phương trình đã cho?",
    "A. $(0; 0)$.",
    "B. $(-2; 1)$.",
    "C. $(3; -1)$.",
    "D. $(-3; 1)$.",
    "",
    "## B – TỰ LUẬN",
    "",
    "2.12. Biểu diễn miền nghiệm của bất phương trình $\\frac{x + y}{2} \\ge \\frac{2x - y + 1}{3}$ trên mặt phẳng toạ độ.",
    "",
    "2.13. Biểu diễn miền nghiệm của hệ bất phương trình $\\begin{cases} x + y < 1 \\\\ 2x - y \\ge 3 \\end{cases}$ trên mặt phẳng toạ độ.",
    "",
    "2.14. Biểu diễn miền nghiệm của hệ bất phương trình $\\begin{cases} y - 2x \\le 2 \\\\ y \\le 4 \\\\ x \\le 5 \\\\ x + y \\ge -1 \\end{cases}$ trên mặt phẳng toạ độ.",
    "Từ đó tìm giá trị lớn nhất và giá trị nhỏ nhất của biểu thức $F(x; y) = -x - y$ với $(x; y)$ thoả mãn hệ trên.",
    "",
    "2.15. Bác An đầu tư 1,2 tỉ đồng vào ba loại trái phiếu: trái phiếu chính phủ với lãi suất 7% một năm, trái phiếu ngân hàng với lãi suất 8% một năm và trái phiếu doanh nghiệp rủi ro cao với lãi suất 12% một năm. Vì lí do giảm thuế, bác An muốn số tiền đầu tư trái phiếu chính phủ gấp ít nhất 3 lần số tiền đầu tư trái phiếu ngân hàng. Hơn nữa, để giảm thiểu rủi ro, bác An đầu tư không quá 200 triệu đồng cho trái phiếu doanh nghiệp. Hỏi bác An nên đầu tư mỗi loại trái phiếu bao nhiêu tiền để lợi nhuận thu được sau một năm là lớn nhất?",
    "",
    "2.16. Một công ty dự định chi tối đa 160 triệu đồng cho quảng cáo một sản phẩm mới trong một tháng trên các đài phát thanh và truyền hình. Biết cùng một thời lượng quảng cáo, số người mới quan tâm đến sản phẩm trên truyền hình gấp 8 lần trên đài phát thanh, tức là quảng cáo trên truyền hình có hiệu quả gấp 8 lần trên đài phát thanh.",
    "Đài phát thanh chỉ nhận các quảng cáo có tổng thời lượng trong một tháng tối đa là 900 giây với chi phí là 80 nghìn đồng/giây. Đài truyền hình chỉ nhận các quảng cáo có tổng thời lượng trong một tháng tối đa là 360 giây với chi phí là 400 nghìn đồng/giây.",
    "Công ty cần đặt thời gian quảng cáo trên các đài phát thanh và truyền hình như thế nào để hiệu quả nhất?",
    "*Gợi ý.* Nếu coi hiệu quả khi quảng cáo 1 giây trên đài phát thanh là 1 (đơn vị) thì hiệu quả khi quảng cáo 1 giây trên đài truyền hình là 8 (đơn vị). Khi đó hiệu quả quảng cáo $x$ (giây) trên đài phát thanh và $y$ (giây) trên truyền hình là $F(x; y) = x + 8y$. Ta cần tìm giá trị lớn nhất của hàm $F(x; y)$ với $x, y$ thoả mãn các điều kiện trong đề bài.",
    "",
    "32"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B5', 'Bài 5. Giá trị lượng giác của một góc từ 0° đến 180°', 33, 7, $JSON$
{
  "content": [
    "# CHƯƠNG III",
    "# HỆ THỨC LƯỢNG TRONG TAM GIÁC",
    "",
    "Lượng giác được phát triển từ nhu cầu tính toán góc và khoảng cách trong rất nhiều lĩnh vực như thiên văn học, lập bản đồ, bản vẽ thiết kế, khảo sát và tìm tầm bắn của pháo binh.",
    "Ở lớp 9, ta đã biết tỉ số lượng giác của một góc nhọn. Chương này mở rộng khái niệm đó cho một góc bất kì từ $0^\\circ$ đến $180^\\circ$.",
    "",
    "[Hình ảnh: Trái đất nhìn từ không gian với hai vệ tinh nhân tạo đang bay quanh quỹ đạo, liên lạc với nhau và với trạm mặt đất tạo thành các góc lượng giác. Nền ảnh là không gian vũ trụ.]",
    "",
    "# Bài 5 GIÁ TRỊ LƯỢNG GIÁC CỦA MỘT GÓC TỪ $0^\\circ$ ĐẾN $180^\\circ$",
    "",
    "**THUẬT NGỮ**",
    "- Giá trị lượng giác của một góc",
    "- Hai góc bù nhau",
    "- Nửa đường tròn đơn vị",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Nhận biết giá trị lượng giác của một góc từ $0^\\circ$ đến $180^\\circ$.",
    "- Giải thích hệ thức liên hệ giữa các giá trị lượng giác của hai góc phụ nhau, bù nhau.",
    "- Sử dụng máy tính cầm tay để tính các giá trị lượng giác của một góc.",
    "- Vận dụng giải một số bài toán có nội dung thực tiễn.",
    "",
    "$\\sin\\alpha = \\frac{b}{a}$          $\\cos\\alpha = \\frac{c}{a}$",
    "$\\tan\\alpha = \\frac{b}{c}$          $\\cot\\alpha = \\frac{c}{b}$",
    "",
    "[Hình ảnh: Tam giác ABC vuông tại A. Cạnh huyền BC có độ dài $a$, cạnh góc vuông AC có độ dài $b$, cạnh góc vuông AB có độ dài $c$. Góc B là góc $\\alpha$. Ghi chú Hình 3.1]",
    "",
    "[Hình ảnh: Bạn nữ đưa ra câu hỏi: Bạn đã biết tỉ số lượng giác của một góc nhọn. Đối với góc tù thì sao?]",
    "",
    "33",
    "## 1. GIÁ TRỊ LƯỢNG GIÁC CỦA MỘT GÓC",
    "",
    "Trong mặt phẳng toạ độ $Oxy$, nửa đường tròn tâm $O$, bán kính $R = 1$ nằm phía trên trục hoành (H.3.2) được gọi là **nửa đường tròn đơn vị**.",
    "Cho trước một góc $\\alpha$, $0^\\circ \\le \\alpha \\le 180^\\circ$. Khi đó, có duy nhất điểm $M(x_0; y_0)$ trên nửa đường tròn đơn vị nói trên để $\\widehat{xOM} = \\alpha$.",
    "",
    "[Hình ảnh: Hai đồ thị nửa đường tròn đơn vị trên mặt phẳng toạ độ Oxy.",
    "Hình bên trái: $\\alpha < 90^\\circ$, điểm M nằm ở góc phần tư thứ nhất, hoành độ $x_0$ dương, tung độ $y_0$ dương.",
    "Hình bên phải: $\\alpha > 90^\\circ$, điểm M nằm ở góc phần tư thứ hai, hoành độ $x_0$ âm, tung độ $y_0$ dương.",
    "Ghi chú Hình 3.2]",
    "",
    "**HĐ1.** a) Nêu nhận xét về vị trí của điểm $M$ trên nửa đường tròn đơn vị trong mỗi trường hợp sau:",
    "$\\cdot~ \\alpha = 90^\\circ$;          $\\cdot~ \\alpha < 90^\\circ$;          $\\cdot~ \\alpha > 90^\\circ$.",
    "b) Khi $0^\\circ < \\alpha < 90^\\circ$, nêu mối quan hệ giữa $\\cos\\alpha$, $\\sin\\alpha$ với hoành độ và tung độ của điểm $M$.",
    "",
    "Mở rộng khái niệm tỉ số lượng giác của một góc nhọn cho một góc bất kì từ $0^\\circ$ đến $180^\\circ$, ta có định nghĩa sau:",
    "",
    "> Với mỗi góc $\\alpha$ ($0^\\circ \\le \\alpha \\le 180^\\circ$), gọi $M(x_0; y_0)$ là điểm trên nửa đường tròn đơn vị sao cho $\\widehat{xOM} = \\alpha$. Khi đó:",
    "> - **$\\sin$** của góc $\\alpha$ là tung độ $y_0$ của điểm $M$, được kí hiệu là $\\sin\\alpha$;",
    "> - **côsin** của góc $\\alpha$ là hoành độ $x_0$ của điểm $M$, được kí hiệu là $\\cos\\alpha$;",
    "> - Khi $\\alpha \\neq 90^\\circ$ (hay là $x_0 \\neq 0$), **tang** của $\\alpha$ là $\\frac{y_0}{x_0}$, được kí hiệu là $\\tan\\alpha$;",
    "> - Khi $\\alpha \\neq 0^\\circ$ và $\\alpha \\neq 180^\\circ$ (hay là $y_0 \\neq 0$), **côtang** của $\\alpha$ là $\\frac{x_0}{y_0}$, được kí hiệu là $\\cot\\alpha$.",
    "",
    "Từ định nghĩa trên, ta có:",
    "> $\\tan\\alpha = \\frac{\\sin\\alpha}{\\cos\\alpha}$ ($\\alpha \\neq 90^\\circ$);",
    "> $\\cot\\alpha = \\frac{\\cos\\alpha}{\\sin\\alpha}$ ($\\alpha \\neq 0^\\circ$ và $\\alpha \\neq 180^\\circ$);",
    "> $\\tan\\alpha = \\frac{1}{\\cot\\alpha}$ ($\\alpha \\notin \\{0^\\circ; 90^\\circ; 180^\\circ\\}$).",
    "",
    "Sau đây là bảng giá trị lượng giác (GTLG) của một số góc đặc biệt mà em nên nhớ.",
    "",
    "| $\\alpha$ | $0^\\circ$ | $30^\\circ$ | $45^\\circ$ | $60^\\circ$ | $90^\\circ$ | $180^\\circ$ |",
    "|---|---|---|---|---|---|---|",
    "| $\\sin\\alpha$ | 0 | $\\frac{1}{2}$ | $\\frac{\\sqrt{2}}{2}$ | $\\frac{\\sqrt{3}}{2}$ | 1 | 0 |",
    "| $\\cos\\alpha$ | 1 | $\\frac{\\sqrt{3}}{2}$ | $\\frac{\\sqrt{2}}{2}$ | $\\frac{1}{2}$ | 0 | $-1$ |",
    "| $\\tan\\alpha$ | 0 | $\\frac{\\sqrt{3}}{3}$ | 1 | $\\sqrt{3}$ | $||$ | 0 |",
    "| $\\cot\\alpha$ | $||$ | $\\sqrt{3}$ | 1 | $\\frac{\\sqrt{3}}{3}$ | 0 | $||$ |",
    "*Bảng 3.1*",
    "",
    "*(Khung chú thích: Trong bảng, kí hiệu $||$ chỉ giá trị lượng giác tương ứng không xác định.)*",
    "[Hình ảnh: Robot giơ tay chỉ vào bảng]",
    "",
    "34",
    "**Ví dụ 1.** Tìm các giá trị lượng giác của góc $135^\\circ$.",
    "",
    "**Giải** (H.3.3)",
    "Gọi $M$ là điểm trên nửa đường tròn đơn vị sao cho $\\widehat{xOM} = 135^\\circ$. Gọi $N, P$ tương ứng là hình chiếu vuông góc của $M$ lên các trục $Ox, Oy$.",
    "Vì $\\widehat{xOM} = 135^\\circ$ nên $\\widehat{MON} = 45^\\circ$, $\\widehat{MOP} = 45^\\circ$. Vậy các tam giác $MON$, $MOP$ là vuông cân với cạnh huyền $OM = 1$.",
    "Từ đó, ta có $ON = OP = \\frac{\\sqrt{2}}{2}$. Mặt khác, điểm $M$ nằm bên trái trục tung nên có toạ độ là $\\left(-\\frac{\\sqrt{2}}{2}; \\frac{\\sqrt{2}}{2}\\right)$.",
    "Theo định nghĩa, ta có:",
    "$\\sin 135^\\circ = \\frac{\\sqrt{2}}{2}$;          $\\cos 135^\\circ = -\\frac{\\sqrt{2}}{2}$;",
    "$\\tan 135^\\circ = -1$;          $\\cot 135^\\circ = -1$.",
    "",
    "[Hình ảnh: Đồ thị nửa đường tròn đơn vị, góc xOM = 135 độ. Hình chiếu của M xuống trục hoành là N, vuông góc trục tung là P. Tam giác MON vuông cân tại N. Ghi chú Hình 3.3]",
    "[Hình ảnh: Đồ thị nửa đường tròn đơn vị cho góc xOM = 120 độ. Hình chiếu của M xuống trục hoành là N, vuông góc trục tung là P. Ghi chú Hình 3.4]",
    "",
    "**Luyện tập 1.** Tìm các giá trị lượng giác của góc $120^\\circ$ (H.3.4).",
    "",
    "Ta có thể sử dụng máy tính cầm tay để tính (đúng hoặc gần đúng) các giá trị lượng giác của một góc và tính góc khi biết giá trị lượng giác của góc đó.",
    "Chẳng hạn, với một loại máy tính cầm tay, sau khi mở máy ta bấm phím `SHIFT` `MODE` (SETUP) rồi bấm phím `3` để chọn đơn vị đo góc là \"độ\". Sau đó tính giá trị lượng giác của góc hoặc tính góc khi biết giá trị lượng giác của góc đó.",
    "- Tính giá trị lượng giác của một số góc:",
    "",
    "| Tính | Bấm phím | Kết quả |",
    "|---|---|---|",
    "| $\\sin 48^\\circ 50' 40''$ | `sin` `4` `8` `°'\"` `5` `0` `°'\"` `4` `0` `°'\"` `=` | $\\sin 48^\\circ 50' 40'' \\approx 0,7529256291$ |",
    "| $\\cos 112^\\circ 12' 45''$ | `cos` `1` `1` `2` `°'\"` `1` `2` `°'\"` `4` `5` `°'\"` `=` | $\\cos 112^\\circ 12' 45'' \\approx -0,3780427715$ |",
    "| $\\tan 15^\\circ$ | `tan` `1` `5` `=` | $\\tan 15^\\circ = 2 - \\sqrt{3}$ |",
    "",
    "[Hình ảnh: Một chiếc máy tính cầm tay khoa học CASIO]",
    "",
    "- Tìm góc khi biết một giá trị lượng giác của góc đó:",
    "",
    "| Tìm $x$, biết | Bấm phím | Kết quả |",
    "|---|---|---|",
    "| $\\sin x = 0,3456$ | `SHIFT` `sin` ($\\sin^{-1}$) `0` `.` `3` `4` `5` `6` `=` `°'\"` | $x \\approx 20^\\circ 13' 7''$ |",
    "",
    "*Chú ý*",
    "- Khi tìm $x$ biết $\\sin x$, máy tính chỉ đưa ra giá trị $x \\le 90^\\circ$.",
    "- Muốn tìm $x$ khi biết $\\cos x, \\tan x$, ta cũng làm tương tự như trên, chỉ thay phím `sin` tương ứng bởi phím `cos`, `tan`.",
    "",
    "35",
    "## 2. MỐI QUAN HỆ GIỮA CÁC GIÁ TRỊ LƯỢNG GIÁC CỦA HAI GÓC BÙ NHAU",
    "",
    "Ở lớp 9, em đã biết mối quan hệ giữa tỉ số lượng giác của hai góc phụ nhau. Trong mục này, em hãy tìm mối quan hệ giữa các giá trị lượng giác của hai góc bù nhau.",
    "Đối với một góc $\\alpha$ tuỳ ý ($0^\\circ \\le \\alpha \\le 180^\\circ$), gọi $M, M'$ là hai điểm trên nửa đường tròn đơn vị tương ứng với hai góc bù nhau $\\alpha$ và $180^\\circ - \\alpha$ ($\\widehat{xOM} = \\alpha$, $\\widehat{xOM'} = 180^\\circ - \\alpha$) (H.3.5).",
    "",
    "**HĐ2.** Nêu nhận xét về vị trí của hai điểm $M, M'$ đối với trục $Oy$. Từ đó, nêu các mối quan hệ giữa $\\sin\\alpha$ và $\\sin(180^\\circ - \\alpha)$, giữa $\\cos\\alpha$ và $\\cos(180^\\circ - \\alpha)$.",
    "",
    "[Hình ảnh: Đồ thị nửa đường tròn đơn vị với hai điểm M, M' đối xứng nhau qua trục tung. Góc xOM là $\\alpha$, góc xOM' là $180^\\circ - \\alpha$. Hoành độ của M là $x_0$, của M' là $-x_0$. Tung độ của cả hai là $y_0$. Ghi chú Hình 3.5]",
    "",
    "> Đối với hai góc bù nhau, $\\alpha$ và $180^\\circ - \\alpha$, ta có:",
    "> - $\\sin(180^\\circ - \\alpha) = \\sin\\alpha$;",
    "> - $\\cos(180^\\circ - \\alpha) = -\\cos\\alpha$;",
    "> - $\\tan(180^\\circ - \\alpha) = -\\tan\\alpha$ ($\\alpha \\neq 90^\\circ$);",
    "> - $\\cot(180^\\circ - \\alpha) = -\\cot\\alpha$ ($0^\\circ < \\alpha < 180^\\circ$).",
    "",
    "**Ví dụ 2.** Tính các giá trị lượng giác của các góc $120^\\circ, 135^\\circ, 150^\\circ$.",
    "",
    "**Giải**",
    "Do các góc $120^\\circ, 135^\\circ, 150^\\circ$ tương ứng bù với các góc $60^\\circ, 45^\\circ, 30^\\circ$ nên từ *Bảng 3.1*, ta cũng có bảng các giá trị lượng giác sau:",
    "",
    "| $\\alpha$ | $120^\\circ$ | $135^\\circ$ | $150^\\circ$ |",
    "|---|---|---|---|",
    "| $\\sin\\alpha$ | $\\frac{\\sqrt{3}}{2}$ | $\\frac{\\sqrt{2}}{2}$ | $\\frac{1}{2}$ |",
    "| $\\cos\\alpha$ | $-\\frac{1}{2}$ | $-\\frac{\\sqrt{2}}{2}$ | $-\\frac{\\sqrt{3}}{2}$ |",
    "| $\\tan\\alpha$ | $-\\sqrt{3}$ | $-1$ | $-\\frac{\\sqrt{3}}{3}$ |",
    "| $\\cot\\alpha$ | $-\\frac{\\sqrt{3}}{3}$ | $-1$ | $-\\sqrt{3}$ |",
    "*Bảng 3.2*",
    "",
    "*(Khung chú thích của bạn nam: Hai góc bù nhau có sin bằng nhau; có côsin, tang, côtang đối nhau.)*",
    "",
    "**Luyện tập 2.** Trong Hình 3.6, hai điểm $M, N$ ứng với hai góc phụ nhau $\\alpha$ và $90^\\circ - \\alpha$ ($\\widehat{xOM} = \\alpha, \\widehat{xON} = 90^\\circ - \\alpha$).",
    "Chứng minh rằng $\\Delta MOP = \\Delta NOQ$.",
    "Từ đó nêu mối quan hệ giữa $\\cos\\alpha$ và $\\sin(90^\\circ - \\alpha)$.",
    "",
    "[Hình ảnh: Nửa đường tròn đơn vị góc phần tư thứ nhất. Điểm M có góc $\\alpha$. Điểm N có góc $90^\\circ - \\alpha$. Hình chiếu của M xuống Ox là P, hình chiếu của N xuống Oy là Q. Hai tam giác vuông OMP và ONQ. Ghi chú Hình 3.6]",
    "*(Khung chú thích của bạn nữ: Hai góc phụ nhau có sin góc này bằng côsin góc kia, tang góc này bằng côtang góc kia.)*",
    "",
    "36",
    "**Vận dụng.** Một chiếc đu quay có bán kính 75 m, tâm của vòng quay ở độ cao 90 m (H.3.7), thời gian thực hiện mỗi vòng quay của đu quay là 30 phút. Nếu một người vào cabin tại vị trí thấp nhất của vòng quay, thì sau 20 phút quay, người đó ở độ cao bao nhiêu mét?",
    "",
    "[Hình ảnh: Một chiếc đu quay khổng lồ nằm ven sông/hồ. Trục toạ độ Oxy được đặt với tâm O tại trục của đu quay. Tâm vòng quay nằm trên trục Oy. Chiều cao từ mặt đất lên trục vòng quay là 90m. Bán kính vòng quay là 75m. Vị trí thấp nhất nằm trên trục tung. Ghi chú Hình 3.7]",
    "",
    "## BÀI TẬP",
    "",
    "3.1. Không dùng máy tính cầm tay, tính giá trị của các biểu thức sau:",
    "a) $(2\\sin 30^\\circ + \\cos 135^\\circ - 3\\tan 150^\\circ) \\cdot (\\cos 180^\\circ - \\cot 60^\\circ)$;",
    "b) $\\sin^2 90^\\circ + \\cos^2 120^\\circ + \\cos^2 0^\\circ - \\tan^2 60^\\circ + \\cot^2 135^\\circ$;",
    "c) $\\cos 60^\\circ \\cdot \\sin 30^\\circ + \\cos^2 30^\\circ$.",
    "",
    "*Chú ý.* $\\sin^2\\alpha = (\\sin\\alpha)^2, \\cos^2\\alpha = (\\cos\\alpha)^2, \\tan^2\\alpha = (\\tan\\alpha)^2, \\cot^2\\alpha = (\\cot\\alpha)^2$.",
    "",
    "3.2. Đơn giản các biểu thức sau:",
    "a) $\\sin 100^\\circ + \\sin 80^\\circ + \\cos 16^\\circ + \\cos 164^\\circ$;",
    "b) $2\\sin(180^\\circ - \\alpha) \\cdot \\cot\\alpha - \\cos(180^\\circ - \\alpha) \\cdot \\tan\\alpha \\cdot \\cot(180^\\circ - \\alpha)$, với $0^\\circ < \\alpha < 90^\\circ$.",
    "",
    "3.3. Chứng minh các hệ thức sau:",
    "a) $\\sin^2\\alpha + \\cos^2\\alpha = 1$;",
    "b) $1 + \\tan^2\\alpha = \\frac{1}{\\cos^2\\alpha}$ ($\\alpha \\neq 90^\\circ$);",
    "c) $1 + \\cot^2\\alpha = \\frac{1}{\\sin^2\\alpha}$ ($0^\\circ < \\alpha < 180^\\circ$).",
    "",
    "3.4. Cho góc $\\alpha$ ($0^\\circ < \\alpha < 180^\\circ$) thoả mãn $\\tan\\alpha = 3$.",
    "Tính giá trị của biểu thức: $P = \\frac{2\\sin\\alpha - 3\\cos\\alpha}{3\\sin\\alpha + 2\\cos\\alpha}$.",
    "",
    "37"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B6', 'Bài 6. Hệ thức lượng trong tam giác', 38, 8, $JSON$
{
  "content": [
    "# Bài 6 HỆ THỨC LƯỢNG TRONG TAM GIÁC",
    "",
    "**THUẬT NGỮ**",
    "- Định lí côsin",
    "- Định lí sin",
    "- Công thức tính diện tích",
    "- Giải tam giác",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Hiểu định lí côsin, định lí sin, công thức tính diện tích tam giác.",
    "- Giải tam giác và giải quyết một số bài toán trong đo đạc.",
    "",
    "Ngắm Tháp Rùa từ bờ, chỉ với những dụng cụ đơn giản, dễ chuẩn bị, ta cũng có thể xác định được khoảng cách từ vị trí ta đứng tới Tháp Rùa. Em có biết vì sao?",
    "[Hình ảnh: Cảnh Tháp Rùa trên hồ Hoàn Kiếm, nhìn từ xa trên bờ.]",
    "Tháp Rùa nằm trong lòng hồ Hoàn Kiếm ở Thủ đô Hà Nội",
    "",
    "## 1. ĐỊNH LÍ CÔSIN",
    "",
    "**HĐ1.** Một tàu biển xuất phát từ cảng Vân Phong (Khánh Hoà) theo hướng đông với vận tốc 20 km/h. Sau khi đi được 1 giờ, tàu chuyển sang hướng đông nam rồi giữ nguyên vận tốc và đi tiếp.",
    "a) Hãy vẽ sơ đồ đường đi của tàu trong 1,5 giờ kể từ khi xuất phát (1 cm trên bản vẽ ứng với 1 cm trên bản vẽ... wait, it says \"1 km trên thực tế ứng với 1 cm trên bản vẽ\").",
    "b) Hãy đo trực tiếp trên bản vẽ và cho biết sau 1,5 giờ kể từ khi xuất phát, tàu cách cảng Vân Phong bao nhiêu kilômét (số đo gần đúng).",
    "c) Nếu sau khi đi được 2 giờ, tàu chuyển sang hướng nam (thay vì hướng đông nam) thì có thể dùng định lí Pythagore (Pi-ta-go) để tính chính xác các số đo trong câu b hay không?",
    "",
    "*(Khung chú thích của bạn nữ: Có hay không, một kiểu định lí Pythagore cho tam giác tuỳ ý?)*",
    "",
    "Đối với tam giác $ABC$, ta thường kí hiệu $A, B, C$ là các góc của tam giác tại đỉnh tương ứng; $a, b, c$ tương ứng là độ dài của các cạnh đối diện với đỉnh $A, B, C$; $p$ là nửa chu vi; $S$ là diện tích; $R, r$ tương ứng là bán kính đường tròn ngoại tiếp, nội tiếp tam giác.",
    "",
    "**HĐ2.** Trong Hình 3.8, hãy thực hiện các bước sau để thiết lập công thức tính $a$ theo $b, c$ và giá trị lượng giác của góc $A$.",
    "a) Tính $a^2$ theo $BD^2$ và $CD^2$.",
    "b) Tính $a^2$ theo $b, c$ và $DA$.",
    "c) Tính $DA$ theo $c$ và $\\cos A$.",
    "d) Chứng minh $a^2 = b^2 + c^2 - 2bc\\cos A$.",
    "",
    "[Hình ảnh: Tam giác ABC với cạnh BC = a, AC = b, AB = c. Kẻ đường cao CD từ C xuống AB. Ta có tam giác BCD vuông tại D. Góc A là góc $\\alpha$. Ghi chú Hình 3.8]",
    "",
    "38",
    "*Chú ý.* Người ta chứng minh được kết quả trong HĐ2d đối với cả các trường hợp góc $A$ là góc vuông hoặc nhọn.",
    "",
    "> **Định lí côsin.** Trong tam giác $ABC$:",
    "> $a^2 = b^2 + c^2 - 2bc\\cos A$,",
    "> $b^2 = c^2 + a^2 - 2ca\\cos B$,",
    "> $c^2 = a^2 + b^2 - 2ab\\cos C$.",
    "",
    "[Hình ảnh: Dấu chấm hỏi trong ô vuông đỏ] Định lí Pythagore có phải là một trường hợp đặc biệt của định lí côsin hay không?",
    "",
    "**Ví dụ 1.** Cho tam giác $ABC$ có $\\widehat{A} = 120^\\circ$ và $AB = 5$, $AC = 8$. Tính độ dài cạnh $BC$.",
    "",
    "**Giải** (H.3.9)",
    "Áp dụng định lí côsin cho tam giác $ABC$, ta có:",
    "$BC^2 = AB^2 + AC^2 - 2AB \\cdot AC \\cdot \\cos 120^\\circ$",
    "$= 5^2 + 8^2 - 2 \\cdot 5 \\cdot 8 \\cdot \\left(-\\frac{1}{2}\\right) = 129$. Vậy $BC = \\sqrt{129}$.",
    "",
    "[Hình ảnh: Tam giác ABC tù tại A. Cạnh c=5, b=8. Góc A = $120^\\circ$. Ghi chú Hình 3.9]",
    "",
    "**Khám phá.** Từ định lí côsin, hãy viết các công thức tính $\\cos A, \\cos B, \\cos C$ theo độ dài các cạnh $a, b, c$ của tam giác $ABC$.",
    "",
    "**Luyện tập 1.** Cho tam giác $ABC$ có $AB = 5, AC = 8$ và $\\widehat{A} = 45^\\circ$. Tính độ dài cạnh và độ lớn các góc còn lại của tam giác.",
    "",
    "**Trải nghiệm.** Vẽ một tam giác $ABC$, sau đó đo độ dài các cạnh, số đo góc $A$ và kiểm tra tính đúng đắn của định lí côsin tại đỉnh $A$ đối với tam giác đó.",
    "",
    "**Vận dụng 1.** Dùng định lí côsin, tính khoảng cách được đề cập trong HĐ1b.",
    "",
    "## 2. ĐỊNH LÍ SIN",
    "",
    "**HĐ3.** Trong mỗi hình dưới đây, hãy tính $R$ theo $a$ và $\\sin A$.",
    "",
    "[Hình ảnh:",
    "Hình a) Tam giác ABC nội tiếp đường tròn tâm O bán kính R. Góc A nhọn. Kẻ đường kính CM. Có góc A bằng góc M (chắn cung BC). Tam giác MBC vuông tại B.",
    "Hình b) Tam giác ABC tù tại A nội tiếp đường tròn tâm O. Đường kính kẻ từ C cắt đường tròn tại M.",
    "Ghi chú Hình 3.10]",
    "",
    "> **Định lí sin.** Trong tam giác $ABC$:",
    "> $\\frac{a}{\\sin A} = \\frac{b}{\\sin B} = \\frac{c}{\\sin C} = 2R$.",
    "",
    "39",
    "**Ví dụ 2.** Cho tam giác $ABC$ có $\\widehat{A} = 135^\\circ, \\widehat{C} = 15^\\circ$ và $b = 12$. Tính $a, c, R$ và số đo góc $B$.",
    "",
    "**Giải** (H.3.11)",
    "Ta có: $\\widehat{B} = 180^\\circ - (\\widehat{A} + \\widehat{C}) = 180^\\circ - (135^\\circ + 15^\\circ) = 30^\\circ$.",
    "Áp dụng định lí sin, ta có: $\\frac{a}{\\sin 135^\\circ} = \\frac{12}{\\sin 30^\\circ} = \\frac{c}{\\sin 15^\\circ} = 2R$.",
    "Suy ra $a = \\frac{12}{\\sin 30^\\circ} \\cdot \\sin 135^\\circ = 12\\sqrt{2}$; $c = \\frac{12}{\\sin 30^\\circ} \\cdot \\sin 15^\\circ = 24\\sin 15^\\circ (\\approx 6,21)$; $R = \\frac{12}{2\\sin 30^\\circ} = 12$.",
    "",
    "[Hình ảnh: Tam giác ABC tù tại A, góc A = $135^\\circ$, góc C = $15^\\circ$, cạnh AC = 12. Ghi chú Hình 3.11]",
    "",
    "**Luyện tập 2.** Cho tam giác $ABC$ có $b = 8, c = 5$ và $\\widehat{B} = 80^\\circ$. Tính số đo các góc, bán kính đường tròn ngoại tiếp và độ dài cạnh còn lại của tam giác.",
    "",
    "## 3. GIẢI TAM GIÁC VÀ ỨNG DỤNG THỰC TẾ",
    "",
    "Việc tính độ dài các cạnh và số đo các góc của một tam giác khi biết một số yếu tố của tam giác đó được gọi là **giải tam giác**.",
    "",
    "**Ví dụ 3.** Giải tam giác $ABC$, biết $c = 14, \\widehat{A} = 60^\\circ, \\widehat{B} = 40^\\circ$.",
    "",
    "**Giải**",
    "Ta có $\\widehat{C} = 180^\\circ - (\\widehat{A} + \\widehat{B}) = 80^\\circ$.",
    "Áp dụng định lí sin, ta có: $\\frac{a}{\\sin 60^\\circ} = \\frac{b}{\\sin 40^\\circ} = \\frac{14}{\\sin 80^\\circ}$.",
    "Suy ra $a = \\frac{14\\sin 60^\\circ}{\\sin 80^\\circ} \\approx 12,31$; $b = \\frac{14\\sin 40^\\circ}{\\sin 80^\\circ} \\approx 9,14$.",
    "",
    "[Hình ảnh: Tam giác ABC nhọn, cạnh AB = 14, góc A = $60^\\circ$, góc B = $40^\\circ$. Ghi chú bên phải: 14, 60, 40]",
    "",
    "**Luyện tập 3.** Giải tam giác $ABC$, biết $b = 32, c = 45, \\widehat{A} = 87^\\circ$.",
    "",
    "*Chú ý.* Áp dụng các định lí côsin, sin và sử dụng máy tính cầm tay, ta có thể tính (gần đúng) các cạnh và các góc của một tam giác trong các trường hợp sau:",
    "- Biết hai cạnh và góc xen giữa;",
    "- Biết ba cạnh;",
    "- Biết một cạnh và hai góc kề.",
    "",
    "**Ví dụ 4.** Trở lại *tình huống mở đầu*, theo các bước sau, ta có thể tiến hành đo khoảng cách từ vị trí $A$ trên bờ hồ Hoàn Kiếm đến Tháp Rùa (H.3.12):",
    "*Bước 1.* Trên bờ, đặt một cọc tiêu tại vị trí $A$ và một cọc tiêu tại vị trí $B$ nào đó. Đo khoảng cách $AB$.",
    "*Bước 2.* Đứng tại $A$, ngắm Tháp Rùa và cọc tiêu $B$ để đo góc tạo bởi hai hướng ngắm đó.",
    "*Bước 3.* Đứng tại $B$, ngắm cọc tiêu $A$ và Tháp Rùa để đo góc tạo bởi hai hướng ngắm đó.",
    "*Bước 4.* Gọi $C$ là vị trí của Tháp Rùa. Áp dụng định lí sin cho tam giác $ABC$ để tính độ dài cạnh $AC$.",
    "",
    "[Hình ảnh: Ảnh chụp Tháp Rùa. Đè lên ảnh là các đường thẳng nối điểm A, B trên bờ với điểm C (Tháp Rùa). Khoảng cách AB được đánh dấu là có thể đo được. Ghi chú Hình 3.12]",
    "",
    "**Vận dụng 2.** Từ một khu vực có thể quan sát được hai đỉnh núi, ta có thể ngắm và đo để xác định khoảng cách giữa hai đỉnh núi đó. Hãy thảo luận để đưa ra các bước cho một cách đo.",
    "",
    "40",
    "## 4. CÔNG THỨC TÍNH DIỆN TÍCH TAM GIÁC",
    "",
    "Ta đã biết tính diện tích một tam giác theo chiều cao và độ dài cạnh đáy tương ứng. Liệu còn công thức nào khác để tính diện tích tam giác hay không?",
    "",
    "**HĐ4.** Cho tam giác $ABC$ với $I$ là tâm đường tròn nội tiếp tam giác.",
    "a) Nêu mối liên hệ giữa diện tích tam giác $ABC$ và diện tích các tam giác $IBC, ICA, IAB$.",
    "b) Tính diện tích tam giác $ABC$ theo $r, a, b, c$.",
    "",
    "> Công thức tính diện tích tam giác $ABC$: $S = pr = \\frac{(a + b + c)r}{2}$.",
    "",
    "[Hình ảnh: Tam giác ABC có đường tròn nội tiếp tâm I, bán kính r tiếp xúc với ba cạnh. Ghi chú Hình 3.13]",
    "",
    "**HĐ5.** Cho tam giác $ABC$ với đường cao $BD$.",
    "a) Biểu thị $BD$ theo $AB$ và $\\sin A$.",
    "b) Viết công thức tính diện tích $S$ của tam giác $ABC$ theo $b, c, \\sin A$.",
    "",
    "[Hình ảnh: Tam giác ABC. Đường cao BD kẻ từ B xuống AC.",
    "Hình trái: Góc A nhọn, điểm D nằm trong đoạn AC.",
    "Hình phải: Góc A tù, điểm D nằm ngoài đoạn AC, kéo dài CA về phía A.",
    "Ghi chú Hình 3.14]",
    "",
    "> Công thức tính diện tích tam giác $ABC$: $S = \\frac{1}{2}bc\\sin A = \\frac{1}{2}ca\\sin B = \\frac{1}{2}ab\\sin C$.",
    "",
    "**Ví dụ 5.** Tính diện tích $S$ của tam giác $ABC$ có $c = 4$, $b = 6$, $\\widehat{A} = 150^\\circ$.",
    "",
    "**Giải** (H.3.15)",
    "Ta có: $S = \\frac{1}{2}bc\\sin A = \\frac{1}{2} \\cdot 6 \\cdot 4 \\cdot \\sin 150^\\circ = 6$.",
    "",
    "[Hình ảnh: Tam giác ABC góc tù tại A. Góc A = 150 độ. Cạnh AB = 4, cạnh AC = 6. Ghi chú Hình 3.15]",
    "",
    "**Luyện tập 4.** Tính diện tích của tam giác $ABC$ có $b = 2$, $\\widehat{B} = 30^\\circ$, $\\widehat{C} = 45^\\circ$.",
    "",
    "*Chú ý.* Do $\\sin A = \\frac{a}{2R}$ nên từ công thức $S = \\frac{1}{2}bc\\sin A$, ta có:",
    "> Công thức tính diện tích tam giác $ABC$: $S = \\frac{abc}{4R}$.",
    "",
    "**Thảo luận.** Ta đã biết tính $\\cos A$ theo độ dài các cạnh của tam giác $ABC$. Liệu $\\sin A$ và diện tích $S$ có tính được theo độ dài các cạnh của tam giác $ABC$ hay không?",
    "",
    "> **Công thức Heron.** Trong tam giác $ABC$: $S = \\sqrt{p(p - a)(p - b)(p - c)}$.",
    "",
    "41",
    "**Ví dụ 6.** Cho tam giác $ABC$ có $a = 13, b = 14, c = 15$.",
    "a) Tính $\\sin A$.",
    "b) Tính diện tích $S$ bằng hai cách khác nhau.",
    "",
    "**Giải** (H.3.16)",
    "a) Áp dụng định lí côsin, ta có:",
    "$\\cos A = \\frac{b^2 + c^2 - a^2}{2bc} = \\frac{14^2 + 15^2 - 13^2}{420} = 0,6$.",
    "Do đó $\\sin A = \\sqrt{1 - \\cos^2 A} = 0,8$.",
    "",
    "b) Ta có $S = \\frac{1}{2}bc\\sin A = 84$.",
    "Áp dụng công thức Heron, ta cũng có thể tính $S$ theo cách thứ hai như sau:",
    "Tam giác $ABC$ có nửa chu vi là: $p = \\frac{a + b + c}{2} = \\frac{13 + 14 + 15}{2} = 21$.",
    "Khi đó",
    "$S_{ABC} = \\sqrt{p(p - a)(p - b)(p - c)} = \\sqrt{21 \\cdot (21 - 13) \\cdot (21 - 14) \\cdot (21 - 15)} = \\sqrt{21 \\cdot 8 \\cdot 7 \\cdot 6} = 84$.",
    "",
    "[Hình ảnh: Tam giác ABC với cạnh a = 13, b = 14, c = 15. Cạnh BC ở bên trái (13), cạnh AC ở bên phải (15), cạnh AB ở dưới đáy (14). Đỉnh A ở góc dưới bên phải, đỉnh B ở trên, đỉnh C ở góc dưới bên trái. Ghi chú Hình 3.16]",
    "",
    "**Vận dụng 3.** Công viên Hoà Bình (Hà Nội) có dạng hình ngũ giác $ABCDE$ như Hình 3.17. Dùng chế độ tính khoảng cách giữa hai điểm của Google Maps, một người xác định được các khoảng cách như trong hình vẽ. Theo số liệu đó, em hãy tính diện tích của công viên Hoà Bình.",
    "",
    "[Hình ảnh: Bản đồ vệ tinh Công viên Hoà Bình, viền đỏ tạo thành ngũ giác ABCDE. Nối các đỉnh tạo thành 3 tam giác. AD=441m, AC=538m. Các cạnh được đánh số: CD=575m, BC=476m, AB=256m, AE=401m, ED=217m. Ghi chú Hình 3.17]",
    "",
    "## BÀI TẬP",
    "",
    "3.5. Cho tam giác $ABC$ có $a = 6, b = 5, c = 8$. Tính $\\cos A, S, r$.",
    "",
    "3.6. Cho tam giác $ABC$ có $a = 10$, $\\widehat{A} = 45^\\circ$, $\\widehat{B} = 70^\\circ$. Tính $R, b, c$.",
    "",
    "3.7. Giải tam giác $ABC$ và tính diện tích của tam giác đó, biết $\\widehat{A} = 15^\\circ$, $\\widehat{B} = 130^\\circ$, $c = 6$.",
    "",
    "3.8. Một tàu đánh cá xuất phát từ cảng $A$, đi theo hướng S70°E với vận tốc 70 km/h. Đi được 90 phút thì động cơ của tàu bị hỏng nên tàu trôi tự do theo hướng nam với vận tốc 8 km/h. Sau 2 giờ kể từ khi động cơ bị hỏng, tàu neo đậu được vào một hòn đảo.",
    "a) Tính khoảng cách từ cảng $A$ tới đảo nơi tàu neo đậu.",
    "b) Xác định hướng từ cảng $A$ tới đảo nơi tàu neo đậu.",
    "",
    "*(Khung chú thích xanh: Hướng S$\\alpha^\\circ$E là hướng tạo với hướng nam góc $\\alpha^\\circ$ và tạo với hướng đông góc $90^\\circ - \\alpha^\\circ$. Các hướng S$\\alpha^\\circ$W, N$\\alpha^\\circ$E, N$\\alpha^\\circ$W cũng được định nghĩa một cách tương tự.",
    "[Hình ảnh biểu diễn các hướng: N (Bắc), S (Nam), E (Đông), W (Tây). Các tia biểu diễn hướng N$\\alpha^\\circ$W, N$\\alpha^\\circ$E, S$\\alpha^\\circ$W, S$\\alpha^\\circ$E với góc $\\alpha^\\circ$ tạo với trục Bắc-Nam.])*",
    "",
    "42",
    "3.9. Trên nóc một toà nhà có một cột ăng-ten cao 5 m. Từ một vị trí quan sát $A$ cao 7 m so với mặt đất có thể nhìn thấy đỉnh $B$ và chân $C$ của cột ăng-ten, với các góc tương ứng là $50^\\circ$ và $40^\\circ$ so với phương nằm ngang (H.3.18).",
    "a) Tính các góc của tam giác $ABC$.",
    "b) Tính chiều cao của toà nhà.",
    "",
    "[Hình ảnh: Sơ đồ mô tả bài toán 3.9. Toà nhà màu cam bên trái, cột ăng-ten BC cao 5m trên nóc toà nhà. Điểm quan sát A bên phải, độ cao 7m. Góc nhìn đến đỉnh B là $50^\\circ$, đến chân C là $40^\\circ$ so với phương ngang. Ghi chú Hình 3.18]",
    "",
    "3.10. Từ bãi biển Vũng Chùa, Quảng Trị, ta có thể ngắm được Đảo Yến. Hãy đề xuất một cách xác định bề rộng của hòn đảo (theo chiều ta ngắm được).",
    "",
    "[Hình ảnh: Cảnh Đảo Yến nhìn từ bãi biển.",
    "Đảo Yến, nhìn từ bãi biển Vũng Chùa, Quảng Trị]",
    "",
    "3.11. Để tránh núi, đường giao thông hiện tại phải đi vòng như mô hình trong Hình 3.19. Để rút ngắn khoảng cách và tránh sạt lở núi, người ta dự định làm đường hầm xuyên núi, nối thẳng từ $A$ tới $D$. Hỏi độ dài đường mới sẽ giảm bao nhiêu kilômét so với đường cũ?",
    "",
    "[Hình ảnh: Mô hình ngọn núi, đường vòng từ A qua B, C đến D. Đường hầm nối thẳng A và D.",
    "$AB = 8$ km, $BC = 6$ km, $CD = 12$ km.",
    "Góc $\\widehat{ABC} = 105^\\circ$, góc $\\widehat{BCD} = 135^\\circ$.",
    "Ghi chú Hình 3.19]",
    "",
    "**Em có biết?**",
    "Heron (Heron of Alexandria) là một nhà phát minh, nhà toán học Hy Lạp, sống vào khoảng thế kỉ I. Mặc dù cỗ máy với động cơ hơi nước đầu tiên trên thế giới ra đời ở thế kỉ XVIII – một sự kiện quan trọng góp phần tạo nên cuộc cách mạng công nghiệp lần thứ nhất, nhưng chính Heron là người đầu tiên mô tả một mô hình đơn giản cho phép biến hơi nước thành chuyển động quay. Trong toán học, Heron mô tả cách tính diện tích của các đa giác đều từ 3 tới 12 cạnh, diện tích một số mặt và thể tích một số hình trong không gian.",
    "",
    "[Hình ảnh: Chân dung Heron of Alexandria]",
    "*(Theo mathshistory.st-andrews.ac.uk)*",
    "",
    "43"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'CH3_END', 'Bài tập cuối chương III', 44, 9, $JSON$
{
  "content": [
    "# BÀI TẬP CUỐI CHƯƠNG III",
    "",
    "## A – TRẮC NGHIỆM",
    "",
    "3.12. Cho tam giác $ABC$ có $\\widehat{B} = 135^\\circ$. Khẳng định nào sau đây là đúng?",
    "a) A. $S = \\frac{1}{2}ca$.          B. $S = \\frac{-\\sqrt{2}}{4}ac$.          C. $S = \\frac{\\sqrt{2}}{4}bc$.          D. $S = \\frac{\\sqrt{2}}{4}ca$.",
    "b) A. $R = \\frac{a}{\\sin A}$.          B. $R = \\frac{\\sqrt{2}}{2}b$.          C. $R = \\frac{\\sqrt{2}}{2}c$.          D. $R = \\frac{\\sqrt{2}}{2}a$.",
    "c) A. $a^2 = b^2 + c^2 + \\sqrt{2}ab$.          B. $\\frac{b}{\\sin A} = \\frac{a}{\\sin B}$.",
    "C. $\\sin B = -\\frac{\\sqrt{2}}{2}$.          D. $b^2 = c^2 + a^2 - 2ca\\cos 135^\\circ$.",
    "",
    "3.13. Cho tam giác $ABC$. Khẳng định nào sau đây là đúng?",
    "a) A. $S = \\frac{abc}{4r}$.          B. $r = \\frac{2S}{a + b + c}$.",
    "C. $a^2 = b^2 + c^2 + 2bc\\cos A$.          D. $S = r(a + b + c)$.",
    "b) A. $\\sin A = \\sin(B + C)$.          B. $\\cos A = \\cos(B + C)$.",
    "C. $\\cos A > 0$.          D. $\\sin A \\le 0$.",
    "",
    "## B – TỰ LUẬN",
    "",
    "3.14. Tính giá trị của các biểu thức sau:",
    "a) $M = \\sin 45^\\circ \\cdot \\cos 45^\\circ + \\sin 30^\\circ$;",
    "b) $N = \\sin 60^\\circ \\cdot \\cos 30^\\circ + \\frac{1}{2}\\sin 45^\\circ \\cdot \\cos 45^\\circ$;",
    "c) $P = 1 + \\tan^2 60^\\circ$;",
    "d) $Q = \\frac{1}{\\sin^2 120^\\circ} - \\cot^2 120^\\circ$.",
    "",
    "3.15. Cho tam giác $ABC$ có $\\widehat{B} = 60^\\circ$, $\\widehat{C} = 45^\\circ$, $AC = 10$. Tính $a, R, S, r$.",
    "",
    "3.16. Cho tam giác $ABC$ có trung tuyến $AM$. Chứng minh rằng:",
    "a) $\\cos\\widehat{AMB} + \\cos\\widehat{AMC} = 0$;",
    "b) $MA^2 + MB^2 - AB^2 = 2MA \\cdot MB \\cdot \\cos\\widehat{AMB}$ và $MA^2 + MC^2 - AC^2 = 2MA \\cdot MC \\cdot \\cos\\widehat{AMC}$;",
    "c) $MA^2 = \\frac{2(AB^2 + AC^2) - BC^2}{4}$ (công thức đường trung tuyến).",
    "",
    "3.17. Cho tam giác $ABC$. Chứng minh rằng:",
    "a) Nếu góc $A$ nhọn thì $b^2 + c^2 > a^2$;",
    "b) Nếu góc $A$ tù thì $b^2 + c^2 < a^2$;",
    "c) Nếu góc $A$ vuông thì $b^2 + c^2 = a^2$.",
    "",
    "44",
    "3.18. Trên biển, tàu $B$ ở vị trí cách tàu $A$ 53 km về hướng N34°E. Sau đó, tàu $B$ chuyển động thẳng đều với vận tốc có độ lớn 30 km/h về hướng đông, đồng thời tàu $A$ chuyển động thẳng đều với vận tốc có độ lớn 50 km/h để gặp tàu $B$.",
    "a) Hỏi tàu $A$ cần phải chuyển động theo hướng nào?",
    "b) Với hướng chuyển động đó thì sau bao lâu tàu $A$ gặp tàu $B$?",
    "",
    "[Hình ảnh: Sơ đồ vị trí các tàu. Tàu A ở gốc hệ trục toạ độ N-S-E-W. Tàu B ở góc N34°E. Khoảng cách AB ban đầu. Hướng của tàu B là hướng Đông. Tàu A di chuyển cắt đường đi của tàu B tại điểm C. Tam giác ABC có góc A là $\\alpha$, góc B là $124^\\circ$ ($90^\\circ + 34^\\circ$).",
    "Ghi chú Hình 3.20]",
    "",
    "3.19. Trên sân bóng chày dành cho nam, các vị trí gôn Nhà (Home plate), gôn 1 (First base), gôn 2 (Second base), gôn 3 (Third base) là bốn đỉnh của một hình vuông có cạnh dài 27,4 m. Vị trí đứng ném bóng (Pitcher's mound) nằm trên đường nối gôn Nhà với gôn 2, và cách gôn Nhà 18,44 m. Tính các khoảng cách từ vị trí đứng ném bóng tới các gôn 1 và gôn 3.",
    "",
    "[Hình ảnh: Sân bóng chày với các vị trí Gôn Nhà, Gôn 1, Gôn 2, Gôn 3 và Vị trí ném bóng được đánh dấu trên bức ảnh chụp sân vận động.",
    "Ghi chú Hình 3.21]",
    "",
    "45"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B7', 'Bài 7. Các khái niệm mở đầu', 46, 10, $JSON$
{
  "content": [
    "# CHƯƠNG IV. VECTƠ",
    "",
    "[Hình ảnh: Bản đồ Google Maps chỉ đường từ Ga An Cựu đến Kinh thành Huế / Hoàng cung trong tử cấm thành. Có đường kẻ đứt nét nối hai vị trí, với khoảng cách hiển thị là \"3,01 km\" và hướng chỉ về phía Kinh thành Huế.",
    "Ghi chú Hình 4.1 (Theo Google Maps)]",
    "",
    "Hình 4.1 cho thấy ga An Cựu cách Hoàng cung Huế 3,01 km về hướng đông nam. Hai thông tin khoảng cách và hướng cho phép ta xác định được vị trí của ga An Cựu theo vị trí của Hoàng cung Huế.",
    "",
    "Một số đại lượng như lực, vận tốc cũng được đặc trưng bởi hai yếu tố là độ lớn và hướng. Chương này xây dựng một đối tượng toán học, được gọi là vectơ, mà ta có thể dùng nó để biểu diễn các đại lượng nói trên.",
    "Vectơ còn được sử dụng để xây dựng các khái niệm toán học, là công cụ để giải quyết nhiều bài toán và góp phần vào việc hình thành và phát triển năng lực tư duy tuyến tính cho người học.",
    "",
    "# Bài 7 CÁC KHÁI NIỆM MỞ ĐẦU",
    "",
    "**THUẬT NGỮ**",
    "- Vectơ, vectơ-không",
    "- Độ dài của vectơ",
    "- Giá của vectơ",
    "- Hai vectơ cùng phương",
    "- Hai vectơ cùng hướng, ngược hướng",
    "- Hai vectơ bằng nhau",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Nhận biết khái niệm vectơ, hai vectơ cùng phương, hai vectơ cùng hướng, hai vectơ bằng nhau, vectơ-không.",
    "- Biểu thị một số đại lượng như lực, vận tốc bằng vectơ.",
    "",
    "Nhiệt độ và gió là hai yếu tố luôn cùng được đề cập trong các bản tin dự báo thời tiết. Tuy nhiên, nhiệt độ là đại lượng chỉ có độ lớn, còn gió có cả hướng và độ lớn. Với một đơn vị đo, ta có thể dùng số để biểu diễn nhiệt độ. Đối với các đại lượng gồm hướng và độ lớn như vận tốc gió thì sao? Ta có thể dùng đối tượng toán học nào để biểu diễn chúng?",
    "*(Khung chú thích xanh trên nền ảnh bầu trời: Nhiệt độ: 30°C. Gió: đông nam, 18 km/h.)*",
    "",
    "46",
    "## 1. KHÁI NIỆM VECTƠ",
    "",
    "**HĐ1.** Một con tàu khởi hành từ đảo $A$, đi thẳng về hướng đông 10 km rồi đi thẳng tiếp 10 km về hướng nam thì tới đảo $B$ (H.4.2). Nếu từ đảo $A$, tàu đi thẳng (không đổi hướng) tới đảo $B$, thì phải đi theo hướng nào và quãng đường phải đi dài bao nhiêu kilômét?",
    "",
    "[Hình ảnh: Sơ đồ di chuyển của tàu. Trục toạ độ định hướng N-S-E-W. Từ điểm A mũi tên xanh chỉ sang Đông dài 10 km. Sau đó mũi tên xanh chỉ xuống Nam dài 10 km đến điểm B. Mũi tên đứt nét màu đỏ nối thẳng từ A tới B. Ghi chú Hình 4.2]",
    "",
    "Ta có thể gắn cho quãng đường thẳng từ đảo $A$ tới đảo $B$ đồng thời hai yếu tố, đó là độ dài và hướng (hướng đi thẳng từ đảo $A$ tới đảo $B$). Từ thực tế này, ta đi tới khái niệm toán học sau:",
    "",
    "> - **Vectơ** là một đoạn thẳng có hướng, nghĩa là, trong hai điểm mút của đoạn thẳng, đã chỉ rõ điểm đầu, điểm cuối.",
    "> - **Độ dài của vectơ** là khoảng cách giữa điểm đầu và điểm cuối của vectơ đó.",
    "",
    "**Chú ý**",
    "- Vectơ có điểm đầu $A$ và điểm cuối $B$ được kí hiệu là $\\overrightarrow{AB}$, đọc là *vectơ AB* (H.4.3).",
    "- Để vẽ một vectơ, ta vẽ đoạn thẳng nối điểm đầu và điểm cuối của nó, rồi đánh dấu mũi tên ở điểm cuối (H.4.3).",
    "- Vectơ còn được kí hiệu là $\\vec{a}, \\vec{b}, \\vec{x}, \\vec{y},...$ (H.4.4).",
    "- Độ dài của vectơ $\\overrightarrow{AB}, \\vec{a}$ tương ứng được kí hiệu là $|\\overrightarrow{AB}|, |\\vec{a}|$.",
    "",
    "[Hình ảnh: Mũi tên từ điểm A tới điểm B. Ghi chú Hình 4.3]",
    "[Hình ảnh: Bốn mũi tên với các nhãn $\\vec{a}, \\vec{b}, \\vec{x}, \\vec{y}$. Ghi chú Hình 4.4]",
    "",
    "**Ví dụ 1.** Cho hình vuông $ABCD$ với cạnh có độ dài bằng 1. Tính độ dài các vectơ $\\overrightarrow{AC}, \\overrightarrow{CA}, \\overrightarrow{BD}$.",
    "",
    "**Giải**",
    "Vì cạnh của hình vuông $ABCD$ có độ dài bằng 1 nên các đường chéo của hình vuông này có độ dài bằng $\\sqrt{2}$.",
    "Vậy $|\\overrightarrow{AC}| = AC = \\sqrt{2}$, $|\\overrightarrow{CA}| = CA = \\sqrt{2}$, $|\\overrightarrow{BD}| = BD = \\sqrt{2}$.",
    "",
    "[Hình ảnh: Hình vuông ABCD với hai đường chéo cắt nhau. Ghi chú bên trái hình vuông này là các đỉnh B, C (trên), A, D (dưới).] Wait. A hình vuông is ABCD. Let's look at the image carefully. Top edge is BC, bottom edge is AD. A is bottom left, D is bottom right. B is top left, C is top right. Actually, the label says A bottom left, D bottom right, B top left, C top right.",
    "",
    "**Luyện tập 1.** Cho tam giác đều $ABC$ với cạnh có độ dài bằng $a$. Hãy chỉ ra các vectơ có độ dài bằng $a$ và có điểm đầu, điểm cuối là các đỉnh của tam giác $ABC$.",
    "",
    "[Hình ảnh: Tam giác đều ABC, đỉnh A ở trên, B ở dưới bên trái, C ở dưới bên phải.]",
    "",
    "## 2. HAI VECTƠ CÙNG PHƯƠNG, CÙNG HƯỚNG, BẰNG NHAU",
    "",
    "**HĐ2.** Quan sát các làn đường trong Hình 4.5 và cho biết những nhận xét nào sau đây là đúng.",
    "a) Các làn đường song song với nhau.",
    "b) Các xe chạy theo cùng một hướng.",
    "c) Hai xe bất kì đều chạy theo cùng một hướng hoặc hai hướng ngược nhau.",
    "",
    "[Hình ảnh: Góc nhìn từ trên xuống của hai làn xe song song trên đường. Làn bên trái có hai xe đi xuống. Làn bên phải có một xe đi lên. Các dải phân cách đứt nét giữa đường. Ghi chú Hình 4.5]",
    "",
    "47",
    "> - Đường thẳng đi qua điểm đầu và điểm cuối của một vectơ được gọi là **giá** của vectơ đó.",
    "> - Hai vectơ được gọi là **cùng phương** nếu chúng có giá song song hoặc trùng nhau.",
    "",
    "[Hình ảnh: Bốn đường thẳng song song đứt nét. Trên các đường thẳng là các mũi tên (vectơ) $\\vec{a}, \\vec{b}, \\vec{c}, \\vec{d}$. Vectơ a và c nằm trên cùng một đường thẳng. Vectơ b và d nằm trên cùng một đường thẳng. Vectơ a và b cùng hướng sang phải. Vectơ c hướng sang phải. Vectơ d hướng sang trái. Ghi chú Hình 4.6]",
    "",
    "Trong Hình 4.7, mỗi cặp vectơ trong các vectơ $\\overrightarrow{AB}, \\vec{a}, \\vec{x}, \\vec{y}, \\vec{z}$ đều cùng phương, nhưng vectơ $\\vec{b}$ không cùng phương với mỗi vectơ trên.",
    "",
    "**HĐ3.** Xét các vectơ cùng phương trong Hình 4.7. Hai vectơ $\\vec{a}$ và $\\overrightarrow{AB}$ được gọi là cùng hướng, còn hai vectơ $\\vec{a}$ và $\\vec{x}$ được gọi là ngược hướng. Hãy chỉ ra các vectơ cùng hướng với vectơ $\\vec{a}$ và các vectơ ngược hướng với vectơ $\\vec{a}$.",
    "",
    "[Hình ảnh: Các vectơ trên lưới ô vuông.",
    "- Vectơ $\\vec{a}$ hướng lên trên bên phải.",
    "- Vectơ $\\overrightarrow{AB}$ hướng lên trên bên phải.",
    "- Vectơ $\\vec{x}$ hướng xuống dưới bên trái.",
    "- Vectơ $\\vec{y}$ hướng lên trên bên phải.",
    "- Vectơ $\\vec{z}$ hướng xuống dưới bên trái.",
    "- Vectơ $\\vec{b}$ hướng lên trên bên phải nhưng dốc hơn.",
    "Các vectơ $\\vec{a}, \\overrightarrow{AB}, \\vec{x}, \\vec{y}, \\vec{z}$ song song với nhau. Vectơ $\\vec{b}$ có phương khác.",
    "Ghi chú Hình 4.7]",
    "",
    "> Đối với hai vectơ cùng phương thì chúng **cùng hướng** hoặc **ngược hướng**.",
    "*(Khung chú thích của bạn nam: Chỉ khi hai vectơ cùng phương, ta mới nói tới chúng cùng hướng hay ngược hướng.)*",
    "",
    "> Hai vectơ $\\vec{a}$ và $\\vec{b}$ được gọi là **bằng nhau**, kí hiệu $\\vec{a} = \\vec{b}$, nếu chúng có cùng độ dài và cùng hướng.",
    "",
    "**Chú ý**",
    "- Ta cũng xét các vectơ có điểm đầu và điểm cuối trùng nhau (chẳng hạn $\\overrightarrow{AA}, \\overrightarrow{BB}, \\overrightarrow{MM}$), gọi là các **vectơ-không**.",
    "- Ta quy ước vectơ-không có độ dài bằng $0$, cùng hướng (do đó cùng phương) với mọi vectơ.",
    "- Các vectơ-không có cùng độ dài và cùng hướng nên bằng nhau và được kí hiệu chung là $\\vec{0}$.",
    "- Với mỗi điểm $O$ và vectơ $\\vec{a}$ cho trước, có duy nhất điểm $A$ sao cho $\\overrightarrow{OA} = \\vec{a}$ (H.4.8).",
    "",
    "[Hình ảnh: Lưới ô vuông. Vectơ $\\vec{a}$ và vectơ $\\overrightarrow{OA}$ song song, bằng nhau và cùng hướng. O là gốc, A là ngọn. Ghi chú Hình 4.8]",
    "",
    "**Ví dụ 2.** Cho hình chữ nhật $ABCD$. Hãy chỉ ra mối quan hệ về độ dài, phương, hướng giữa các cặp vectơ: $\\overrightarrow{AD}$ và $\\overrightarrow{BC}$, $\\overrightarrow{AB}$ và $\\overrightarrow{CD}$, $\\overrightarrow{AC}$ và $\\overrightarrow{BD}$. Những cặp vectơ nào trong các cặp vectơ trên là bằng nhau?",
    "",
    "**Giải** (H.4.9)",
    "- Hai vectơ $\\overrightarrow{AD}$ và $\\overrightarrow{BC}$ có cùng độ dài và cùng hướng.",
    "Do đó, hai vectơ $\\overrightarrow{AD}$ và $\\overrightarrow{BC}$ bằng nhau.",
    "- Hai vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{CD}$ có cùng độ dài và ngược hướng.",
    "Do đó, hai vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{CD}$ không bằng nhau.",
    "- Hai vectơ $\\overrightarrow{AC}$ và $\\overrightarrow{BD}$ có cùng độ dài nhưng không cùng phương nên không cùng hướng. Do đó, hai vectơ $\\overrightarrow{AC}$ và $\\overrightarrow{BD}$ không bằng nhau.",
    "",
    "[Hình ảnh: Hình chữ nhật ABCD. A góc trên bên trái, B góc trên bên phải, C góc dưới bên phải, D góc dưới bên trái. Ghi chú Hình 4.9]",
    "",
    "Vậy trong các cặp vectơ đang xét, chỉ có cặp vectơ $\\overrightarrow{AD}$ và $\\overrightarrow{BC}$ là bằng nhau ($\\overrightarrow{AD} = \\overrightarrow{BC}$).",
    "",
    "48",
    "**Luyện tập 2.** Cho hình thang cân $ABCD$ với hai đáy $AB, CD$, $AB < CD$ (H.4.10). Hãy chỉ ra mối quan hệ về độ dài, phương, hướng giữa các cặp vectơ $\\overrightarrow{AD}$ và $\\overrightarrow{BC}$, $\\overrightarrow{AB}$ và $\\overrightarrow{CD}$, $\\overrightarrow{AC}$ và $\\overrightarrow{BD}$. Có cặp vectơ nào trong các cặp vectơ trên bằng nhau hay không?",
    "",
    "[Hình ảnh: Hình thang cân ABCD. Đáy nhỏ AB nằm trên, đáy lớn CD nằm dưới. A ở trên cùng bên trái, B ở trên cùng bên phải. D ở dưới bên trái, C ở dưới bên phải. Các đường chéo AC, BD cắt nhau. Ghi chú Hình 4.10]",
    "",
    "**Ví dụ 3.** Chứng minh rằng ba điểm phân biệt $A, B, C$ thẳng hàng khi và chỉ khi hai vectơ $\\overrightarrow{AB}, \\overrightarrow{AC}$ cùng phương.",
    "",
    "**Giải**",
    "- Giả sử ba điểm $A, B, C$ thẳng hàng. Khi đó, chúng cùng thuộc một đường thẳng $d$. Vậy hai vectơ $\\overrightarrow{AB}, \\overrightarrow{AC}$ có cùng giá là $d$. Suy ra chúng cùng phương.",
    "- Giả sử hai vectơ $\\overrightarrow{AB}, \\overrightarrow{AC}$ cùng phương. Khi đó, chúng có cùng giá hoặc có giá song song với nhau. Mặt khác, giá của các vectơ trên đều đi qua $A$ nên chúng trùng nhau. Vậy $A, B, C$ thẳng hàng.",
    "",
    "*(Khung chú thích của bạn nữ: Ta có thể dùng ngôn ngữ vectơ để biểu thị một số quan hệ hình học.)*",
    "",
    "*Nhận xét.* Ba điểm phân biệt $A, B, C$ thẳng hàng khi và chỉ khi $\\overrightarrow{AB}, \\overrightarrow{AC}$ cùng phương.",
    "",
    "**Luyện tập 3.** Trong các điều kiện dưới đây, chọn điều kiện cần và đủ để một điểm $M$ nằm giữa hai điểm phân biệt $A$ và $B$.",
    "a) $\\overrightarrow{AB}$ và $\\overrightarrow{AM}$ ngược hướng.",
    "b) $\\overrightarrow{MA}$ và $\\overrightarrow{MB}$ cùng phương.",
    "c) $\\overrightarrow{AB}$ và $\\overrightarrow{AM}$ cùng hướng.",
    "d) $\\overrightarrow{MA}$ và $\\overrightarrow{MB}$ ngược hướng.",
    "",
    "*Chú ý.* Ta có thể dùng vectơ để biểu diễn các đại lượng như lực, vận tốc, gia tốc. Hướng của vectơ chỉ hướng của đại lượng, độ dài của vectơ thể hiện cho độ lớn của đại lượng và được lấy tỉ lệ với độ lớn của đại lượng.",
    "",
    "**Ví dụ 4.** Một vật $A$ được thả chìm hoàn toàn dưới đáy một cốc chất lỏng. Biết rằng trong ba cách biểu diễn lực đẩy Archimedes (Ác-si-mét) $\\vec{F}$ và trọng lực $\\vec{P}$ tác động lên vật $A$ ở Hình 4.11, có một cách biểu diễn đúng.",
    "",
    "[Hình ảnh: 3 cách biểu diễn lực $\\vec{F}$ và $\\vec{P}$ tác dụng vào vật A.",
    "a) $\\vec{F}$ chỉ lên (ngắn), $\\vec{P}$ chỉ xuống (dài).",
    "b) $\\vec{F}$ chỉ lên (bằng $\\vec{P}$), $\\vec{P}$ chỉ xuống (bằng $\\vec{F}$).",
    "c) $\\vec{F}$ chỉ lên (dài), $\\vec{P}$ chỉ xuống (ngắn).",
    "Ghi chú Hình 4.11]",
    "",
    "Hãy chỉ ra mối quan hệ giữa trọng lượng riêng của vật $A$ và trọng lượng riêng của chất lỏng trong cốc.",
    "",
    "49",
    "**Giải**",
    "",
    "Lực đẩy Archimedes và trọng lực đều tác động lên vật $A$ theo phương thẳng đứng, hai lực này cùng phương nhưng ngược hướng. Do đó, Hình 4.11a không đúng. Vật $A$ chìm xuống đáy nên trọng lực $P$ (có hướng từ trên xuống) lớn hơn lực đẩy Archimedes $F$ (có hướng từ dưới lên). Do vậy, Hình 4.11c không đúng.",
    "",
    "Vậy hình biểu diễn đúng là Hình 4.11b. Theo đó, vectơ biểu diễn lực $\\vec{P}$ có độ dài gấp 3 lần độ dài của vectơ biểu diễn lực $\\vec{F}$.",
    "",
    "Độ lớn của trọng lực và lực đẩy Archimedes tác động lên $A$ là: $|\\vec{P}| = d' \\cdot V, |\\vec{F}| = d \\cdot V$, trong đó $V$ (m³) là thể tích của vật $A$ và $d', d$ (N/m³) tương ứng là trọng lượng riêng của vật $A$ và của chất lỏng. Do $|\\vec{P}| = 3|\\vec{F}|$ (theo H.4.11b) nên $d' = 3d$. Vậy trọng lượng riêng của vật $A$ gấp 3 lần trọng lượng riêng của chất lỏng trong cốc.",
    "",
    "**Vận dụng.** Hai ca nô $A$ và $B$ chạy trên sông với các vận tốc riêng có cùng độ lớn là 15 km/h. Tuy vậy, ca nô $A$ chạy xuôi dòng còn ca nô $B$ chạy ngược dòng. Vận tốc của dòng nước trên sông là 3 km/h.",
    "a) Hãy thể hiện trên hình vẽ, vectơ vận tốc $\\vec{v}$ của dòng nước và các vectơ vận tốc thực tế $\\vec{v_a}, \\vec{v_b}$ của các ca nô $A, B$.",
    "b) Trong các vectơ $\\vec{v}, \\vec{v_a}, \\vec{v_b}$, những cặp vectơ nào cùng phương và những cặp vectơ nào ngược hướng?",
    "",
    "## BÀI TẬP",
    "",
    "4.1. Cho ba vectơ $\\vec{a}, \\vec{b}, \\vec{c}$ đều khác $\\vec{0}$. Những khẳng định nào sau đây là đúng?",
    "a) $\\vec{a}, \\vec{b}, \\vec{c}$ đều cùng hướng với $\\vec{0}$;",
    "b) Nếu $\\vec{b}$ không cùng hướng với $\\vec{a}$ thì $\\vec{b}$ ngược hướng với $\\vec{a}$;",
    "c) Nếu $\\vec{a}$ và $\\vec{b}$ đều cùng phương với $\\vec{c}$ thì $\\vec{a}$ và $\\vec{b}$ cùng phương;",
    "d) Nếu $\\vec{a}$ và $\\vec{b}$ đều cùng hướng với $\\vec{c}$ thì $\\vec{a}$ và $\\vec{b}$ cùng hướng.",
    "",
    "4.2. Trong Hình 4.12, hãy chỉ ra các vectơ cùng phương, các cặp vectơ ngược hướng và các cặp vectơ bằng nhau.",
    "",
    "[Hình ảnh: Trục toạ độ Oxy. Các vectơ trên mặt phẳng:",
    "$\\vec{a}$ từ điểm (0,0) đến (1,2)",
    "$\\vec{b}$ từ (-1,0) đến (0,2)",
    "$\\vec{c}$ từ (0,-4) đến (2,0)",
    "$\\vec{d}$ từ (1,2) đến (4,-1) -> Wait, let me check. $\\vec{d}$ is from point (1,2) pointing to (4,0). Let's see: start at (1,2), end at (4,0). Vector is (3, -2).",
    "Ghi chú Hình 4.12] Let me describe more carefully.",
    "Vector $\\vec{a}$ is green, from origin to (1,2).",
    "Vector $\\vec{b}$ is blue, from (-1,0) to (0,2).",
    "Vector $\\vec{c}$ is light blue, from (0,-4) to (2,0).",
    "Vector $\\vec{d}$ is red, from (1,2) to (4,0).",
    "",
    "4.3. Chứng minh rằng tứ giác $ABCD$ là một hình bình hành khi và chỉ khi $\\overrightarrow{BC} = \\overrightarrow{AD}$.",
    "",
    "4.4. Cho hình vuông $ABCD$ có hai đường chéo cắt nhau tại $O$. Hãy chỉ ra tập hợp $S$ gồm tất cả các vectơ khác $\\vec{0}$, có điểm đầu và điểm cuối thuộc tập hợp $\\{A; B; C; D; O\\}$. Hãy chia tập $S$ thành các nhóm sao cho hai vectơ thuộc cùng một nhóm khi và chỉ khi chúng bằng nhau.",
    "",
    "4.5. Trên mặt phẳng toạ độ $Oxy$, hãy vẽ các vectơ $\\overrightarrow{OA}, \\overrightarrow{MN}$ với $A(1; 2), M(0; -1), N(3; 5)$.",
    "a) Chỉ ra mối quan hệ giữa hai vectơ trên.",
    "b) Một vật thể khởi hành từ $M$ và chuyển động thẳng đều với vận tốc (tính theo giờ) được biểu diễn bởi vectơ $\\vec{v} = \\overrightarrow{OA}$. Hỏi vật thể đó có đi qua $N$ hay không? Nếu có thì sau bao lâu vật sẽ tới $N$?",
    "",
    "50"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B8', 'Bài 8. Tổng và hiệu của hai vectơ', 51, 11, $JSON$
{
  "content": [
    "# Bài 8 TỔNG VÀ HIỆU CỦA HAI VECTƠ",
    "",
    "**THUẬT NGỮ**",
    "- Tổng của hai vectơ",
    "- Hiệu của hai vectơ",
    "- Vectơ đối",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Thực hiện các phép toán cộng, trừ vectơ.",
    "- Mô tả trung điểm của đoạn thẳng, trọng tâm của tam giác bằng vectơ.",
    "- Vận dụng vectơ trong bài toán tổng hợp lực, tổng hợp vận tốc.",
    "",
    "Một con tàu chuyển động từ bờ bên này sang bờ bên kia của một dòng sông với vận tốc riêng không đổi. Giả sử vận tốc dòng nước là không đổi và đáng kể, các yếu tố bên ngoài khác không ảnh hưởng đến vận tốc thực tế của tàu. Nếu không quan tâm đến điểm đến thì cần giữ lái cho tàu tạo với bờ sông một góc bao nhiêu để tàu sang bờ bên kia được nhanh nhất?",
    "",
    "[Hình ảnh: Con tàu di chuyển chéo qua sông. Có các mũi tên biểu thị vận tốc của nước (mũi tên xanh lá cây ngang) và vận tốc mũi tàu (mũi tên đỏ chéo). Mũi tên đỏ chỉ hướng của tàu.]",
    "",
    "Vận tốc thực tế của con tàu trên sông đối với bờ phụ thuộc vào vận tốc riêng của tàu (đối với dòng nước) và vận tốc của dòng nước (đối với bờ). Tương tự, một vật thường chịu tác động của nhiều lực. Ta đã biết dùng vectơ để biểu diễn các đại lượng đó; bài học này xây dựng các phép toán vectơ, tương thích với việc tổng hợp vận tốc, tổng hợp và phân tích lực.",
    "",
    "## 1. TỔNG CỦA HAI VECTƠ",
    "",
    "**HĐ1.** Với hai vectơ $\\vec{a}, \\vec{b}$ cho trước, lấy một điểm $A$ và vẽ các vectơ $\\overrightarrow{AB} = \\vec{a}, \\overrightarrow{BC} = \\vec{b}$. Lấy điểm $A'$ khác $A$ và cũng vẽ các vectơ $\\overrightarrow{A'B'} = \\vec{a}, \\overrightarrow{B'C'} = \\vec{b}$. Hỏi hai vectơ $\\overrightarrow{AC}$ và $\\overrightarrow{A'C'}$ có mối quan hệ gì?",
    "",
    "[Hình ảnh:",
    "- Bên trái: Lưới ô vuông với tam giác ABC (nét liền đen) tạo bởi $\\overrightarrow{AB} = \\vec{a}$ và $\\overrightarrow{BC} = \\vec{b}$. Điểm A nằm tại giao điểm ô vuông, B sang phải 2 ô và lên 2 ô, C sang phải 2 ô và xuống 2 ô từ B. (Wait, let me look at the image). B is 2 right, 2 up from A. C is 2 right, 2 down from B. So C is 4 right from A.",
    "- Bên phải: Tam giác A'B'C' với các cạnh song song và bằng các cạnh của tam giác ABC. $\\overrightarrow{A'B'} = \\vec{a}$, $\\overrightarrow{B'C'} = \\vec{b}$, $\\overrightarrow{A'C'}$ có mũi tên.",
    "Ghi chú Hình này đi kèm HĐ1.]",
    "",
    "> Cho hai vectơ $\\vec{a}, \\vec{b}$. Lấy một điểm $A$ tuỳ ý và vẽ $\\overrightarrow{AB} = \\vec{a}, \\overrightarrow{BC} = \\vec{b}$ (H.4.13). Khi đó vectơ $\\overrightarrow{AC}$ được gọi là **tổng của hai vectơ** $\\vec{a}$ và $\\vec{b}$ và được kí hiệu là $\\vec{a} + \\vec{b}$.",
    "> Phép lấy tổng của hai vectơ được gọi là phép cộng vectơ.",
    "",
    "[Hình ảnh:",
    "Bên trái là 2 vectơ $\\vec{a}, \\vec{b}$ rời nhau.",
    "Bên phải là tam giác ABC. $\\overrightarrow{AB}$ mang nhãn $\\vec{a}$, $\\overrightarrow{BC}$ mang nhãn $\\vec{b}$, $\\overrightarrow{AC}$ mang nhãn $\\vec{a} + \\vec{b}$. Ghi chú Hình 4.13]",
    "",
    "**HĐ2.** Cho hình bình hành $ABCD$. Tìm mối quan hệ giữa hai vectơ $\\overrightarrow{AB} + \\overrightarrow{AD}$ và $\\overrightarrow{AC}$.",
    "",
    "[Hình ảnh: Hình bình hành ABCD, cạnh đáy AD. (No, the labels are: A bottom left, D bottom right. B top left, C top right). Vectơ $\\overrightarrow{AB}$, $\\overrightarrow{AD}$ và $\\overrightarrow{AC}$.]",
    "",
    "51",
    "> **Quy tắc ba điểm:** Với ba điểm bất kì $A, B, C$, ta có $\\overrightarrow{AB} + \\overrightarrow{BC} = \\overrightarrow{AC}$.",
    "> **Quy tắc hình bình hành:** Nếu $ABCD$ là một hình bình hành thì $\\overrightarrow{AB} + \\overrightarrow{AD} = \\overrightarrow{AC}$.",
    "",
    "**HĐ3.** a) Trong Hình 4.14a, hãy chỉ ra vectơ $\\vec{a} + \\vec{b}$ và vectơ $\\vec{b} + \\vec{a}$.",
    "b) Trong Hình 4.14b, hãy chỉ ra vectơ $(\\vec{a} + \\vec{b}) + \\vec{c}$ và vectơ $\\vec{a} + (\\vec{b} + \\vec{c})$.",
    "",
    "[Hình ảnh:",
    "a) Hình bình hành ABCD, cạnh dưới là $\\vec{b}$, cạnh bên là $\\vec{a}$. Đường chéo là $\\vec{a} + \\vec{b}$ hoặc $\\vec{b} + \\vec{a}$.",
    "b) Tứ giác lồi ABCD. Cạnh đáy là $\\vec{a}$, cạnh bên $\\vec{b}$, cạnh trên $\\vec{c}$. Đường chéo $\\vec{a} + \\vec{b}$ và $\\vec{b} + \\vec{c}$.",
    "Ghi chú Hình 4.14]",
    "",
    "> Với ba vectơ $\\vec{a}, \\vec{b}, \\vec{c}$ tuỳ ý:",
    "> - Tính chất giao hoán: $\\vec{a} + \\vec{b} = \\vec{b} + \\vec{a}$;",
    "> - Tính chất kết hợp: $(\\vec{a} + \\vec{b}) + \\vec{c} = \\vec{a} + (\\vec{b} + \\vec{c})$;",
    "> - Tính chất của vectơ-không: $\\vec{a} + \\vec{0} = \\vec{0} + \\vec{a} = \\vec{a}$.",
    "",
    "**Chú ý.** Do các vectơ $(\\vec{a} + \\vec{b}) + \\vec{c}$ và $\\vec{a} + (\\vec{b} + \\vec{c})$ bằng nhau, nên ta còn viết chúng dưới dạng $\\vec{a} + \\vec{b} + \\vec{c}$ và gọi là *tổng của ba vectơ* $\\vec{a}, \\vec{b}, \\vec{c}$. Tương tự, ta cũng có thể viết tổng của một số vectơ mà không cần dùng các dấu ngoặc.",
    "",
    "**Ví dụ 1.** Cho hình vuông $ABCD$ với cạnh có độ dài bằng 1. Tính độ dài của các vectơ $\\overrightarrow{AB} + \\overrightarrow{CB}$, $\\overrightarrow{AB} + \\overrightarrow{DC} + \\overrightarrow{BD}$.",
    "",
    "**Giải**",
    "Do $\\overrightarrow{AB} = \\overrightarrow{DC}$ nên $\\overrightarrow{AB} + \\overrightarrow{CB} = \\overrightarrow{DC} + \\overrightarrow{CB} = \\overrightarrow{DB}$.",
    "Vậy $|\\overrightarrow{AB} + \\overrightarrow{CB}| = |\\overrightarrow{DB}| = DB = \\sqrt{2}$.",
    "Ta có $\\overrightarrow{AB} + \\overrightarrow{DC} + \\overrightarrow{BD} = (\\overrightarrow{AB} + \\overrightarrow{BD}) + \\overrightarrow{DC} = \\overrightarrow{AD} + \\overrightarrow{DC} = \\overrightarrow{AC}$.",
    "Do đó $|\\overrightarrow{AB} + \\overrightarrow{DC} + \\overrightarrow{BD}| = |\\overrightarrow{AC}| = AC = \\sqrt{2}$.",
    "",
    "[Hình ảnh: Hình vuông ABCD. A trên trái, B trên phải... wait no. A ở dưới bên trái, D ở dưới bên phải. B ở trên bên trái, C ở trên bên phải. Let me recheck. A bottom left, D bottom right. B top left, C top right. But the diagonal is BD. And AB + CB? Usually A bottom left, B top left. Oh, A, B, C, D clockwise or counter-clockwise.] Let me describe it simply: Hình vuông ABCD với hai đường chéo cắt nhau.",
    "",
    "**Luyện tập 1.** Cho hình thoi $ABCD$ với cạnh có độ dài bằng 1 và $\\widehat{BAD} = 120^\\circ$. Tính độ dài của các vectơ $\\overrightarrow{CB} + \\overrightarrow{CD}$, $\\overrightarrow{DB} + \\overrightarrow{CD} + \\overrightarrow{BA}$.",
    "",
    "[Hình ảnh: Hình thoi ABCD với góc A = 120 độ. Đáy là AD, cạnh bên là AB, DC. D ở dưới phải, A dưới trái. C trên phải, B trên trái.]",
    "",
    "## 2. HIỆU CỦA HAI VECTƠ",
    "",
    "[Hình ảnh: Trẻ em chơi kéo co. Hai đội kéo co ở hai bên dây thừng. Đội áo cam bên trái, đội áo xanh bên phải. Dây được đánh dấu vạch đỏ ở giữa. Ghi chú dưới ảnh: Hai đội kéo co bất phân thắng bại!]",
    "",
    "**HĐ4.** Thế nào là hai lực cân bằng? Nếu dùng hai vectơ để biểu diễn hai lực cân bằng thì hai vectơ này có mối quan hệ gì với nhau?",
    "",
    "> - Vectơ có cùng độ dài và ngược hướng với vectơ $\\vec{a}$ được gọi là **vectơ đối** của vectơ $\\vec{a}$. Vectơ đối của $\\vec{a}$ được kí hiệu là $-\\vec{a}$.",
    "> - Vectơ $\\vec{0}$ được coi là vectơ đối của chính nó.",
    "",
    "**Chú ý.** Hai vectơ đối nhau khi và chỉ khi tổng của chúng bằng $\\vec{0}$.",
    "",
    "52",
    "> Vectơ $\\vec{a} + (-\\vec{b})$ được gọi là **hiệu của hai vectơ** $\\vec{a}$ và $\\vec{b}$ và được kí hiệu là $\\vec{a} - \\vec{b}$. Phép lấy hiệu hai vectơ được gọi là **phép trừ vectơ**.",
    "",
    "**Chú ý.** Nếu $\\vec{b} + \\vec{c} = \\vec{a}$ thì $\\vec{a} - \\vec{b} = \\vec{a} + (-\\vec{b}) = \\vec{c} + \\vec{b} + (-\\vec{b}) = \\vec{c} + \\vec{0} = \\vec{c}$.",
    "Với ba điểm $O, M, N$ tuỳ ý, ta có $\\overrightarrow{MN} = \\overrightarrow{MO} + \\overrightarrow{ON} = (-\\overrightarrow{OM}) + \\overrightarrow{ON} = \\overrightarrow{ON} - \\overrightarrow{OM}$.",
    "",
    "> **Quy tắc hiệu:** Với ba điểm $O, M, N$, ta có $\\overrightarrow{MN} = \\overrightarrow{ON} - \\overrightarrow{OM}$.",
    "",
    "**Ví dụ 2.** Cho hình bình hành $ABCD$ và một điểm $O$ bất kì. Chứng minh rằng $\\overrightarrow{OB} - \\overrightarrow{OA} = \\overrightarrow{OC} - \\overrightarrow{OD}$.",
    "",
    "**Giải**",
    "Áp dụng quy tắc hiệu, ta có $\\overrightarrow{OB} - \\overrightarrow{OA} = \\overrightarrow{AB}$, $\\overrightarrow{OC} - \\overrightarrow{OD} = \\overrightarrow{DC}$.",
    "Mặt khác $\\overrightarrow{AB} = \\overrightarrow{DC}$ nên $\\overrightarrow{OB} - \\overrightarrow{OA} = \\overrightarrow{OC} - \\overrightarrow{OD}$.",
    "",
    "**Ví dụ 3.** a) Chứng minh rằng nếu $I$ là trung điểm của đoạn thẳng $AB$ thì $\\overrightarrow{IA} + \\overrightarrow{IB} = \\vec{0}$.",
    "b) Chứng minh rằng nếu $G$ là trọng tâm của tam giác $ABC$ thì $\\overrightarrow{GA} + \\overrightarrow{GB} + \\overrightarrow{GC} = \\vec{0}$.",
    "",
    "**Giải**",
    "a) (H.4.15) Khi $I$ là trung điểm của $AB$, thì hai vectơ $\\overrightarrow{IA}$ và $\\overrightarrow{IB}$ có cùng độ dài và ngược hướng. Do đó, $\\overrightarrow{IA}$ và $\\overrightarrow{IB}$ đối nhau, suy ra $\\overrightarrow{IA} + \\overrightarrow{IB} = \\vec{0}$.",
    "",
    "[Hình ảnh: Đoạn thẳng AB với I là trung điểm. Vectơ IA hướng về trái, vectơ IB hướng về phải. Ghi chú Hình 4.15]",
    "",
    "b) (H.4.16) Trọng tâm $G$ của tam giác $ABC$ thuộc trung tuyến $AI$ và $GA = 2GI$. Lấy điểm $D$ đối xứng với $G$ qua $I$. Khi đó tứ giác $GBDC$ có hai đường chéo cắt nhau tại trung điểm của mỗi đường nên nó là một hình bình hành. Ta có $GA = 2GI = GD$.",
    "Hai vectơ $\\overrightarrow{GA}$ và $\\overrightarrow{GD}$ có cùng độ dài và ngược hướng nên chúng là hai vectơ đối nhau, do đó $\\overrightarrow{GA} + \\overrightarrow{GD} = \\vec{0}$.",
    "Trong hình bình hành $GBDC$, ta có $\\overrightarrow{GB} + \\overrightarrow{GC} = \\overrightarrow{GD}$.",
    "Vậy $\\overrightarrow{GA} + \\overrightarrow{GB} + \\overrightarrow{GC} = \\overrightarrow{GA} + \\overrightarrow{GD} = \\vec{0}$.",
    "",
    "[Hình ảnh: Tam giác ABC với trọng tâm G. AI là trung tuyến. Kéo dài IG thêm đoạn GD = IG. Hình bình hành GBDC được tạo thành. Ghi chú Hình 4.16]",
    "",
    "**Luyện tập 2.** Cho tứ giác $ABCD$. Gọi $M, N$ lần lượt là trung điểm của các cạnh $AB, CD$ và $O$ là trung điểm của $MN$. Chứng minh rằng $\\overrightarrow{OA} + \\overrightarrow{OB} + \\overrightarrow{OC} + \\overrightarrow{OD} = \\vec{0}$.",
    "",
    "**Chú ý.** Phép cộng vectơ tương ứng với các quy tắc tổng hợp lực, tổng hợp vận tốc:",
    "- Nếu hai lực cùng tác động vào chất điểm $A$ và được biểu diễn bởi các vectơ $\\vec{u_1}, \\vec{u_2}$ thì hợp lực tác động vào $A$ được biểu diễn bởi vectơ $\\vec{u_1} + \\vec{u_2}$.",
    "- Nếu một con thuyền di chuyển trên sông với vận tốc riêng (vận tốc so với dòng nước) được biểu diễn bởi vectơ $\\vec{v_r}$ và vận tốc của dòng nước (so với bờ) được biểu diễn bởi vectơ $\\vec{v_n}$, thì vận tốc thực tế của thuyền (so với bờ) được biểu diễn bởi vectơ $\\vec{v_r} + \\vec{v_n}$.",
    "",
    "*(Khung chú thích xanh của rô-bốt: Trong Vật lí, trọng tâm của một vật là điểm đặt của trọng lực tác dụng lên vật đó. Đối với một vật mỏng hình đa giác $A_1A_2...A_n$ thì trọng tâm của nó là điểm $G$ thoả mãn $\\overrightarrow{GA_1} + \\overrightarrow{GA_2} + ... + \\overrightarrow{GA_n} = \\vec{0}$.)*",
    "",
    "53",
    "**Ví dụ 4.** Hãy giải bài toán trong *tình huống mở đầu*.",
    "",
    "**Giải**",
    "Ta biểu thị hai bờ sông là hai đường thẳng song song $d_1, d_2$ (H.4.17). Giả sử tàu xuất phát từ $A \\in d_1$ và bánh lái luôn được giữ để tàu tạo với bờ góc $\\alpha$. Gọi $\\vec{v_r}$ và $\\vec{v_n}$ lần lượt là vectơ vận tốc riêng của tàu và vận tốc dòng nước. Gọi $M, N$ là các điểm sao cho $\\vec{v_r} = \\overrightarrow{AM}, \\vec{v_n} = \\overrightarrow{MN}$.",
    "Khi đó tàu chuyển động với vectơ vận tốc thực tế là $\\vec{v} = \\vec{v_r} + \\vec{v_n} = \\overrightarrow{AM} + \\overrightarrow{MN} = \\overrightarrow{AN}$.",
    "Gọi $B, C$ tương ứng là giao điểm của $AN, AM$ với $d_2$. Tàu chuyển động thẳng từ $A$ đến $B$ với vectơ vận tốc thực tế $\\overrightarrow{AN}$, do đó thời gian cần thiết để tàu sang được bờ $d_2$ là $\\frac{AB}{AN} = \\frac{AC}{AM}$.",
    "Mặt khác, $AM = |\\vec{v_r}|$ không đổi nên $\\frac{AC}{AM}$ nhỏ nhất $\\Leftrightarrow AC$ nhỏ nhất $\\Leftrightarrow AC \\perp d_2 \\Leftrightarrow AM \\perp d_2$.",
    "Vậy để tàu sang được bờ bên kia nhanh nhất, ta cần giữ bánh lái để tàu luôn vuông góc với bờ.",
    "",
    "[Hình ảnh: Hai đường thẳng song song d1 và d2. A nằm trên d1. Mũi tên AM là $\\vec{v_r}$ tạo góc $\\alpha$ với d1. Mũi tên MN là $\\vec{v_n}$ dọc theo d1. Mũi tên AN là $\\vec{v}$. C và B nằm trên d2. Ghi chú Hình 4.17]",
    "",
    "**Vận dụng.** Tính lực kéo cần thiết để kéo một khẩu pháo có trọng lượng 22 148 N (ứng với khối lượng xấp xỉ 2 260 kg) lên một con dốc nghiêng $30^\\circ$ so với phương nằm ngang (H.4.18). Nếu lực kéo của mỗi người bằng 100 N, thì cần tối thiểu bao nhiêu người để kéo pháo?",
    "",
    "[Hình ảnh: Pháo đang ở trên dốc nghiêng $30^\\circ$. Lực $\\vec{P}$ hướng thẳng xuống, lực $\\vec{w}$ hướng vuông góc với dốc lên, lực $\\vec{F}$ kéo song song với dốc lên. Ghi chú Hình 4.18]",
    "",
    "**Chú ý.** Ta coi khẩu pháo chịu tác động của ba lực: trọng lực $\\vec{P}$ (có độ lớn $|\\vec{P}| = 22~148$ N, có phương vuông góc với phương nằm ngang và hướng xuống dưới), phản lực $\\vec{w}$ (có độ lớn $|\\vec{w}| = |\\vec{P}|\\cos 30^\\circ$, có phương vuông góc với mặt dốc và hướng lên trên) và lực kéo $\\vec{F}$ (theo phương dốc, hướng từ chân dốc lên đỉnh dốc).",
    "",
    "## BÀI TẬP",
    "",
    "4.6. Cho bốn điểm $A, B, C, D$. Chứng minh rằng:",
    "a) $\\overrightarrow{AB} + \\overrightarrow{BC} + \\overrightarrow{CD} + \\overrightarrow{DA} = \\vec{0}$;",
    "b) $\\overrightarrow{AC} - \\overrightarrow{AD} = \\overrightarrow{BC} - \\overrightarrow{BD}$.",
    "",
    "4.7. Cho hình bình hành $ABCD$. Hãy tìm điểm $M$ để $\\overrightarrow{BM} = \\overrightarrow{AB} + \\overrightarrow{AD}$. Tìm mối quan hệ giữa hai vectơ $\\overrightarrow{CD}$ và $\\overrightarrow{CM}$.",
    "",
    "4.8. Cho tam giác đều $ABC$ có cạnh bằng $a$. Tính độ dài của các vectơ $\\overrightarrow{AB} - \\overrightarrow{AC}, \\overrightarrow{AB} + \\overrightarrow{AC}$.",
    "",
    "4.9. Hình 4.19 biểu diễn hai lực $\\vec{F_1}, \\vec{F_2}$ cùng tác động lên một vật, cho $|\\vec{F_1}| = 3$ N, $|\\vec{F_2}| = 2$ N. Tính độ lớn của hợp lực $\\vec{F_1} + \\vec{F_2}$.",
    "",
    "[Hình ảnh: Vectơ $\\vec{F_1}$ nằm ngang sang phải. Vectơ $\\vec{F_2}$ tạo góc $120^\\circ$ với $\\vec{F_1}$. Ghi chú Hình 4.19]",
    "",
    "4.10. Hai con tàu xuất phát cùng lúc từ bờ bên này để sang bờ bên kia của dòng sông với vận tốc riêng không đổi và có độ lớn bằng nhau. Hai tàu luôn được giữ lái sao cho chúng tạo với bờ cùng một góc nhọn nhưng một tàu hướng xuống hạ lưu, một tàu hướng lên thượng nguồn (hình bên). Vận tốc dòng nước là đáng kể, các yếu tố bên ngoài khác không ảnh hưởng tới vận tốc của các tàu. Hỏi tàu nào sang bờ bên kia trước?",
    "",
    "[Hình ảnh: Hai con tàu xuất phát từ một điểm trên bờ sông, tạo góc với bờ. Một tàu xuôi dòng, một tàu ngược dòng. Dòng nước chảy từ trái sang phải.]",
    "",
    "54"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B9', 'Bài 9. Tích của một vectơ với một số', 55, 12, $JSON$
{
  "content": [
    "# Bài 9 TÍCH CỦA MỘT VECTƠ VỚI MỘT SỐ",
    "",
    "**THUẬT NGỮ**",
    "- Tích của vectơ với một số",
    "- Phân tích một vectơ theo hai vectơ không cùng phương",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Thực hiện phép nhân vectơ với một số.",
    "- Mô tả các mối quan hệ cùng phương, cùng hướng bằng vectơ.",
    "",
    "Với mỗi cặp vật đặt trên hai đầu của một thanh đòn $AB$, luôn có duy nhất một điểm $M$ thuộc $AB$ để nếu đặt trụ đỡ tại $M$ thì thanh đòn ở trạng thái cân bằng (H.4.20). Điều trên còn đúng trong những trường hợp tổng quát hơn, chẳng hạn, thanh đòn được thay bởi một tấm ván hình đa giác $n$ đỉnh $A_1, A_2,..., A_n$, tại mỗi đỉnh $A_i$ có đặt một vật nặng $m_i$ (kg). Ở đây, ta coi thanh đòn, tấm ván là không có trọng lượng. Trong Vật lí, điểm $M$ như trên được gọi là điểm khối tâm của hệ chất điểm $A_1, A_2,..., A_n$ ứng với các khối lượng $m_1, m_2,..., m_n$ (kg).",
    "Qua bài học này, ta sẽ thấy Hình học cho phép xác định vị trí điểm khối tâm của một hệ chất điểm.",
    "",
    "[Hình ảnh: Đòn bẩy. Một thanh ván dài đặt trên điểm tựa tam giác M. Hai vật hình cầu (màu xanh ở đầu A, màu cam lớn hơn ở đầu B) được đặt lên ván. Hệ thống đang cân bằng. Ghi chú Hình 4.20]",
    "",
    "## 1. TÍCH CỦA MỘT VECTƠ VỚI MỘT SỐ",
    "",
    "**HĐ1.** Cho vectơ $\\overrightarrow{AB} = \\vec{a}$. Hãy xác định điểm $C$ sao cho $\\overrightarrow{BC} = \\vec{a}$.",
    "a) Tìm mối quan hệ giữa $\\overrightarrow{AC}$ và $\\vec{a}$.",
    "b) Vectơ $\\vec{a} + \\vec{a}$ có mối quan hệ như thế nào về hướng và độ dài đối với vectơ $\\vec{a}$?",
    "",
    "> Tích của một vectơ $\\vec{a} \\ne \\vec{0}$ với một số thực $k > 0$ là một vectơ, kí hiệu là $k\\vec{a}$, cùng hướng với vectơ $\\vec{a}$ và có độ dài bằng $k|\\vec{a}|$.",
    "",
    "[Hình ảnh: Lưới ô vuông. Vectơ $\\vec{a}$ chéo 2 ô lên, 2 ô phải.",
    "- Vectơ $\\frac{1}{2}\\vec{a}$ chéo 1 ô lên, 1 ô phải.",
    "- Vectơ $\\frac{3}{2}\\vec{a}$ chéo 3 ô lên, 3 ô phải.",
    "Ghi chú Hình 4.21]",
    "",
    "*(Biểu tượng dấu hỏi đỏ: $1\\vec{a}$ và $\\vec{a}$ có bằng nhau hay không?)*",
    "",
    "55",
    "**HĐ2.** Trên một trục số, gọi $O, A, M, N$ tương ứng biểu diễn các số $0; 1; \\sqrt{2}; -\\sqrt{2}$. Hãy nêu mối quan hệ về hướng và độ dài của mỗi vectơ $\\overrightarrow{OM}, \\overrightarrow{ON}$ với vectơ $\\vec{a} = \\overrightarrow{OA}$. Viết đẳng thức thể hiện mối quan hệ giữa hai vectơ $\\overrightarrow{OM}$ và $\\overrightarrow{OA}$.",
    "",
    "[Hình ảnh: Trục số. Điểm N ở toạ độ $-\\sqrt{2}$. Điểm O ở 0. Điểm A ở 1. Điểm M ở $\\sqrt{2}$. Ghi chú Hình 4.22]",
    "",
    "*(Khung chú thích của bạn nữ: Mối quan hệ giữa $\\overrightarrow{ON}$ và $\\overrightarrow{OA}$ được thể hiện bởi đẳng thức nào?)*",
    "",
    "> Tích của một vectơ $\\vec{a} \\ne \\vec{0}$ với một số thực $k < 0$ là một vectơ, kí hiệu là $k\\vec{a}$, ngược hướng với vectơ $\\vec{a}$ và có độ dài bằng $(-k)|\\vec{a}|$.",
    "",
    "[Hình ảnh: Lưới ô vuông. Vectơ $\\vec{a}$ chéo 2 ô lên, 2 ô phải.",
    "- Vectơ $-2\\vec{a}$ chéo 4 ô xuống, 4 ô trái.",
    "- Vectơ $-\\frac{3}{2}\\vec{a}$ chéo 3 ô xuống, 3 ô trái.",
    "Ghi chú Hình 4.23]",
    "",
    "**Chú ý.** Ta quy ước $k\\vec{a} = \\vec{0}$ nếu $\\vec{a} = \\vec{0}$ hoặc $k = 0$.",
    "",
    "Trong Hình 4.24, hai trung tuyến $AM$ và $BN$ của tam giác $ABC$ cắt nhau tại $G$.",
    "Ta có $\\overrightarrow{GA} = -2\\overrightarrow{GM}, \\overrightarrow{MN} = -\\frac{1}{2}\\overrightarrow{AB}$.",
    "",
    "[Hình ảnh: Tam giác ABC. M là trung điểm BC, N là trung điểm AC. Trung tuyến AM và BN cắt nhau tại G. Ghi chú Hình 4.24]",
    "",
    "*Nhận xét.* Vectơ $k\\vec{a}$ có độ dài bằng $|k||\\vec{a}|$ và cùng hướng với $\\vec{a}$ nếu $k \\ge 0$, ngược hướng với $\\vec{a}$ nếu $\\vec{a} \\ne \\vec{0}$ và $k < 0$.",
    "",
    "*(Khung chú thích màu xanh lơ: Phép lấy tích của vectơ với một số gọi là phép nhân vectơ với một số (hay phép nhân một số với vectơ).)*",
    "",
    "*(Biểu tượng dấu hỏi đỏ: $-\\vec{a}$ và $(-1)\\vec{a}$ có mối quan hệ gì?)*",
    "",
    "**Ví dụ 1.** Chứng minh rằng hai vectơ $\\vec{a}$ và $\\vec{b}$ ($\\vec{b} \\ne \\vec{0}$) cùng phương khi và chỉ khi tồn tại số $k$ để $\\vec{a} = k\\vec{b}$.",
    "",
    "**Giải**",
    "Thật vậy, nếu $\\vec{a} = k\\vec{b}$ thì $\\vec{a}$ và $\\vec{b}$ cùng phương.",
    "Ngược lại, giả sử $\\vec{a}$ và $\\vec{b}$ cùng phương, ta lấy $k = \\frac{|\\vec{a}|}{|\\vec{b}|}$ nếu $\\vec{a}$ và $\\vec{b}$ cùng hướng và lấy $k = -\\frac{|\\vec{a}|}{|\\vec{b}|}$ nếu $\\vec{a}$ và $\\vec{b}$ ngược hướng. Khi đó $\\vec{a} = k\\vec{b}$.",
    "",
    "**Luyện tập 1.** Cho đường thẳng $d$ đi qua hai điểm phân biệt $A$ và $B$ (H.4.25). Những khẳng định nào sau đây là đúng?",
    "a) Điểm $M$ thuộc đường thẳng $d$ khi và chỉ khi tồn tại số $t$ để $\\overrightarrow{AM} = t\\overrightarrow{AB}$.",
    "b) Với điểm $M$ bất kì, ta luôn có $\\overrightarrow{AM} = \\frac{AM}{AB} \\overrightarrow{AB}$.",
    "c) Điểm $M$ thuộc tia đối của tia $AB$ khi và chỉ khi tồn tại số $t \\le 0$ để $\\overrightarrow{AM} = t\\overrightarrow{AB}$.",
    "",
    "[Hình ảnh: Đường thẳng d. Có hai điểm A và B trên đường thẳng này. Ghi chú Hình 4.25]",
    "",
    "56",
    "## 2. CÁC TÍNH CHẤT CỦA PHÉP NHÂN VECTƠ VỚI MỘT SỐ",
    "",
    "**HĐ3.** Với $\\vec{u} \\ne \\vec{0}$ và hai số thực $k, t$, những khẳng định nào sau đây là đúng?",
    "a) Hai vectơ $k(t\\vec{u})$ và $(kt)\\vec{u}$ có cùng độ dài bằng $|kt||\\vec{u}|$.",
    "b) Nếu $kt \\ge 0$ thì cả hai vectơ $k(t\\vec{u}), (kt)\\vec{u}$ cùng hướng với $\\vec{u}$.",
    "c) Nếu $kt < 0$ thì cả hai vectơ $k(t\\vec{u}), (kt)\\vec{u}$ ngược hướng với $\\vec{u}$.",
    "d) Hai vectơ $k(t\\vec{u})$ và $(kt)\\vec{u}$ bằng nhau.",
    "",
    "[Hình ảnh: Lưới tạo bởi các đường thẳng song song. Vectơ $\\vec{u}$ ở dưới. Vectơ $\\vec{v}$ chéo lên. Điểm M ở giữa hình bình hành. Vectơ đi từ góc dưới trái đến góc trên phải. Các đỉnh A, B, C. Ghi chú Hình 4.26]",
    "",
    "**HĐ4.** Hãy chỉ ra trên Hình 4.26 hai vectơ $3(\\vec{u} + \\vec{v})$ và $3\\vec{u} + 3\\vec{v}$.",
    "Từ đó, nêu mối quan hệ giữa $3(\\vec{u} + \\vec{v})$ và $3\\vec{u} + 3\\vec{v}$.",
    "",
    "> Với hai vectơ $\\vec{a}, \\vec{b}$ và hai số thực $k, t$, ta luôn có:",
    "> - $k(t\\vec{a}) = (kt)\\vec{a}$;",
    "> - $(k + t)\\vec{a} = k\\vec{a} + t\\vec{a}$;",
    "> - $k(\\vec{a} + \\vec{b}) = k\\vec{a} + k\\vec{b}$;",
    "> - $k(\\vec{a} - \\vec{b}) = k\\vec{a} - k\\vec{b}$;",
    "> - $1\\vec{a} = \\vec{a}; (-1)\\vec{a} = -\\vec{a}$.",
    "",
    "**Ví dụ 2.** Cho đoạn thẳng $AB$ có trung điểm $I$. Chứng minh rằng với điểm $O$ tuỳ ý, ta có $\\overrightarrow{OA} + \\overrightarrow{OB} = 2\\overrightarrow{OI}$.",
    "",
    "**Giải**",
    "Vì $I$ là trung điểm của $AB$ nên $\\overrightarrow{IA} + \\overrightarrow{IB} = \\vec{0}$ (Ví dụ 3a, Bài 8).",
    "Do đó $\\overrightarrow{OA} + \\overrightarrow{OB} = (\\overrightarrow{OI} + \\overrightarrow{IA}) + (\\overrightarrow{OI} + \\overrightarrow{IB}) = 2\\overrightarrow{OI} + (\\overrightarrow{IA} + \\overrightarrow{IB}) = 2\\overrightarrow{OI}$.",
    "",
    "**Luyện tập 2.** Cho tam giác $ABC$ có trọng tâm $G$. Chứng minh rằng với điểm $O$ tuỳ ý, ta có $\\overrightarrow{OA} + \\overrightarrow{OB} + \\overrightarrow{OC} = 3\\overrightarrow{OG}$.",
    "",
    "*Nhận xét*",
    "- Điểm $I$ là trung điểm của đoạn thẳng $AB$ khi và chỉ khi $\\overrightarrow{IA} + \\overrightarrow{IB} = \\vec{0}$.",
    "- Điểm $G$ là trọng tâm của tam giác $ABC$ khi và chỉ khi $\\overrightarrow{GA} + \\overrightarrow{GB} + \\overrightarrow{GC} = \\vec{0}$.",
    "",
    "**Luyện tập 3.** Trong Hình 4.27, hãy biểu thị mỗi vectơ $\\vec{u}, \\vec{v}$ theo hai vectơ $\\vec{a}, \\vec{b}$, tức là tìm các số $x, y, z, t$ để $\\vec{u} = x\\vec{a} + y\\vec{b}, \\vec{v} = t\\vec{a} + z\\vec{b}$.",
    "",
    "[Hình ảnh: Lưới toạ độ xiên. Các vectơ $\\vec{a}$ (dọc theo đường xiên), $\\vec{b}$ (ngang), $\\vec{u}, \\vec{v}$ được vẽ trên lưới này. Ghi chú Hình 4.27]",
    "",
    "**Chú ý.** Cho hai vectơ không cùng phương $\\vec{a}, \\vec{b}$ (H.4.28). Khi đó, mọi vectơ $\\vec{u}$ đều biểu thị (phân tích) được một cách duy nhất theo hai vectơ $\\vec{a}, \\vec{b}$, nghĩa là có duy nhất cặp số $(x; y)$ sao cho $\\vec{u} = x\\vec{a} + y\\vec{b}$.",
    "",
    "[Hình ảnh: Vectơ $\\vec{u}$ được phân tích thành tổng của một vectơ cùng phương với $\\vec{a}$ và một vectơ cùng phương với $\\vec{b}$ theo quy tắc hình bình hành. Ghi chú Hình 4.28]",
    "",
    "57",
    "**Ví dụ 3.** Cho tam giác $ABC$. Hãy xác định điểm $M$ để $\\overrightarrow{MA} + 3\\overrightarrow{MB} + 2\\overrightarrow{MC} = \\vec{0}$.",
    "",
    "**Giải** (H.4.29)",
    "[Hình ảnh: Tam giác ABC. Điểm E trên AB sao cho AE = 1/2 AB (Wait, EB = 2AE? No, AE = 1/2 AB means AE=EB). F trên AC sao cho AF = 1/3 AC. M nằm trong tam giác. Nối A với M kéo dài. Nối E, M, F. Hình bình hành EAFM. Ghi chú Hình 4.29]",
    "",
    "Để xác định vị trí của $M$, trước hết ta biểu thị $\\overrightarrow{AM}$ (với góc $A$ đã biết) theo hai vectơ đã biết $\\overrightarrow{AB}, \\overrightarrow{AC}$.",
    "Đẳng thức vectơ đã cho tương đương với: $\\overrightarrow{MA} + 3(\\overrightarrow{MA} + \\overrightarrow{AB}) + 2(\\overrightarrow{MA} + \\overrightarrow{AC}) = \\vec{0}$",
    "$\\Leftrightarrow 6\\overrightarrow{MA} + 3\\overrightarrow{AB} + 2\\overrightarrow{AC} = \\vec{0} \\Leftrightarrow \\overrightarrow{AM} = \\frac{1}{2}\\overrightarrow{AB} + \\frac{1}{3}\\overrightarrow{AC}$.",
    "Lấy điểm $E$ là trung điểm của $AB$ và điểm $F$ thuộc cạnh $AC$ sao cho $AF = \\frac{1}{3}AC$.",
    "Khi đó $\\overrightarrow{AE} = \\frac{1}{2}\\overrightarrow{AB}$ và $\\overrightarrow{AF} = \\frac{1}{3}\\overrightarrow{AC}$. Vì vậy $\\overrightarrow{AM} = \\overrightarrow{AE} + \\overrightarrow{AF}$.",
    "Suy ra $M$ là đỉnh thứ tư của hình bình hành $EAFM$.",
    "",
    "Ta trở lại vấn đề đã được nêu trong phần đầu bài học. Điểm khối tâm $M$ của hệ các chất điểm $A_1, A_2,..., A_n$ với các khối lượng tương ứng $m_1, m_2,..., m_n$ được xác định bởi đẳng thức vectơ",
    "$m_1\\overrightarrow{MA_1} + m_2\\overrightarrow{MA_2} + ... + m_n\\overrightarrow{MA_n} = \\vec{0}$.",
    "Vì vậy, việc xác định điểm khối tâm được quy về việc xác định điểm thoả mãn đẳng thức vectơ tương ứng.",
    "",
    "## BÀI TẬP",
    "",
    "4.11. Cho hình bình hành $ABCD$. Gọi $M$ là trung điểm của cạnh $BC$. Hãy biểu thị $\\overrightarrow{AM}$ theo hai vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{AD}$.",
    "",
    "4.12. Cho tứ giác $ABCD$. Gọi $M, N$ tương ứng là trung điểm của các cạnh $AB, CD$. Chứng minh rằng $\\overrightarrow{BC} + \\overrightarrow{AD} = 2\\overrightarrow{MN} = \\overrightarrow{AC} + \\overrightarrow{BD}$.",
    "",
    "4.13. Cho hai điểm phân biệt $A$ và $B$.",
    "a) Hãy xác định điểm $K$ sao cho $\\overrightarrow{KA} + 2\\overrightarrow{KB} = \\vec{0}$.",
    "b) Chứng minh rằng với mọi điểm $O$, ta có $\\overrightarrow{OK} = \\frac{1}{3}\\overrightarrow{OA} + \\frac{2}{3}\\overrightarrow{OB}$.",
    "",
    "4.14. Cho tam giác $ABC$.",
    "a) Hãy xác định điểm $M$ để $\\overrightarrow{MA} + \\overrightarrow{MB} + 2\\overrightarrow{MC} = \\vec{0}$.",
    "b) Chứng minh rằng với mọi điểm $O$, ta có $\\overrightarrow{OA} + \\overrightarrow{OB} + 2\\overrightarrow{OC} = 4\\overrightarrow{OM}$.",
    "",
    "58",
    "4.15. Chất điểm $A$ chịu tác động của ba lực $\\vec{F_1}, \\vec{F_2}, \\vec{F_3}$ như Hình 4.30 và ở trạng thái cân bằng (tức là $\\vec{F_1} + \\vec{F_2} + \\vec{F_3} = \\vec{0}$). Tính độ lớn của các lực $\\vec{F_2}, \\vec{F_3}$, biết $\\vec{F_1}$ có độ lớn là 20 N.",
    "",
    "[Hình ảnh: Chất điểm A. Lực $\\vec{F_1}$ hướng xuống. Lực $\\vec{F_2}$ hướng ngang sang phải. Lực $\\vec{F_3}$ hướng lên trên chéo sang trái. Góc giữa hướng thẳng đứng (ngược với $\\vec{F_1}$) và $\\vec{F_3}$ là $120^\\circ$. Góc giữa $\\vec{F_2}$ và $\\vec{F_3}$ là $120^\\circ$.",
    "Ghi chú Hình 4.30]",
    "",
    "**Em có biết?**",
    "",
    "Mặc dù dựa vào lực đẩy của gió, bằng cách đi theo đường dích dắc, thuyền buồm vẫn có thể di chuyển tới một vị trí ở ngược hướng gió so với vị trí xuất phát.",
    "",
    "[Hình ảnh: Sơ đồ di chuyển dích dắc của thuyền buồm.",
    "- Phía trên là Đích. Phía dưới là Vị trí xuất phát.",
    "- Gió thổi thẳng từ Đích xuống Vị trí xuất phát.",
    "- Thuyền đi theo đường dích dắc xiên qua lại.",
    "- Hình phóng to cánh buồm: Vectơ gió thổi vào cánh buồm. Lực $\\vec{p}$ song song với cánh buồm, lực $\\vec{q}$ vuông góc cánh buồm. Lực $\\vec{q}$ được phân tích thành $\\vec{a}$ (dọc theo hướng thuyền đi) và $\\vec{b}$ (vuông góc với hướng thuyền). Lực cản của nước $\\vec{b'}$ ngược hướng với $\\vec{b}$.",
    "Ghi chú Phương cánh buồm, Gió.]",
    "",
    "Ta hãy dùng kiến thức về vectơ để phân tích các lực chính tác động tới sự chuyển động của thuyền buồm trong trường hợp này. Lực $\\vec{F}$ do gió tác động vào cánh buồm được phân tích thành lực $\\vec{p}$ cùng phương với cánh buồm và lực $\\vec{q}$ vuông góc với cánh buồm. Do cánh buồm mỏng nên lực $\\vec{p}$ chỉ trượt đi mà không tác động lên cánh buồm. Ta lại phân tích lực $\\vec{q}$ thành lực $\\vec{a}$ cùng phương với sống thuyền và lực $\\vec{b}$ có phương vuông góc với sống thuyền. Thuyền buồm có sống thuyền sâu (mũi nhọn) nên nó chịu một lực cản $\\vec{b'}$ đáng kể của nước, vuông góc với sống thuyền. Người ta điều chỉnh hướng thuyền (hướng sống thuyền), phương của cánh buồm để lực cản $\\vec{b'}$ của nước (lực này không phụ thuộc vào sự điều chỉnh) thắng lực $\\vec{b}$ (có thể điều chỉnh độ lớn). Cuối cùng, dưới tác động của lực $\\vec{a}$ thuyền di chuyển và sau một khoảng thời gian, nó lại được điều chỉnh hướng, để đi đến đích theo đường dích dắc.",
    "",
    "59"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B10', 'Bài 10. Vectơ trong mặt phẳng toạ độ', 60, 13, $JSON$
{
  "content": [
    "# Bài 10 VECTƠ TRONG MẶT PHẲNG TOẠ ĐỘ",
    "",
    "**THUẬT NGỮ**",
    "- Mặt phẳng toạ độ",
    "- Toạ độ của vectơ",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Nhận biết toạ độ của vectơ và thể hiện các phép toán vectơ theo toạ độ.",
    "- Thể hiện mối quan hệ giữa các vectơ thông qua toạ độ của chúng.",
    "- Ứng dụng của toạ độ vectơ trong bài toán xác định vị trí của vật trên mặt phẳng toạ độ.",
    "",
    "Một bản tin dự báo thời tiết thể hiện đường đi trong 12 giờ của một cơn bão trên một mặt phẳng toạ độ. Trong khoảng thời gian đó, tâm bão di chuyển thẳng đều từ vị trí có toạ độ $(13,8; 108,3)$ đến vị trí có toạ độ $(14,1; 106,3)$. Dựa vào thông tin trên, liệu ta có thể dự đoán được vị trí của tâm bão tại thời điểm bất kì trong khoảng thời gian 12 giờ đó hay không?",
    "",
    "[Hình ảnh: Bản đồ dự báo quỹ đạo cơn bão số 6 (Nakri) đi vào Biển Đông và hướng về miền Trung Việt Nam. Các vĩ độ và kinh độ được ghi chú trên bản đồ.",
    "Ghi chú Hình 4.31. Ta có thể dùng một phần mặt phẳng toạ độ để mô tả một phạm vi nhất định trên Trái Đất mà vị trí $x^\\circ$ vĩ bắc, $y^\\circ$ kinh đông của tâm bão được thể hiện bởi điểm có toạ độ $(x; y)$.]",
    "",
    "Trong bài học này, ta gắn cho mỗi vectơ trên mặt phẳng toạ độ một cặp số để có thể làm việc với vectơ thông qua cặp số đó.",
    "",
    "## 1. TOẠ ĐỘ CỦA VECTƠ",
    "",
    "**HĐ1.** Trên trục số $Ox$, gọi $A$ là điểm biểu diễn số 1 và đặt $\\overrightarrow{OA} = \\vec{i}$ (H.4.32a). Gọi $M$ là điểm biểu diễn số 4, $N$ là điểm biểu diễn số $-\\frac{3}{2}$. Hãy biểu thị mỗi vectơ $\\overrightarrow{OM}, \\overrightarrow{ON}$ theo vectơ $\\vec{i}$.",
    "",
    "Dùng vectơ, ta có thể diễn đạt lại trục số như sau:",
    "",
    "> Trục toạ độ (còn gọi là trục, hay trục số) là một đường thẳng mà trên đó đã xác định một điểm $O$ và một vectơ $\\vec{i}$ có độ dài bằng 1. Điểm $O$ gọi là *gốc toạ độ*, vectơ $\\vec{i}$ gọi là *vectơ đơn vị* của trục. Điểm $M$ trên trục biểu diễn số $x_0$ nếu $\\overrightarrow{OM} = x_0\\vec{i}$ (H.4.32b).",
    "",
    "[Hình ảnh:",
    "a) Trục số $Ox$. Các điểm $N(-3/2)$, $O(0)$, $A(1)$, $M(4)$.",
    "b) Trục toạ độ. Điểm $O$ ở gốc, vectơ $\\vec{i}$ dài 1 đơn vị. Điểm $M$ ở toạ độ $x_0$.",
    "Ghi chú Hình 4.32]",
    "",
    "60",
    "**HĐ2.** Trong Hình 4.33:",
    "a) Hãy biểu thị mỗi vectơ $\\overrightarrow{OM}, \\overrightarrow{ON}$ theo các vectơ $\\vec{i}, \\vec{j}$.",
    "b) Hãy biểu thị vectơ $\\overrightarrow{MN}$ theo các vectơ $\\overrightarrow{OM}, \\overrightarrow{ON}$, từ đó biểu thị vectơ $\\overrightarrow{MN}$ theo các vectơ $\\vec{i}, \\vec{j}$.",
    "",
    "[Hình ảnh: Hệ trục toạ độ Oxy. Điểm M(3, 5), N(-2, 5/2). Vectơ đơn vị $\\vec{i}$ trên Ox, $\\vec{j}$ trên Oy. Vectơ OM, ON, MN được vẽ. Ghi chú Hình 4.33]",
    "",
    "*(Khung chú thích của bạn nam: Hãy nhớ lại quy tắc hình bình hành và quy tắc hiệu.)*",
    "",
    "Trên mặt phẳng với một đơn vị đo độ dài cho trước, xét hai trục $Ox, Oy$ có chung gốc $O$ và vuông góc với nhau. Kí hiệu vectơ đơn vị của trục $Ox$ là $\\vec{i}$, vectơ đơn vị của trục $Oy$ là $\\vec{j}$. Hệ gồm hai trục $Ox, Oy$ như vậy được gọi là *hệ trục toạ độ* $Oxy$. Điểm $O$ gọi là *gốc toạ độ*, trục $Ox$ gọi là *trục hoành*, trục $Oy$ gọi là *trục tung*. Mặt phẳng chứa hệ trục toạ độ $Oxy$ gọi là **mặt phẳng toạ độ** $Oxy$ hay mặt phẳng $Oxy$ (H.4.34).",
    "",
    "> Với mỗi vectơ $\\vec{u}$ trên mặt phẳng $Oxy$, có duy nhất cặp số $(x_0; y_0)$ sao cho $\\vec{u} = x_0\\vec{i} + y_0\\vec{j}$. Ta nói vectơ $\\vec{u}$ có **toạ độ** $(x_0; y_0)$ và viết $\\vec{u} = (x_0; y_0)$ hay $\\vec{u}(x_0; y_0)$. Các số $x_0, y_0$ tương ứng được gọi là **hoành độ, tung độ** của $\\vec{u}$.",
    "",
    "[Hình ảnh: Hệ trục toạ độ Oxy với vectơ $\\vec{u}$ có điểm đầu tại gốc O, điểm cuối tại $(x_0, y_0)$. Vectơ đơn vị $\\vec{i}, \\vec{j}$. Ghi chú Hình 4.34]",
    "",
    "*Nhận xét.* Hai vectơ bằng nhau khi và chỉ khi chúng có cùng toạ độ.",
    "$\\vec{u}(x; y) = \\vec{v}(x'; y') \\Leftrightarrow \\begin{cases} x = x' \\\\ y = y' \\end{cases}$.",
    "",
    "**Ví dụ 1.** Tìm toạ độ của các vectơ đơn vị $\\vec{i}, \\vec{j}$ tương ứng của các trục $Ox, Oy$.",
    "",
    "**Giải**",
    "Vì $\\vec{i} = 1\\vec{i} + 0\\vec{j}$ nên $\\vec{i}$ có toạ độ là $(1; 0)$.",
    "Vì $\\vec{j} = 0\\vec{i} + 1\\vec{j}$ nên $\\vec{j}$ có toạ độ là $(0; 1)$.",
    "",
    "**Luyện tập 1.** Tìm toạ độ của $\\vec{0}$.",
    "",
    "## 2. BIỂU THỨC TOẠ ĐỘ CỦA CÁC PHÉP TOÁN VECTƠ",
    "",
    "**HĐ3.** Trong mặt phẳng toạ độ $Oxy$, cho $\\vec{u} = (2; -3), \\vec{v} = (4; 1), \\vec{a} = (8; -12)$.",
    "a) Hãy biểu thị mỗi vectơ $\\vec{u}, \\vec{v}, \\vec{a}$ theo các vectơ $\\vec{i}, \\vec{j}$.",
    "b) Tìm toạ độ của các vectơ $\\vec{u} + \\vec{v}, 4\\vec{u}$.",
    "c) Tìm mối liên hệ giữa hai vectơ $\\vec{u}, \\vec{a}$.",
    "",
    "> Cho hai vectơ $\\vec{u} = (x; y)$ và $\\vec{v} = (x'; y')$. Khi đó:",
    "> - $\\vec{u} + \\vec{v} = (x + x'; y + y')$;",
    "> - $\\vec{u} - \\vec{v} = (x - x'; y - y')$;",
    "> - $k\\vec{u} = (kx; ky)$, với $k \\in \\mathbb{R}$.",
    "",
    "61",
    "**Ví dụ 2.** Cho $\\vec{a} = (1; 2), \\vec{b} = \\left(\\frac{3}{2}; 3\\right)$.",
    "a) Tìm toạ độ của $\\vec{a} + \\vec{b}, \\vec{a} - 2\\vec{b}$.",
    "b) Hỏi $\\vec{a}$ và $\\vec{b}$ có cùng phương hay không?",
    "",
    "**Giải**",
    "a) Vì $\\vec{a} = (1; 2), \\vec{b} = \\left(\\frac{3}{2}; 3\\right)$ nên $\\vec{a} + \\vec{b} = \\left(\\frac{5}{2}; 5\\right)$.",
    "Ta có $2\\vec{b} = (3; 6)$ nên $\\vec{a} - 2\\vec{b} = (-2; -4)$.",
    "b) Do $\\frac{3}{2}\\vec{a} = \\left(\\frac{3}{2}; 3\\right) = \\vec{b}$ nên hai vectơ $\\vec{a}$ và $\\vec{b}$ cùng phương.",
    "",
    "*Nhận xét.* Vectơ $\\vec{v}(x'; y')$ cùng phương với vectơ $\\vec{u}(x; y) \\ne \\vec{0}$ khi và chỉ khi tồn tại số $k$ sao cho $x' = kx, y' = ky$ (hay là $\\frac{x'}{x} = \\frac{y'}{y}$ nếu $xy \\ne 0$).",
    "",
    "**HĐ4.** Trong mặt phẳng toạ độ $Oxy$, cho điểm $M(x_0; y_0)$.",
    "Gọi $P, Q$ tương ứng là hình chiếu vuông góc của $M$ trên trục hoành $Ox$ và trục tung $Oy$ (H.4.35).",
    "a) Trên trục $Ox$, điểm $P$ biểu diễn số nào? Biểu thị $\\overrightarrow{OP}$ theo $\\vec{i}$ và tính độ dài của $\\overrightarrow{OP}$ theo $x_0$.",
    "b) Trên trục $Oy$, điểm $Q$ biểu diễn số nào? Biểu thị $\\overrightarrow{OQ}$ theo $\\vec{j}$ và tính độ dài của $\\overrightarrow{OQ}$ theo $y_0$.",
    "c) Dựa vào hình chữ nhật $OPMQ$, tính độ dài của $\\overrightarrow{OM}$ theo $x_0, y_0$.",
    "d) Biểu thị $\\overrightarrow{OM}$ theo các vectơ $\\vec{i}, \\vec{j}$.",
    "",
    "[Hình ảnh: Hệ toạ độ Oxy. Điểm $M(x_0, y_0)$. P trên Ox là hình chiếu của M. Q trên Oy là hình chiếu của M. Hình chữ nhật OPMQ. Vectơ $\\vec{i}$ trên Ox, $\\vec{j}$ trên Oy. Ghi chú Hình 4.35]",
    "",
    "> Nếu điểm $M$ có toạ độ $(x; y)$ thì vectơ $\\overrightarrow{OM}$ có toạ độ $(x; y)$ và độ dài $|\\overrightarrow{OM}| = \\sqrt{x^2 + y^2}$.",
    "",
    "*Nhận xét.* Với vectơ $\\vec{u} = (x; y)$, ta lấy điểm $M(x; y)$ thì $\\vec{u} = \\overrightarrow{OM}$. Do đó, $|\\vec{u}| = |\\overrightarrow{OM}| = \\sqrt{x^2 + y^2}$.",
    "Chẳng hạn, vectơ $\\vec{u} = (2; -1)$ có độ dài là $|\\vec{u}| = \\sqrt{2^2 + (-1)^2} = \\sqrt{5}$.",
    "",
    "**HĐ5.** Trong mặt phẳng toạ độ $Oxy$, cho các điểm $M(x; y)$ và $N(x'; y')$.",
    "a) Tìm toạ độ của các vectơ $\\overrightarrow{OM}, \\overrightarrow{ON}$.",
    "b) Biểu thị vectơ $\\overrightarrow{MN}$ theo các vectơ $\\overrightarrow{OM}, \\overrightarrow{ON}$ và tìm toạ độ của $\\overrightarrow{MN}$.",
    "c) Tìm độ dài của vectơ $\\overrightarrow{MN}$.",
    "",
    "62",
    "> Với hai điểm $M(x; y)$ và $N(x'; y')$ thì $\\overrightarrow{MN} = (x' - x; y' - y)$ và khoảng cách giữa hai điểm $M, N$ là $MN = |\\overrightarrow{MN}| = \\sqrt{(x' - x)^2 + (y' - y)^2}$.",
    "",
    "**Ví dụ 3.** Trong mặt phẳng toạ độ $Oxy$, cho ba điểm $A(1; -2), B(3; 2), C(7; 4)$.",
    "a) Tìm toạ độ của các vectơ $\\overrightarrow{AB}, \\overrightarrow{BC}$. So sánh các khoảng cách từ $B$ tới $A$ và $C$.",
    "b) Ba điểm $A, B, C$ có thẳng hàng hay không?",
    "c) Tìm điểm $D(x; y)$ để $ABCD$ là một hình thoi.",
    "",
    "**Giải**",
    "a) Ta có $\\overrightarrow{AB} = (3 - 1; 2 - (-2)) = (2; 4), \\overrightarrow{BC} = (7 - 3; 4 - 2) = (4; 2)$.",
    "Các khoảng cách từ $B$ tới $A$ và $C$ lần lượt là:",
    "$AB = |\\overrightarrow{AB}| = \\sqrt{2^2 + 4^2} = 2\\sqrt{5}$; $BC = |\\overrightarrow{BC}| = \\sqrt{4^2 + 2^2} = 2\\sqrt{5}$.",
    "Do đó các khoảng cách này bằng nhau.",
    "b) Hai vectơ $\\overrightarrow{AB} = (2; 4), \\overrightarrow{BC} = (4; 2)$ không cùng phương (vì $\\frac{2}{4} \\ne \\frac{4}{2}$). Do đó các điểm $A, B, C$ không cùng nằm trên một đường thẳng. Vậy chúng không thẳng hàng.",
    "c) Các điểm $A, B, C$ không thẳng hàng và $BA = BC$ nên $ABCD$ là một hình thoi khi và chỉ khi $\\overrightarrow{AD} = \\overrightarrow{BC}$.",
    "Do $\\overrightarrow{AD} = (x - 1; y + 2), \\overrightarrow{BC} = (4; 2)$ nên",
    "$\\overrightarrow{AD} = \\overrightarrow{BC} \\Leftrightarrow \\begin{cases} x - 1 = 4 \\\\ y + 2 = 2 \\end{cases} \\Leftrightarrow \\begin{cases} x = 5 \\\\ y = 0. \\end{cases}$",
    "Vậy điểm cần tìm là $D(5; 0)$.",
    "",
    "[Hình ảnh: Hình thoi ABCD. A dưới trái, B trên trái, C trên phải, D dưới phải. Ghi chú Hình 4.36]",
    "",
    "**Luyện tập 2.** Trong mặt phẳng toạ độ $Oxy$, cho hai điểm $A(2; 1), B(3; 3)$.",
    "a) Các điểm $O, A, B$ có thẳng hàng hay không?",
    "b) Tìm điểm $M(x; y)$ để $OABM$ là một hình bình hành.",
    "",
    "**Ví dụ 4.** Trong mặt phẳng toạ độ $Oxy$, cho ba điểm không thẳng hàng:",
    "$A(1; 3), B(-2; 6), C(5; 1)$.",
    "a) Tìm toạ độ trung điểm $I$ của đoạn thẳng $AB$.",
    "b) Tìm toạ độ trọng tâm $G$ của tam giác $ABC$.",
    "",
    "63",
    "**Giải**",
    "",
    "a) (H.4.37) Điểm $I(x; y)$ là trung điểm của đoạn thẳng $AB$ khi và chỉ khi $\\overrightarrow{IA} + \\overrightarrow{IB} = \\vec{0}$ (*).",
    "",
    "[Hình ảnh: Đoạn thẳng AB với trung điểm I. Ghi chú Hình 4.37]",
    "",
    "Mặt khác $\\overrightarrow{IA} = (1 - x; 3 - y), \\overrightarrow{IB} = (-2 - x; 6 - y), \\overrightarrow{IA} + \\overrightarrow{IB} = (-1 - 2x; 9 - 2y)$.",
    "Do đó, (*) tương đương với $\\begin{cases} -1 - 2x = 0 \\\\ 9 - 2y = 0 \\end{cases} \\Leftrightarrow \\begin{cases} x = -\\frac{1}{2} \\\\ y = \\frac{9}{2}. \\end{cases}$",
    "Vậy $I\\left(-\\frac{1}{2}; \\frac{9}{2}\\right)$.",
    "",
    "b) Điểm $G(x; y)$ là trọng tâm của tam giác $ABC$ khi và chỉ khi $\\overrightarrow{GA} + \\overrightarrow{GB} + \\overrightarrow{GC} = \\vec{0}$ (**).",
    "Mặt khác",
    "$\\overrightarrow{GA} = (1 - x; 3 - y), \\overrightarrow{GB} = (-2 - x; 6 - y), \\overrightarrow{GC} = (5 - x; 1 - y)$,",
    "$\\overrightarrow{GA} + \\overrightarrow{GB} + \\overrightarrow{GC} = (4 - 3x; 10 - 3y)$.",
    "Do đó, (**) tương đương với $\\begin{cases} 4 - 3x = 0 \\\\ 10 - 3y = 0 \\end{cases} \\Leftrightarrow \\begin{cases} x = \\frac{4}{3} \\\\ y = \\frac{10}{3}. \\end{cases}$",
    "Vậy $G\\left(\\frac{4}{3}; \\frac{10}{3}\\right)$.",
    "",
    "**Chú ý**",
    "- Trung điểm $M$ của đoạn thẳng $AB$ có toạ độ là $\\left(\\frac{x_A + x_B}{2}; \\frac{y_A + y_B}{2}\\right)$.",
    "- Trọng tâm $G$ của tam giác $ABC$ có toạ độ là $\\left(\\frac{x_A + x_B + x_C}{3}; \\frac{y_A + y_B + y_C}{3}\\right)$.",
    "",
    "**Vận dụng.** Từ thông tin dự báo bão được đưa ra ở đầu bài học, hãy xác định toạ độ vị trí $M$ của tâm bão tại thời điểm 9 giờ trong khoảng thời gian 12 giờ của dự báo.",
    "",
    "*(Khung chú thích xanh: Trong 12 giờ, tâm bão được dự báo di chuyển thẳng đều từ A(13,8; 108,3) tới B(14,1; 106,3). Gọi toạ độ của M là (x; y). Bạn hãy tìm mối liên hệ giữa hai vectơ AM và AB rồi thể hiện mối quan hệ đó theo toạ độ để tìm x; y.)*",
    "",
    "**Chú ý.** Để thể hiện một phần Trái Đất trên một bản đồ phẳng người ta dùng một phép chiếu bản đồ, với độ sai khác nhất định giữa bản vẽ và thực địa (thường được quy định với từng loại bản đồ). Về nguyên tắc, phạm vi thể hiện càng hẹp thì càng chính xác. Trong vận dụng này, ta chỉ tính toán trong phạm vi một đoạn đường đi ngắn của tâm bão.",
    "",
    "64",
    "## BÀI TẬP",
    "",
    "4.16. Trong mặt phẳng toạ độ $Oxy$, cho các điểm $M(1; 3), N(4; 2)$.",
    "a) Tính độ dài của các đoạn thẳng $OM, ON, MN$.",
    "b) Chứng minh rằng tam giác $OMN$ vuông cân.",
    "",
    "4.17. Trong mặt phẳng toạ độ $Oxy$, cho các vectơ $\\vec{a} = 3\\vec{i} - 2\\vec{j}, \\vec{b} = (4; -1)$ và các điểm $M(-3; 6), N(3; -3)$.",
    "a) Tìm mối liên hệ giữa các vectơ $\\overrightarrow{MN}$ và $2\\vec{a} - \\vec{b}$.",
    "b) Các điểm $O, M, N$ có thẳng hàng hay không?",
    "c) Tìm điểm $P(x; y)$ để $OMNP$ là một hình bình hành.",
    "",
    "4.18. Trong mặt phẳng toạ độ $Oxy$, cho các điểm $A(1; 3), B(2; 4), C(-3; 2)$.",
    "a) Chứng minh rằng $A, B, C$ là ba đỉnh của một tam giác.",
    "b) Tìm toạ độ trung điểm $M$ của đoạn thẳng $AB$.",
    "c) Tìm toạ độ trọng tâm $G$ của tam giác $ABC$.",
    "d) Tìm điểm $D(x; y)$ để $O(0; 0)$ là trọng tâm của tam giác $ABD$.",
    "",
    "4.19. Sự chuyển động của một tàu thuỷ được thể hiện trên một mặt phẳng toạ độ như sau:",
    "Tàu khởi hành từ vị trí $A(1; 2)$ chuyển động thẳng đều với vận tốc (tính theo giờ) được biểu thị bởi vectơ $\\vec{v} = (3; 4)$. Xác định vị trí của tàu (trên mặt phẳng toạ độ) tại thời điểm sau khi khởi hành 1,5 giờ.",
    "",
    "4.20. Trong Hình 4.38, quân mã đang ở vị trí có toạ độ $(1; 2)$. Hỏi sau một nước đi, quân mã có thể đến những vị trí nào?",
    "",
    "[Hình ảnh: Bàn cờ vua đặt trên hệ toạ độ Oxy. Ô a1 tương ứng toạ độ (1,1). Quân mã đen ở vị trí (1,2) tức là ô a2. Có các quân cờ khác trên bàn cờ. Các trục x, y từ 1 đến 8 (or 7 in the image? No, 1 to 7 is marked). Let's trace it carefully.",
    "Trục x: 1, 2, 3, 4, 5, 6, 7 (the 8th column is half visible).",
    "Trục y: 1, 2, 3, 4, 5, 6, 7 (the 8th row is half visible).",
    "Quân mã đen ở toạ độ x=1, y=2.",
    "Ghi chú Hình 4.38]",
    "",
    "*(Khung chú thích của bạn nữ: Bạn có thể tìm hiểu để biết quy tắc đi của quân mã.)*",
    "",
    "65"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B11', 'Bài 11. Tích vô hướng của hai vectơ', 66, 14, $JSON$
{
  "content": [
    "# Bài 11 TÍCH VÔ HƯỚNG CỦA HAI VECTƠ",
    "",
    "**THUẬT NGỮ**",
    "- Góc giữa hai vectơ",
    "- Tích vô hướng của hai vectơ",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Tính góc, tích vô hướng của hai vectơ trong những trường hợp cụ thể.",
    "- Công thức toạ độ của tích vô hướng, tính chất của tích vô hướng.",
    "- Liên hệ khái niệm tích vô hướng với khái niệm công trong Vật lí.",
    "",
    "Toán học cung cấp ngôn ngữ và công cụ cho nhiều ngành khoa học. Trong các bài học trước, ta đã dùng vectơ để biểu diễn các đại lượng lực, vận tốc và dùng phép toán vectơ để tính hợp lực và tổng hợp vận tốc. Bài học này tiếp tục xây dựng khái niệm tích vô hướng giữa hai vectơ – đối tượng toán học còn được dùng để định nghĩa khái niệm công sinh bởi một lực trong Vật lí.",
    "",
    "## 1. GÓC GIỮA HAI VECTƠ",
    "",
    "**HĐ1.** Trong Hình 4.39, số đo góc $BAC$ cũng được gọi là số đo góc giữa hai vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{AC}$. Hãy tìm số đo các góc giữa $\\overrightarrow{BC}$ và $\\overrightarrow{BD}, \\overrightarrow{DA}$ và $\\overrightarrow{DB}$.",
    "",
    "[Hình ảnh: Tam giác ABC. Có đường phân giác AD? No.",
    "Tam giác ABD. Điểm C nằm trên đoạn AD.",
    "Góc A = 80 độ. Góc B = 30 độ.",
    "Tam giác ABC không phải vuông. Chú thích hình: $\\widehat{BAC} = 80^\\circ$, $\\widehat{ABC} = 30^\\circ$. Đỉnh A ở dưới trái, D ở dưới phải. C nằm giữa A và D. (Wait, the image shows A, C, D collinear). $\\widehat{BAC} = 80^\\circ$ is impossible if A,C,D are collinear and angle is inside triangle? Let's check: The arc for $80^\\circ$ is at A, covering the angle BAD. The arc for $30^\\circ$ is at B, covering the angle ABC.",
    "Ghi chú Hình 4.39]",
    "",
    "> Cho hai vectơ $\\vec{u}$ và $\\vec{v}$ khác $\\vec{0}$. Từ một điểm $A$ tuỳ ý, vẽ các vectơ $\\overrightarrow{AB} = \\vec{u}$ và $\\overrightarrow{AC} = \\vec{v}$ (H.4.40). Khi đó, số đo của góc $BAC$ được gọi là số đo góc giữa hai vectơ $\\vec{u}$ và $\\vec{v}$ hay đơn giản là góc giữa hai vectơ $\\vec{u}, \\vec{v}$, kí hiệu là $(\\vec{u}, \\vec{v})$.",
    "",
    "[Hình ảnh: Hai vectơ $\\vec{u}$ (ngang sang phải), $\\vec{v}$ (chéo lên trái) rời nhau. Bên dưới, từ điểm A chung vẽ $\\overrightarrow{AC}$ (giống $\\vec{v}$) và $\\overrightarrow{AB}$ (giống $\\vec{u}$). Góc CAB được khoanh cung. Ghi chú Hình 4.40]",
    "",
    "**Chú ý**",
    "- Quy ước rằng góc giữa hai vectơ $\\vec{u}$ và $\\vec{0}$ có thể nhận một giá trị tuỳ ý từ $0^\\circ$ đến $180^\\circ$.",
    "- Nếu $(\\vec{u}, \\vec{v}) = 90^\\circ$ thì ta nói rằng $\\vec{u}$ và $\\vec{v}$ vuông góc với nhau, kí hiệu là $\\vec{u} \\perp \\vec{v}$ hoặc $\\vec{v} \\perp \\vec{u}$.",
    "",
    "*(Biểu tượng dấu hỏi đỏ: Khi nào thì góc giữa hai vectơ bằng $0^\\circ$, bằng $180^\\circ$?)*",
    "",
    "**Ví dụ 1.** Cho tam giác $ABC$ vuông tại $A$ và $\\widehat{B} = 30^\\circ$.",
    "Tính $(\\overrightarrow{AB}, \\overrightarrow{AC}), (\\overrightarrow{CA}, \\overrightarrow{CB}), (\\overrightarrow{AB}, \\overrightarrow{BC})$.",
    "",
    "**Giải** (H.4.41)",
    "Ta có: $(\\overrightarrow{AB}, \\overrightarrow{AC}) = \\widehat{BAC} = 90^\\circ, (\\overrightarrow{CA}, \\overrightarrow{CB}) = \\widehat{ACB} = 60^\\circ$,",
    "$(\\overrightarrow{AB}, \\overrightarrow{BC}) = (\\overrightarrow{BD}, \\overrightarrow{BC}) = \\widehat{DBC} = 150^\\circ$.",
    "",
    "[Hình ảnh: Tam giác ABC vuông tại A. Góc B = $30^\\circ$. Cạnh AB kéo dài qua B tới D sao cho AB và BD nằm trên cùng một đường thẳng. Ghi chú Hình 4.41]",
    "",
    "**Luyện tập 1.** Cho tam giác đều $ABC$. Tính $(\\overrightarrow{AB}, \\overrightarrow{BC})$.",
    "",
    "66",
    "## 2. TÍCH VÔ HƯỚNG CỦA HAI VECTƠ",
    "",
    "[Hình ảnh: Một người đang kéo một chiếc hộp bằng một sợi dây với lực kéo $\\vec{F}$. Hộp di chuyển từ vị trí M đến vị trí N. Ghi chú Hình 4.42]",
    "",
    "Trong Vật lí, nếu lực $\\vec{F}$ không đổi tác động vào một vật và điểm đặt của lực chuyển động thẳng từ $M$ tới $N$, thì công $A$ của lực $\\vec{F}$ được tính theo công thức: $A = |\\vec{F}| \\cdot |\\overrightarrow{MN}| \\cdot \\cos(\\vec{F}, \\overrightarrow{MN})$,",
    "trong đó $|\\vec{F}|$ là độ lớn của lực $\\vec{F}$ (theo đơn vị Newton);",
    "$|\\overrightarrow{MN}|$ là độ dài của vectơ $\\overrightarrow{MN}$ (theo đơn vị mét);",
    "$(\\vec{F}, \\overrightarrow{MN})$ là góc giữa hai vectơ $\\vec{F}$ và $\\overrightarrow{MN}$.",
    "",
    "Toán học gọi giá trị $A$ (không kể đơn vị đo) trong biểu thức nói trên là tích vô hướng của hai vectơ $\\vec{F}$ và $\\overrightarrow{MN}$.",
    "",
    "> Tích vô hướng của hai vectơ $\\vec{u}$ và $\\vec{v}$ là một số, kí hiệu $\\vec{u} \\cdot \\vec{v}$, được xác định bởi công thức sau:",
    "> $\\vec{u} \\cdot \\vec{v} = |\\vec{u}| \\cdot |\\vec{v}| \\cdot \\cos(\\vec{u}, \\vec{v})$.",
    "",
    "*(Biểu tượng dấu hỏi đỏ: Khi nào thì tích vô hướng của hai vectơ khác vectơ-không $\\vec{u}, \\vec{v}$ là một số dương? Là một số âm?)*",
    "",
    "**Chú ý**",
    "- $\\vec{u} \\perp \\vec{v} \\Leftrightarrow \\vec{u} \\cdot \\vec{v} = 0$.",
    "- $\\vec{u} \\cdot \\vec{u}$ còn được viết là $\\vec{u}^2$ và được gọi là **bình phương vô hướng** của vectơ $\\vec{u}$. Ta có $\\vec{u}^2 = |\\vec{u}| \\cdot |\\vec{u}| \\cdot \\cos 0^\\circ = |\\vec{u}|^2$.",
    "",
    "*(Khung chú thích của bạn nữ: Bình phương vô hướng của một vectơ bằng bình phương độ dài của vectơ đó.)*",
    "",
    "*(Biểu tượng dấu hỏi đỏ: Khi nào thì $(\\vec{u} \\cdot \\vec{v})^2 = \\vec{u}^2 \\cdot \\vec{v}^2$?)*",
    "",
    "**Ví dụ 2.** Cho hình vuông $ABCD$ có cạnh bằng $a$.",
    "Tính các tích vô hướng sau: $\\overrightarrow{AB} \\cdot \\overrightarrow{AD}, \\overrightarrow{AB} \\cdot \\overrightarrow{AC}, \\overrightarrow{AB} \\cdot \\overrightarrow{BD}$.",
    "",
    "**Giải.** Vì $(\\overrightarrow{AB}, \\overrightarrow{AD}) = 90^\\circ$ nên $\\overrightarrow{AB} \\cdot \\overrightarrow{AD} = 0$.",
    "Hình vuông có cạnh bằng $a$ nên có đường chéo bằng $a\\sqrt{2}$.",
    "Mặt khác, $(\\overrightarrow{AB}, \\overrightarrow{AC}) = 45^\\circ$, $(\\overrightarrow{AB}, \\overrightarrow{BD}) = 135^\\circ$, do đó",
    "$\\overrightarrow{AB} \\cdot \\overrightarrow{AC} = AB \\cdot AC \\cdot \\cos 45^\\circ = a \\cdot a\\sqrt{2} \\cdot \\frac{\\sqrt{2}}{2} = a^2$;",
    "$\\overrightarrow{AB} \\cdot \\overrightarrow{BD} = AB \\cdot BD \\cdot \\cos 135^\\circ = a \\cdot a\\sqrt{2} \\cdot \\left(-\\frac{\\sqrt{2}}{2}\\right) = -a^2$.",
    "",
    "[Hình ảnh: Hình vuông ABCD. A trên trái, B trên phải... (Wait, A ở trên trái, B ở trên phải, C ở dưới phải, D ở dưới trái trong hình vẽ. Let's recheck. No, A is top left, B is top right, C is bottom right, D is bottom left. Actually A is top-left, B is top-right, D is bottom-left, C is bottom-right. $\\overrightarrow{AB}$ and $\\overrightarrow{BD}$ angle is $135^\\circ$. Let me check the image. A top-left, B top-right, D bottom-left, C bottom-right. Ghi chú Hình 4.43]",
    "",
    "**Luyện tập 2.** Cho tam giác $ABC$ có $BC = a, CA = b, AB = c$.",
    "Hãy tính $\\overrightarrow{AB} \\cdot \\overrightarrow{AC}$ theo $a, b, c$.",
    "",
    "*(Khung chú thích của bạn nam: Hãy nhớ lại định lí côsin.)*",
    "",
    "67",
    "## 3. BIỂU THỨC TOẠ ĐỘ VÀ TÍNH CHẤT CỦA TÍCH VÔ HƯỚNG",
    "",
    "**HĐ2.** Cho hai vectơ cùng phương $\\vec{u} = (x; y)$ và $\\vec{v} = (kx; ky)$. Hãy kiểm tra công thức $\\vec{u} \\cdot \\vec{v} = k(x^2 + y^2)$ theo từng trường hợp sau:",
    "a) $\\vec{u} = \\vec{0}$;",
    "b) $\\vec{u} \\ne \\vec{0}$ và $k \\ge 0$;",
    "c) $\\vec{u} \\ne \\vec{0}$ và $k < 0$.",
    "",
    "**HĐ3.** Trong mặt phẳng toạ độ $Oxy$, cho hai vectơ không cùng phương $\\vec{u} = (x; y)$ và $\\vec{v} = (x'; y')$.",
    "a) Xác định toạ độ của các điểm $A$ và $B$ sao cho $\\overrightarrow{OA} = \\vec{u}, \\overrightarrow{OB} = \\vec{v}$.",
    "b) Tính $AB^2, OA^2, OB^2$ theo toạ độ của $A$ và $B$.",
    "c) Tính $\\overrightarrow{OA} \\cdot \\overrightarrow{OB}$ theo toạ độ của $A, B$.",
    "",
    "*(Khung chú thích xanh nhạt: Để ý rằng, theo định lí côsin, ta có:",
    "$\\overrightarrow{OA} \\cdot \\overrightarrow{OB} = \\frac{OA^2 + OB^2 - AB^2}{2}$.)*",
    "",
    "> Tích vô hướng của hai vectơ $\\vec{u} = (x; y)$ và $\\vec{v} = (x'; y')$ được tính theo công thức:",
    "> $\\vec{u} \\cdot \\vec{v} = xx' + yy'$.",
    "",
    "**Nhận xét**",
    "- Hai vectơ $\\vec{u}$ và $\\vec{v}$ vuông góc với nhau khi và chỉ khi $xx' + yy' = 0$.",
    "- Bình phương vô hướng của $\\vec{u}(x; y)$ là $\\vec{u}^2 = x^2 + y^2$.",
    "- Nếu $\\vec{u} \\ne \\vec{0}$ và $\\vec{v} \\ne \\vec{0}$ thì $\\cos(\\vec{u}, \\vec{v}) = \\frac{\\vec{u} \\cdot \\vec{v}}{|\\vec{u}| \\cdot |\\vec{v}|} = \\frac{xx' + yy'}{\\sqrt{x^2 + y^2} \\cdot \\sqrt{x'^2 + y'^2}}$.",
    "",
    "**Ví dụ 3.** Trong mặt phẳng toạ độ $Oxy$, tính tích vô hướng của các cặp vectơ sau:",
    "a) $\\vec{u} = (2; -3)$ và $\\vec{v} = (5; 3)$;",
    "b) Hai vectơ đơn vị $\\vec{i}$ và $\\vec{j}$ tương ứng của các trục $Ox, Oy$.",
    "",
    "**Giải**",
    "a) Ta có: $\\vec{u} \\cdot \\vec{v} = 2 \\cdot 5 + (-3) \\cdot 3 = 10 - 9 = 1$.",
    "b) Vì $\\vec{i} = (1; 0)$ và $\\vec{j} = (0; 1)$ nên $\\vec{i} \\cdot \\vec{j} = 1 \\cdot 0 + 0 \\cdot 1 = 0$.",
    "",
    "**Luyện tập 3.** Tính tích vô hướng và góc giữa hai vectơ $\\vec{u} = (0; -5), \\vec{v} = (\\sqrt{3}; 1)$.",
    "",
    "**HĐ4.** Cho ba vectơ $\\vec{u} = (x_1; y_1), \\vec{v} = (x_2; y_2), \\vec{w} = (x_3; y_3)$.",
    "a) Tính $\\vec{u} \\cdot (\\vec{v} + \\vec{w}), \\vec{u} \\cdot \\vec{v} + \\vec{u} \\cdot \\vec{w}$ theo toạ độ của các vectơ $\\vec{u}, \\vec{v}, \\vec{w}$.",
    "b) So sánh $\\vec{u} \\cdot (\\vec{v} + \\vec{w})$ và $\\vec{u} \\cdot \\vec{v} + \\vec{u} \\cdot \\vec{w}$.",
    "c) So sánh $\\vec{u} \\cdot \\vec{v}$ và $\\vec{v} \\cdot \\vec{u}$.",
    "",
    "68",
    "> **Tính chất của tích vô hướng**",
    ">",
    "> Với ba vectơ $\\vec{u}, \\vec{v}, \\vec{w}$ bất kì và mọi số thực $k$, ta có:",
    "> - $\\vec{u} \\cdot \\vec{v} = \\vec{v} \\cdot \\vec{u}$ (tính chất giao hoán);",
    "> - $\\vec{u} \\cdot (\\vec{v} + \\vec{w}) = \\vec{u} \\cdot \\vec{v} + \\vec{u} \\cdot \\vec{w}$ (tính chất phân phối đối với phép cộng);",
    "> - $(k\\vec{u}) \\cdot \\vec{v} = k(\\vec{u} \\cdot \\vec{v}) = \\vec{u} \\cdot (k\\vec{v})$.",
    "",
    "**Chú ý.** Từ các tính chất trên, ta có thể chứng minh được:",
    "$\\vec{u} \\cdot (\\vec{v} - \\vec{w}) = \\vec{u} \\cdot \\vec{v} - \\vec{u} \\cdot \\vec{w}$ (tính chất phân phối đối với phép trừ);",
    "$(\\vec{u} + \\vec{v})^2 = \\vec{u}^2 + 2\\vec{u} \\cdot \\vec{v} + \\vec{v}^2; (\\vec{u} - \\vec{v})^2 = \\vec{u}^2 - 2\\vec{u} \\cdot \\vec{v} + \\vec{v}^2$;",
    "$(\\vec{u} + \\vec{v}) \\cdot (\\vec{u} - \\vec{v}) = \\vec{u}^2 - \\vec{v}^2$.",
    "",
    "**Ví dụ 4.** Cho tam giác $ABC$ vuông tại $A$ có $\\widehat{B} = 60^\\circ$. Gọi $M$ là trung điểm của cạnh $BC$. Trên các cạnh $AB, AC$ lần lượt lấy các điểm $P, Q$. Chứng minh rằng $\\widehat{PMQ} = 90^\\circ$ khi và chỉ khi $BP + \\sqrt{3}CQ = BC$.",
    "",
    "**Giải** (H.4.44)",
    "Đặt $MB = MC = a$.",
    "Ta có $\\widehat{PMQ} = 90^\\circ \\Leftrightarrow \\overrightarrow{MP} \\cdot \\overrightarrow{MQ} = 0$",
    "$\\Leftrightarrow (\\overrightarrow{MB} + \\overrightarrow{BP}) \\cdot (\\overrightarrow{MC} + \\overrightarrow{CQ}) = 0$",
    "$\\Leftrightarrow \\overrightarrow{MB} \\cdot \\overrightarrow{MC} + \\overrightarrow{MB} \\cdot \\overrightarrow{CQ} + \\overrightarrow{BP} \\cdot \\overrightarrow{MC} + \\overrightarrow{BP} \\cdot \\overrightarrow{CQ} = 0$. (1)",
    "",
    "Mặt khác,",
    "$\\overrightarrow{MB} \\cdot \\overrightarrow{MC} = MB \\cdot MC \\cdot \\cos 180^\\circ = -a^2$;",
    "$\\overrightarrow{MB} \\cdot \\overrightarrow{CQ} = MB \\cdot CQ \\cdot \\cos 30^\\circ = \\frac{\\sqrt{3}}{2} a \\cdot CQ$;",
    "$\\overrightarrow{BP} \\cdot \\overrightarrow{MC} = BP \\cdot MC \\cdot \\cos 60^\\circ = \\frac{1}{2} a \\cdot BP$;",
    "$\\overrightarrow{BP} \\cdot \\overrightarrow{CQ} = BP \\cdot CQ \\cdot \\cos 90^\\circ = 0$.",
    "",
    "Do đó",
    "(1) $\\Leftrightarrow -a^2 + \\frac{\\sqrt{3}}{2} a \\cdot CQ + \\frac{1}{2} a \\cdot BP = 0$",
    "$\\Leftrightarrow \\frac{\\sqrt{3}}{2} CQ + \\frac{1}{2} BP - a = 0$",
    "$\\Leftrightarrow \\sqrt{3}CQ + BP = 2a$",
    "$\\Leftrightarrow \\sqrt{3}CQ + BP = BC$.",
    "",
    "Ta có điều phải chứng minh.",
    "",
    "[Hình ảnh: Tam giác ABC vuông tại A. Cạnh BC có M là trung điểm. $\\widehat{B} = 60^\\circ, \\widehat{C} = 30^\\circ$. Điểm P trên AB. Điểm Q trên AC. Nối PM, QM. Ghi chú Hình 4.44]",
    "",
    "69",
    "**Luyện tập 4.** Cho tam giác $ABC$ với $A(-1; 2), B(8; -1), C(8; 8)$.",
    "Gọi $H$ là trực tâm của tam giác.",
    "a) Chứng minh rằng $\\overrightarrow{AH} \\cdot \\overrightarrow{BC} = 0$ và $\\overrightarrow{BH} \\cdot \\overrightarrow{CA} = 0$.",
    "b) Tìm toạ độ của $H$.",
    "c) Giải tam giác $ABC$.",
    "",
    "[Hình ảnh: Tam giác ABC với trực tâm H. Các đường cao AH và BH. Cạnh BC ngang... wait no. B(8, -1), C(8, 8) thì BC dọc. Ghi chú Hình 4.45]",
    "",
    "**Vận dụng.** Một lực $\\vec{F}$ không đổi tác động vào một vật và điểm đặt của lực chuyển động thẳng từ $A$ đến $B$. Lực $\\vec{F}$ được phân tích thành hai lực thành phần là $\\vec{F_1}$ và $\\vec{F_2}$ ($\\vec{F} = \\vec{F_1} + \\vec{F_2}$).",
    "a) Dựa vào tính chất của tích vô hướng, hãy giải thích vì sao công sinh bởi lực $\\vec{F}$ (đã được đề cập ở trên) bằng tổng các công sinh bởi các lực $\\vec{F_1}$ và $\\vec{F_2}$.",
    "b) Giả sử các lực thành phần $\\vec{F_1}, \\vec{F_2}$ tương ứng cùng phương, vuông góc với phương chuyển động của vật. Hãy tìm mối quan hệ giữa các công sinh bởi lực $\\vec{F}$ và lực $\\vec{F_1}$.",
    "",
    "[Hình ảnh: Lực $\\vec{F}$ chéo lên từ A. Phương chuyển động là đoạn AB ngang. $\\vec{F}$ được phân tích thành $\\vec{F_1}$ ngang và $\\vec{F_2}$ dọc. Vật di chuyển từ A đến B trên mặt phẳng. Ghi chú Hình 4.46]",
    "",
    "## BÀI TẬP",
    "",
    "4.21. Trong mặt phẳng toạ độ $Oxy$, hãy tính góc giữa hai vectơ $\\vec{a}$ và $\\vec{b}$ trong mỗi trường hợp sau:",
    "a) $\\vec{a} = (-3; 1), \\vec{b} = (2; 6)$;",
    "b) $\\vec{a} = (3; 1), \\vec{b} = (2; 4)$;",
    "c) $\\vec{a} = (-\\sqrt{2}; 1), \\vec{b} = (2; -\\sqrt{2})$.",
    "",
    "4.22. Tìm điều kiện của $\\vec{u}, \\vec{v}$ để:",
    "a) $\\vec{u} \\cdot \\vec{v} = |\\vec{u}| \\cdot |\\vec{v}|$;",
    "b) $\\vec{u} \\cdot \\vec{v} = -|\\vec{u}| \\cdot |\\vec{v}|$.",
    "",
    "4.23. Trong mặt phẳng toạ độ $Oxy$, cho hai điểm $A(1; 2), B(-4; 3)$. Gọi $M(t; 0)$ là một điểm thuộc trục hoành.",
    "a) Tính $\\overrightarrow{AM} \\cdot \\overrightarrow{BM}$ theo $t$.",
    "b) Tìm $t$ để $\\widehat{AMB} = 90^\\circ$.",
    "",
    "4.24. Trong mặt phẳng toạ độ $Oxy$, cho ba điểm không thẳng hàng $A(-4; 1), B(2; 4), C(2; -2)$.",
    "a) Giải tam giác $ABC$.",
    "b) Tìm toạ độ trực tâm $H$ của tam giác $ABC$.",
    "",
    "4.25. Chứng minh rằng với mọi tam giác $ABC$,",
    "$S_{ABC} = \\frac{1}{2} \\sqrt{\\overrightarrow{AB}^2 \\cdot \\overrightarrow{AC}^2 - (\\overrightarrow{AB} \\cdot \\overrightarrow{AC})^2}$.",
    "",
    "4.26. Cho tam giác $ABC$ có trọng tâm $G$. Chứng minh rằng với mọi điểm $M$,",
    "$MA^2 + MB^2 + MC^2 = 3MG^2 + GA^2 + GB^2 + GC^2$.",
    "",
    "70"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

