{
  "content": [
    "# BÀI TẬP CUỐI CHƯƠNG IV",
    "",
    "## A – TRẮC NGHIỆM",
    "",
    "4.27. Trong mặt phẳng toạ độ, cặp vectơ nào sau đây có cùng phương?",
    "A. $\\vec{u} = (2; 3)$ và $\\vec{v} = \\left(\\frac{1}{2}; 6\\right)$.          B. $\\vec{a} = (\\sqrt{2}; 6)$ và $\\vec{b} = (1; 3\\sqrt{2})$.",
    "C. $\\vec{i} = (0; 1)$ và $\\vec{j} = (1; 0)$.          D. $\\vec{c} = (1; 3)$ và $\\vec{d} = (2; -6)$.",
    "",
    "4.28. Trong mặt phẳng toạ độ, cặp vectơ nào sau đây vuông góc với nhau?",
    "A. $\\vec{u} = (2; 3)$ và $\\vec{v} = (4; 6)$.          B. $\\vec{a} = (1; -1)$ và $\\vec{b} = (-1; 1)$.",
    "C. $\\vec{z} = (a; b)$ và $\\vec{t} = (-b; a)$.          D. $\\vec{n} = (1; 1)$ và $\\vec{k} = (2; 0)$.",
    "",
    "4.29. Trong mặt phẳng toạ độ, vectơ nào sau đây có độ dài bằng 1?",
    "A. $\\vec{a} = (1; 1)$.          B. $\\vec{b} = (1; -1)$.",
    "C. $\\vec{c} = \\left(2; \\frac{1}{2}\\right)$.          D. $\\vec{d} = \\left(\\frac{1}{\\sqrt{2}}; \\frac{-1}{\\sqrt{2}}\\right)$.",
    "",
    "4.30. Góc giữa vectơ $\\vec{a} = (1; -1)$ và vectơ $\\vec{b} = (-2; 0)$ có số đo bằng:",
    "A. $90^\\circ$.          B. $0^\\circ$.          C. $135^\\circ$.          D. $45^\\circ$.",
    "",
    "4.31. Khẳng định nào sau đây là đúng?",
    "A. $(\\vec{a} \\cdot \\vec{b})\\vec{c} = \\vec{a}(\\vec{b} \\cdot \\vec{c})$.          B. $(\\vec{a} \\cdot \\vec{b})^2 = \\vec{a}^2 \\cdot \\vec{b}^2$.",
    "C. $\\vec{a} \\cdot \\vec{b} = |\\vec{a}| \\cdot |\\vec{b}| \\sin(\\vec{a}, \\vec{b})$.          D. $\\vec{a} \\cdot (\\vec{b} - \\vec{c}) = \\vec{a} \\cdot \\vec{b} - \\vec{a} \\cdot \\vec{c}$.",
    "",
    "4.32. Cho hình vuông $ABCD$ có cạnh $a$. Khẳng định nào sau đây là đúng?",
    "A. $(\\overrightarrow{AB}, \\overrightarrow{BD}) = 45^\\circ$.          B. $\\overrightarrow{AC} \\cdot \\overrightarrow{BC} = a^2$.",
    "C. $\\overrightarrow{AC} \\cdot \\overrightarrow{BD} = a^2\\sqrt{2}$.          D. $\\overrightarrow{BA} \\cdot \\overrightarrow{BD} = -a^2$.",
    "",
    "## B – TỰ LUẬN",
    "",
    "4.33. Trên cạnh $BC$ của tam giác $ABC$ lấy điểm $M$ sao cho $MB = 3MC$.",
    "a) Tìm mối liên hệ giữa hai vectơ $\\overrightarrow{MB}$ và $\\overrightarrow{MC}$.",
    "b) Biểu thị vectơ $\\overrightarrow{AM}$ theo hai vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{AC}$.",
    "",
    "71",
    "4.34. Cho hình bình hành $ABCD$. Chứng minh rằng với mọi điểm $M$, ta có:",
    "$\\overrightarrow{MA} + \\overrightarrow{MC} = \\overrightarrow{MB} + \\overrightarrow{MD}$.",
    "",
    "4.35. Trong mặt phẳng toạ độ $Oxy$, cho $A(2; 1), B(-2; 5)$ và $C(-5; 2)$.",
    "a) Tìm toạ độ của các vectơ $\\overrightarrow{BA}$ và $\\overrightarrow{BC}$.",
    "b) Chứng minh rằng $A, B, C$ là ba đỉnh của một tam giác vuông. Tính diện tích và chu vi của tam giác đó.",
    "c) Tìm toạ độ trọng tâm $G$ của tam giác $ABC$.",
    "d) Tìm toạ độ của điểm $D$ sao cho tứ giác $BCAD$ là một hình bình hành.",
    "",
    "4.36. Trong mặt phẳng toạ độ $Oxy$, cho $A(1; 2), B(3; 4), C(-1; -2)$ và $D(6; 5)$.",
    "a) Tìm toạ độ của các vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{CD}$.",
    "b) Hãy giải thích tại sao các vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{CD}$ cùng phương.",
    "c) Giả sử $E$ là điểm có toạ độ $(a; 1)$. Tìm $a$ để các vectơ $\\overrightarrow{AC}$ và $\\overrightarrow{BE}$ cùng phương.",
    "d) Với $a$ tìm được, hãy biểu thị vectơ $\\overrightarrow{AE}$ theo các vectơ $\\overrightarrow{AB}$ và $\\overrightarrow{AC}$.",
    "",
    "4.37. Cho vectơ $\\vec{a} \\ne \\vec{0}$. Chứng minh rằng $\\frac{1}{|\\vec{a}|}\\vec{a}$ (hay còn được viết là $\\frac{\\vec{a}}{|\\vec{a}|}$) là một vectơ đơn vị, cùng hướng với vectơ $\\vec{a}$.",
    "",
    "4.38. Cho ba vectơ $\\vec{a}, \\vec{b}, \\vec{u}$ với $|\\vec{a}| = |\\vec{b}| = 1$ và $\\vec{a} \\perp \\vec{b}$. Xét một hệ trục $Oxy$ với các vectơ đơn vị $\\vec{i} = \\vec{a}, \\vec{j} = \\vec{b}$. Chứng minh rằng:",
    "a) Vectơ $\\vec{u}$ có toạ độ là $(\\vec{u} \\cdot \\vec{a}; \\vec{u} \\cdot \\vec{b})$.",
    "b) $\\vec{u} = (\\vec{u} \\cdot \\vec{a})\\vec{a} + (\\vec{u} \\cdot \\vec{b})\\vec{b}$.",
    "",
    "4.39. Trên sông, một ca nô chuyển động thẳng đều theo hướng S15°E (xem chú thích ở Bài 3.8, trang 42) với vận tốc có độ lớn bằng 20 km/h. Tính độ lớn của vận tốc riêng của ca nô, biết rằng nước trên sông chảy về hướng đông với vận tốc có độ lớn bằng 3 km/h.",
    "",
    "72"
  ]
}
