INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'B14', 'Bài 14. Các số đặc trưng đo độ phân tán', 84, 18, $JSON$
{
  "content": [
    "# Bài 14 CÁC SỐ ĐẶC TRƯNG ĐO ĐỘ PHÂN TÁN",
    "",
    "**THUẬT NGỮ**",
    "- Khoảng biến thiên",
    "- Khoảng tứ phân vị",
    "- Phương sai",
    "- Độ lệch chuẩn",
    "",
    "**KIẾN THỨC, KĨ NĂNG**",
    "- Tính các số đặc trưng đo độ phân tán.",
    "- Biết ý nghĩa của các số đặc trưng đo độ phân tán.",
    "- Phát hiện các giá trị bất thường sử dụng các công cụ toán học.",
    "",
    "Dưới đây là điểm trung bình môn học kì I của hai bạn An và Bình:",
    "",
    "| | Toán | Vật lí | Hoá học | Ngữ văn | Lịch sử | Địa lí | Tin học | Tiếng Anh |",
    "|---|:---:|:---:|:---:|:---:|:---:|:---:|:---:|:---:|",
    "| An | 9,2 | 8,7 | 9,5 | 6,8 | 8,0 | 8,0 | 7,3 | 6,5 |",
    "| Bình | 8,2 | 8,1 | 8,0 | 7,8 | 8,3 | 7,9 | 7,6 | 8,1 |",
    "",
    "Điểm trung bình môn học kì của An và Bình đều là 8,0 nhưng rõ ràng Bình \"học đều\" hơn An. Có thể dùng những số đặc trưng nào để đo mức độ \"học đều\"?",
    "Bài này sẽ giới thiệu một vài số đặc trưng như vậy.",
    "",
    "## 1. KHOẢNG BIẾN THIÊN VÀ KHOẢNG TỨ PHÂN VỊ",
    "",
    "**HĐ1.** Một cổ động viên đã thống kê điểm số mà hai câu lạc bộ Leicester City và Everton đạt được trong 5 mùa giải Ngoại hạng Anh gần đây, từ mùa giải 2014 – 2015 đến mùa giải 2018 – 2019 như sau:",
    "Leicester City: $$41 \\quad 81 \\quad 44 \\quad 47 \\quad 52.$$",
    "Everton: $$47 \\quad 47 \\quad 61 \\quad 49 \\quad 54.$$",
    "Cổ động viên đó cho rằng, Everton thi đấu ổn định hơn Leicester City. Em có đồng ý với nhận định này không? Vì sao?",
    "",
    "Trong 5 mùa giải, điểm thấp nhất, cao nhất của Leicester City lần lượt là 41; 81 trong khi của Everton là 47; 61. Về trực quan, thành tích của Everton ổn định hơn Leicester City. Người ta có nhiều cách để đo sự ổn định này. Cách đơn giản nhất là dùng hiệu số: Điểm cao nhất – Điểm thấp nhất. Giá trị này được gọi là **khoảng biến thiên**.",
    "",
    "> **Khoảng biến thiên**, kí hiệu là $R$, là hiệu số giữa giá trị lớn nhất và giá trị nhỏ nhất trong mẫu số liệu.",
    "",
    "**Ý nghĩa.** Khoảng biến thiên dùng để đo độ phân tán của mẫu số liệu. Khoảng biến thiên càng lớn thì mẫu số liệu càng phân tán.",
    "",
    "**Ví dụ 1.** Điểm kiểm tra học kì môn Toán của các bạn Tổ 1, Tổ 2 lớp 10A được cho như sau:",
    "Tổ 1: $$7 \\quad 8 \\quad 8 \\quad 9 \\quad 8 \\quad 8 \\quad 8.$$",
    "Tổ 2: $$10 \\quad 6 \\quad 8 \\quad 9 \\quad 9 \\quad 7 \\quad 8 \\quad 7 \\quad 8.$$",
    "",
    "84",
    "a) Điểm kiểm tra trung bình của hai tổ có như nhau không?",
    "b) Tính các khoảng biến thiên của hai mẫu số liệu. Căn cứ trên chỉ số này, các bạn tổ nào học đồng đều hơn?",
    "",
    "**Giải**",
    "a) Điểm kiểm tra trung bình của hai tổ đều bằng 8.",
    "b) Đối với Tổ 1: Điểm kiểm tra thấp nhất, cao nhất tương ứng là 7; 9. Do đó khoảng biến thiên là: $R_1 = 9 - 7 = 2.$",
    "Đối với Tổ 2: Điểm kiểm tra thấp nhất, cao nhất tương ứng là 6; 10. Do đó khoảng biến thiên là: $R_2 = 10 - 6 = 4.$",
    "Do $R_2 > R_1$ nên ta nói các bạn Tổ 1 học đều hơn các bạn Tổ 2.",
    "",
    "**Luyện tập 1.** Mẫu số liệu sau cho biết chiều cao (đơn vị cm) của các bạn trong tổ:",
    "$$163 \\quad 159 \\quad 172 \\quad 167 \\quad 165 \\quad 168 \\quad 170 \\quad 161.$$",
    "Tính khoảng biến thiên của mẫu số liệu này.",
    "",
    "**Nhận xét.** Sử dụng khoảng biến thiên có ưu điểm là đơn giản, dễ tính toán song khoảng biến thiên chỉ sử dụng thông tin của giá trị lớn nhất và giá trị nhỏ nhất mà bỏ qua thông tin từ tất cả các giá trị khác. Do đó, khoảng biến thiên rất dễ bị ảnh hưởng bởi các giá trị bất thường.",
    "",
    "**HĐ2.** Trong một tuần, nhiệt độ cao nhất trong ngày (đơn vị $^\\circ\\text{C}$) tại Hà Nội và Điện Biên được cho như sau:",
    "Hà Nội: $$23 \\quad 25 \\quad 28 \\quad 28 \\quad 32 \\quad 33 \\quad 35.$$",
    "Điện Biên: $$16 \\quad 24 \\quad 26 \\quad 26 \\quad 26 \\quad 27 \\quad 28.$$",
    "a) Tính các khoảng biến thiên của mỗi mẫu số liệu và so sánh.",
    "b) Em có nhận xét gì về sự ảnh hưởng của giá trị 16 đến khoảng biến thiên của mẫu số liệu về nhiệt độ cao nhất trong ngày tại Điện Biên?",
    "c) Tính các tứ phân vị và hiệu $Q_3 - Q_1$ cho mỗi mẫu số liệu. Có thể dùng hiệu này để đo độ phân tán của mẫu số liệu không?",
    "",
    "> **Khoảng tứ phân vị**, kí hiệu là $\\Delta_Q$, là hiệu số giữa tứ phân vị thứ ba và tứ phân vị thứ nhất, tức là:",
    "> $$\\Delta_Q = Q_3 - Q_1.$$",
    "",
    "*Bản chất:* Khoảng tứ phân vị là khoảng biến thiên của 50% số liệu chính giữa của mẫu số liệu đã sắp xếp.",
    "",
    "**Ý nghĩa.** Khoảng tứ phân vị cũng là một số đo độ phân tán của mẫu số liệu. Khoảng tứ phân vị càng lớn thì mẫu số liệu càng phân tán.",
    "",
    "**Chú ý.** Một số tài liệu gọi khoảng biến thiên là *biên độ* và khoảng tứ phân vị là *độ trải giữa*.",
    "",
    "**Ví dụ 2.** Mẫu số liệu sau cho biết số ghế trống tại một rạp chiếu phim trong 9 ngày:",
    "$$7 \\quad 8 \\quad 22 \\quad 20 \\quad 15 \\quad 18 \\quad 19 \\quad 13 \\quad 11.$$",
    "Tìm khoảng tứ phân vị cho mẫu số liệu này.",
    "",
    "**Giải**",
    "Trước hết, ta sắp xếp mẫu số liệu theo thứ tự không giảm:",
    "$$7 \\quad 8 \\quad 11 \\quad 13 \\quad 15 \\quad 18 \\quad 19 \\quad 20 \\quad 22.$$",
    "",
    "85",
    "Mẫu số liệu gồm 9 giá trị nên trung vị là số ở vị trí chính giữa $Q_2 = 15$.",
    "Nửa số liệu bên trái là $7, \\ 8, \\ 11, \\ 13$ gồm 4 giá trị, hai phần tử chính giữa là $8, \\ 11$.",
    "Do đó, $Q_1 = (8 + 11) : 2 = 9,5$.",
    "Nửa số liệu bên phải là $18, \\ 19, \\ 20, \\ 22$ gồm 4 giá trị, hai phần tử chính giữa là $19, \\ 20$.",
    "Do đó, $Q_3 = (19 + 20) : 2 = 19,5$.",
    "Vậy khoảng tứ phân vị cho mẫu số liệu là $\\Delta_Q = 19,5 - 9,5 = 10$.",
    "",
    "**Luyện tập 2.** Mẫu số liệu sau đây cho biết số bài hát ở mỗi album trong bộ sưu tập của An:",
    "$$12 \\quad 7 \\quad 10 \\quad 9 \\quad 12 \\quad 9 \\quad 10 \\quad 11 \\quad 10 \\quad 14.$$",
    "Hãy tìm khoảng tứ phân vị cho mẫu số liệu này.",
    "",
    "## 2. PHƯƠNG SAI VÀ ĐỘ LỆCH CHUẨN",
    "",
    "Khoảng biến thiên chỉ sử dụng thông tin của giá trị lớn nhất và nhỏ nhất của mẫu số liệu (bỏ qua thông tin của tất cả các giá trị khác), còn khoảng tứ phân vị chỉ sử dụng thông tin của 50% số liệu chính giữa. Có một vài số đặc trưng khác đo độ phân tán sử dụng thông tin của tất cả các giá trị trong mẫu số liệu. Hai trong số đó là *phương sai* và *độ lệch chuẩn*.",
    "",
    "Cụ thể là với mẫu số liệu $x_1, \\ x_2, \\ \\dots, \\ x_n$, nếu gọi số trung bình là $\\bar{x}$ thì với mỗi giá trị $x_i$, độ lệch của nó so với giá trị trung bình là $x_i - \\bar{x}$.",
    "",
    "> - **Phương sai** là giá trị:",
    ">   $$s^2 = \\frac{(x_1 - \\bar{x})^2 + (x_2 - \\bar{x})^2 + \\dots + (x_n - \\bar{x})^2}{n}$$",
    "> - Căn bậc hai của phương sai, $s = \\sqrt{s^2}$, được gọi là **độ lệch chuẩn**.",
    "",
    "**Chú ý.** Người ta còn sử dụng đại lượng sau để đo độ phân tán của mẫu số liệu:",
    "$$\\hat{s}^2 = \\frac{(x_1 - \\bar{x})^2 + (x_2 - \\bar{x})^2 + \\dots + (x_n - \\bar{x})^2}{n-1}.$$",
    "",
    "**Ý nghĩa.** Phương sai hoặc độ lệch chuẩn càng lớn thì số liệu càng phân tán.",
    "",
    "**Ví dụ 3.** Mẫu số liệu sau đây cho biết sĩ số của 5 lớp khối 10 tại một trường:",
    "$$43 \\quad 45 \\quad 46 \\quad 41 \\quad 40.$$",
    "Tìm phương sai và độ lệch chuẩn cho mẫu số liệu này.",
    "",
    "**Giải**",
    "Số trung bình của mẫu số liệu là: $\\bar{x} = \\frac{43 + 45 + 46 + 41 + 40}{5} = 43$.",
    "Ta có bảng sau:",
    "",
    "| Giá trị | Độ lệch | Bình phương độ lệch |",
    "|:---:|:---:|:---:|",
    "| 43 | $43 - 43 = 0$ | 0 |",
    "| 45 | $45 - 43 = 2$ | 4 |",
    "| 46 | $46 - 43 = 3$ | 9 |",
    "| 41 | $41 - 43 = -2$ | 4 |",
    "| 40 | $40 - 43 = -3$ | 9 |",
    "| **Tổng** | | **26** |",
    "",
    "Mẫu số liệu gồm 5 giá trị nên $n = 5$. Do đó phương sai là:",
    "$$s^2 = \\frac{26}{5} = 5,2.$$",
    "Độ lệch chuẩn là:",
    "$$s = \\sqrt{5,2} \\approx 2,28.$$",
    "",
    "*Gợi ý:* Bạn có thể sử dụng máy tính cầm tay, phần mềm bảng tính hay phần mềm thống kê để tính các số đặc trưng.",
    "",
    "86",
    "**Luyện tập 3.** Dùng đồng hồ đo thời gian có độ chia nhỏ nhất đến 0,001 giây để đo 7 lần thời gian rơi tự do của một vật bắt đầu từ điểm $A\\ (v_A = 0)$ đến điểm $B$. Kết quả đo như sau:",
    "$$0,398 \\quad 0,399 \\quad 0,408 \\quad 0,410 \\quad 0,406 \\quad 0,405 \\quad 0,402.$$",
    "*(Theo Bài tập Vật lí 10, Nhà xuất bản Giáo dục Việt Nam, 2018)*",
    "",
    "Hãy tính phương sai và độ lệch chuẩn cho mẫu số liệu này. Qua các đại lượng này, em có nhận xét gì về độ chính xác của phép đo trên?",
    "",
    "## 3. PHÁT HIỆN SỐ LIỆU BẤT THƯỜNG HOẶC KHÔNG CHÍNH XÁC BẰNG BIỂU ĐỒ HỘP",
    "",
    "Trong mẫu số liệu thống kê, có khi gặp những giá trị quá lớn hoặc quá nhỏ so với đa số các giá trị khác. Những giá trị này được gọi là **giá trị bất thường**. Chúng xuất hiện trong mẫu số liệu có thể do nhầm lẫn hay sai sót nào đó. Ta có thể dùng biểu đồ hộp để phát hiện những giá trị bất thường này.",
    "",
    "[Hình 5.5. Biểu đồ hộp biểu diễn các giá trị bất thường nằm ngoài khoảng từ $Q_1 - 1,5\\cdot\\Delta_Q$ đến $Q_3 + 1,5\\cdot\\Delta_Q$]",
    "",
    "Các giá trị lớn hơn $Q_3 + 1,5 \\cdot \\Delta_Q$ hoặc bé hơn $Q_1 - 1,5 \\cdot \\Delta_Q$ được xem là **giá trị bất thường**.",
    "",
    "**Ví dụ 4.** Hàm lượng Natri (đơn vị mg) trong 100 g một số loại ngũ cốc được cho như sau:",
    "$$0 \\quad 340 \\quad 70 \\quad 140 \\quad 200 \\quad 180 \\quad 210 \\quad 150 \\quad 100 \\quad 130$$",
    "$$140 \\quad 180 \\quad 190 \\quad 160 \\quad 290 \\quad 50 \\quad 220 \\quad 180 \\quad 200 \\quad 210.$$",
    "Tìm giá trị bất thường trong mẫu số liệu trên bằng cách sử dụng biểu đồ hộp.",
    "",
    "**Giải**",
    "Từ mẫu số liệu ta tính được $Q_1 = 135$ và $Q_3 = 205$. Do đó, khoảng tứ phân vị là:",
    "$$\\Delta_Q = 205 - 135 = 70.$$",
    "",
    "Biểu đồ hộp cho mẫu số liệu này là:",
    "[Hình ảnh: Biểu đồ hộp biểu diễn trên trục số từ -10 đến 350. Hộp nằm từ 135 đến 205, có đường phân chia trung vị ở 180. Râu trái kéo dài đến 30, râu phải kéo dài đến 310. Có hai chấm tròn xanh lá ở 0 và 340 nằm ngoài râu.]",
    "",
    "Ta có $Q_1 - 1,5 \\cdot \\Delta_Q = 30$ và $Q_3 + 1,5 \\cdot \\Delta_Q = 310$ nên trong mẫu số liệu có hai giá trị được xem là bất thường là 340 mg (lớn hơn 310 mg) và 0 mg (bé hơn 30 mg).",
    "",
    "**Luyện tập 4.** Một mẫu số liệu có tứ phân vị thứ nhất là 56 và tứ phân vị thứ ba là 84. Hãy kiểm tra xem trong hai giá trị 10 và 100 giá trị nào được xem là giá trị bất thường.",
    "",
    "87",
    "## BÀI TẬP",
    "",
    "**5.11.** Mỗi khẳng định sau đúng hay sai?",
    "(1) Nếu các giá trị của mẫu số liệu càng tập trung quanh giá trị trung bình thì độ lệch chuẩn càng lớn.",
    "(2) Khoảng biến thiên chỉ sử dụng thông tin của giá trị lớn nhất và bé nhất, bỏ qua thông tin của các giá trị còn lại.",
    "(3) Khoảng tứ phân vị có sử dụng thông tin của giá trị lớn nhất, giá trị bé nhất.",
    "(4) Khoảng tứ phân vị chính là khoảng biến thiên của nửa dưới mẫu số liệu đã sắp xếp.",
    "(5) Các số đo độ phân tán đều không âm.",
    "",
    "**5.12.** Cho hai biểu đồ chấm điểm biểu diễn hai mẫu số liệu A, B như sau:",
    "",
    "[Hình A: Biểu đồ chấm điểm biểu diễn phân bố đều từ 3 đến 9]",
    "[Hình B: Biểu đồ chấm điểm biểu diễn tập trung cao ở các giá trị trung tâm 5, 6, 7]",
    "",
    "*(Chú thích: Số chấm trên mỗi giá trị biểu diễn cho tần số của giá trị đó.)*",
    "",
    "Không tính toán, hãy cho biết:",
    "a) Hai mẫu số liệu này có cùng khoảng biến thiên và số trung bình không?",
    "b) Mẫu số liệu nào có phương sai lớn hơn?",
    "",
    "**5.13.** Cho mẫu số liệu gồm 10 số dương không hoàn toàn giống nhau. Các số đo độ phân tán (khoảng biến thiên, khoảng tứ phân vị, độ lệch chuẩn) sẽ thay đổi như thế nào nếu:",
    "a) Nhân mỗi giá trị của mẫu số liệu với 2.",
    "b) Cộng mỗi giá trị của mẫu số liệu với 2.",
    "",
    "**5.14.** Từ mẫu số liệu về thuế thuốc lá của 51 thành phố tại một quốc gia, người ta tính được:",
    "$$\\text{Giá trị nhỏ nhất bằng } 2,5; \\quad Q_1 = 36; \\quad Q_2 = 60; \\quad Q_3 = 100; \\quad \\text{giá trị lớn nhất bằng } 205.$$",
    "a) Tỉ lệ thành phố có thuế thuốc lá lớn hơn 36 là bao nhiêu?",
    "b) Chỉ ra hai giá trị sao cho có 50% giá trị của mẫu số liệu nằm giữa hai giá trị này.",
    "c) Tìm khoảng tứ phân vị của mẫu số liệu.",
    "",
    "**5.15.** Mẫu số liệu sau đây cho biết cân nặng của 10 trẻ sơ sinh (đơn vị kg):",
    "$$2,977 \\quad 3,155 \\quad 3,920 \\quad 3,412 \\quad 4,236$$",
    "$$2,593 \\quad 3,270 \\quad 3,813 \\quad 4,042 \\quad 3,387.$$",
    "Hãy tính khoảng biến thiên, khoảng tứ phân vị và độ lệch chuẩn cho mẫu số liệu này.",
    "",
    "**5.16.** Tỉ lệ thất nghiệp ở một số quốc gia vào năm 2007 (đơn vị %) được cho như sau:",
    "$$7,8 \\quad 3,2 \\quad 7,7 \\quad 8,7 \\quad 8,6 \\quad 8,4 \\quad 7,2 \\quad 3,6$$",
    "$$5,0 \\quad 4,4 \\quad 6,7 \\quad 7,0 \\quad 4,5 \\quad 6,0 \\quad 5,4.$$",
    "Hãy tìm các giá trị bất thường (nếu có) của mẫu số liệu trên.",
    "",
    "88"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'CH5_END', 'Bài tập cuối chương V', 89, 19, $JSON$
{
  "content": [
    "# BÀI TẬP CUỐI CHƯƠNG V",
    "",
    "## A – TRẮC NGHIỆM",
    "",
    "**5.17.** Khi cân một bao gạo bằng một cân treo với thang chia 0,2 kg thì độ chính xác $d$ là:",
    "A. 0,1 kg.          B. 0,2 kg.          C. 0,3 kg.          D. 0,4 kg.",
    "",
    "**5.18.** Trong hai mẫu số liệu, mẫu nào có phương sai lớn hơn thì có độ lệch chuẩn lớn hơn, đúng hay sai?",
    "A. Đúng.          B. Sai.",
    "",
    "**5.19.** Có 25% giá trị của mẫu số liệu nằm giữa $Q_1$ và $Q_3$, đúng hay sai?",
    "A. Đúng.          B. Sai.",
    "",
    "**5.20.** Số đặc trưng nào sau đây đo độ phân tán của mẫu số liệu?",
    "A. Số trung bình.          B. Mốt.          C. Trung vị.          D. Độ lệch chuẩn.",
    "",
    "**5.21.** Điểm trung bình môn học kì I một số môn học của bạn An là 8; 9; 7; 6; 5; 7; 3. Nếu An được cộng thêm mỗi môn 0,5 điểm chuyên cần thì các số đặc trưng nào sau đây của mẫu số liệu không thay đổi?",
    "A. Số trung bình.          B. Trung vị.          C. Độ lệch chuẩn.          D. Tứ phân vị.",
    "",
    "## B – TỰ LUẬN",
    "",
    "**5.22.** Lương khởi điểm của 5 sinh viên vừa tốt nghiệp tại một trường đại học (đơn vị triệu đồng) là:",
    "$$3,5 \\quad 9,2 \\quad 9,2 \\quad 9,5 \\quad 10,5.$$",
    "a) Giải thích tại sao nên dùng trung vị để thể hiện mức lương khởi điểm của sinh viên tốt nghiệp từ trường đại học này.",
    "b) Nên dùng khoảng biến thiên hay khoảng tứ phân vị để đo độ phân tán? Vì sao?",
    "",
    "**5.23.** Điểm Toán và điểm Tiếng Anh của 11 học sinh lớp 10 được cho trong bảng sau:",
    "",
    "| Học sinh | A | B | C | D | E | F | G | H | I | J | K |",
    "| :--- | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: |",
    "| Toán | 62 | 91 | 43 | 31 | 57 | 63 | 80 | 37 | 43 | 5 | 78 |",
    "| Tiếng Anh | 65 | 57 | 55 | 37 | 62 | 70 | 73 | 49 | 65 | 41 | 64 |",
    "",
    "Hãy so sánh mức độ “học đều” của học sinh trong môn Tiếng Anh và môn Toán thông qua các số đặc trưng: khoảng biến thiên, khoảng tứ phân vị, độ lệch chuẩn.",
    "",
    "89",
    "**5.24.** Bảng sau cho biết dân số của các tỉnh/thành phố Đồng bằng Bắc Bộ năm 2018 (đơn vị triệu người).",
    "",
    "| Tỉnh/thành phố | Dân số |",
    "|---|:---:|",
    "| Hà Nội | 7,52 |",
    "| Vĩnh Phúc$^{(1)}$ | 1,09 |",
    "| Bắc Ninh | 1,25 |",
    "| Quảng Ninh | 1,27 |",
    "| Hải Dương$^{(2)}$ | 1,81 |",
    "| Hải Phòng | 2,01 |",
    "| Hưng Yên | 1,19 |",
    "| Thái Bình$^{(3)}$ | 1,79 |",
    "| Hà Nam$^{(4)}$ | 0,81 |",
    "| Nam Định$^{(5)}$ | 1,85 |",
    "| Ninh Bình | 0,97 |",
    "",
    "*(Theo Tổng cục Thống kê – nay là Cục Thống kê)*",
    "",
    "a) Tìm số trung bình và trung vị của mẫu số liệu trên.",
    "b) Giải thích tại sao số trung bình và trung vị lại có sự sai khác nhiều.",
    "c) Nên sử dụng số trung bình hay trung vị để đại diện cho dân số của các tỉnh thuộc Đồng bằng Bắc Bộ?",
    "",
    "**5.25.** Hai mẫu số liệu sau đây cho biết số lượng trường Trung học phổ thông ở mỗi tỉnh/thành phố thuộc Đồng bằng sông Hồng và Đồng bằng sông Cửu Long năm 2017:",
    "Đồng bằng sông Hồng: $$187 \\quad 34 \\quad 35 \\quad 46 \\quad 54 \\quad 57 \\quad 37 \\quad 39 \\quad 23 \\quad 57 \\quad 27.$$",
    "Đồng bằng sông Cửu Long: $$33 \\quad 34 \\quad 33 \\quad 29 \\quad 24 \\quad 39 \\quad 42 \\quad 24 \\quad 23 \\quad 19 \\quad 24 \\quad 15 \\quad 26.$$",
    "",
    "*(Theo Tổng cục Thống kê – nay là Cục Thống kê)*",
    "",
    "a) Tính số trung bình, trung vị, các tứ phân vị, mốt, khoảng biến thiên, khoảng tứ phân vị, độ lệch chuẩn cho mỗi mẫu số liệu trên.",
    "b) Tại sao số trung bình của hai mẫu số liệu có sự sai khác nhiều trong khi trung vị thì không?",
    "c) Tại sao khoảng biến thiên và độ lệch chuẩn của hai mẫu số liệu khác nhau nhiều trong khi khoảng tứ phân vị thì không?",
    "",
    "**5.26.** Tỉ lệ trẻ em suy dinh dưỡng (tính theo cân nặng ứng với độ tuổi) của 10 tỉnh thuộc Đồng bằng sông Hồng được cho như sau:",
    "$$5,5 \\quad 13,8 \\quad 10,2 \\quad 12,2 \\quad 11,0 \\quad 7,4 \\quad 11,4 \\quad 13,1 \\quad 12,5 \\quad 13,4.$$",
    "",
    "*(Theo Tổng cục Thống kê – nay là Cục Thống kê)*",
    "",
    "a) Tính số trung bình, trung vị, khoảng biến thiên và độ lệch chuẩn của mẫu số liệu trên.",
    "b) Thực hiện làm tròn đến hàng đơn vị cho các giá trị trong mẫu số liệu. Sai số tuyệt đối của phép làm tròn này không vượt quá bao nhiêu?",
    "",
    "---",
    "$^{(1)}$ Nay thuộc tỉnh Phú Thọ",
    "$^{(2)}$ Nay thuộc thành phố Hải Phòng",
    "$^{(3)}$ Nay thuộc tỉnh Hưng Yên",
    "$^{(4), \\ (5)}$ Nay thuộc tỉnh Ninh Bình",
    "",
    "90"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'PRACTICE' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'HDTH1', 'Tìm hiểu một số kiến thức về tài chính', 91, 20, $JSON$
{
  "content": [
    "# HOẠT ĐỘNG THỰC HÀNH TRẢI NGHIỆM",
    "",
    "[Hình ảnh: Bản đồ thế giới kết nối mạng lưới nhân sự]",
    "",
    "## TÌM HIỂU MỘT SỐ KIẾN THỨC VỀ TÀI CHÍNH",
    "",
    "**MỤC TIÊU**",
    "- Hiểu sự khác biệt giữa tiết kiệm và đầu tư.",
    "- Thực hành thiết lập kế hoạch đầu tư cá nhân để đạt được tỉ lệ tăng trưởng như mong đợi.",
    "",
    "Tiết kiệm và đầu tư là các phương thức khác biệt đóng vai trò quan trọng trong kế hoạch xây dựng tài sản và phân bổ ngân sách chi tiêu của em. Bài học này giúp em thực hành ứng dụng các kiến thức toán học vào thực tiễn, đặc biệt là trong quản lí tài chính.",
    "",
    "[Hình ảnh: Hai lọ thủy tinh đựng tiền xu ghi chữ \"SAVE\" và \"INVEST\" đặt hai bên chữ \"OR\"]",
    "",
    "91",
    "## 1. TIẾT KIỆM VÀ ĐẦU TƯ",
    "",
    "**HĐ1.** Tháng 1 năm 2018, bác Việt gửi tiết kiệm 2 000 000 000 đồng kì hạn 36 tháng ở ngân hàng với lãi suất 7%/năm. Đến tháng 1 năm 2021, bác Việt rút tiền tiết kiệm nêu trên để mua một căn hộ chung cư với giá 30 626 075 đồng/mét vuông.",
    "a) Hỏi tổng số tiền tiết kiệm bác Việt rút ra được vào tháng 1 năm 2021 là bao nhiêu?",
    "b) Với số tiền nêu trên, bác Việt mua được căn hộ chung cư với diện tích bao nhiêu mét vuông?",
    "",
    "*Công thức lãi kép:* Gửi $A$ đồng vào ngân hàng với lãi suất kép $r\\%$/năm, sau $n$ năm, số tiền nhận được tính theo công thức:",
    "$$T = A \\cdot (1 + r\\%)^n.$$",
    "",
    "[Hình ảnh: Bàn tay nâng heo đất màu hồng]",
    "",
    "**TRAO ĐỔI**",
    "Để mua được căn hộ 100 mét vuông ở thời điểm tháng 1 năm 2021, bác Việt cần phải gửi tiết kiệm từ tháng 1 năm 2018 bao nhiêu tiền?",
    "",
    "**HĐ2.** Cô Lan có 511 000 000 đồng và dự định đầu tư vào chứng khoán của công ty A. Biểu đồ chứng khoán của công ty A được cho trong Hình T.1 với những thời điểm khác nhau.",
    "",
    "[Hình T.1a: Biểu đồ chứng khoán của công ty A từ tháng 6 năm 2020 đến tháng 4 năm 2021]",
    "",
    "92",
    "[Hình T.1b: Biểu đồ biến động giá cổ phiếu tại thời điểm ngày 27 tháng 7 năm 2020]",
    "Hình T.1b",
    "",
    "[Hình T.1c: Biểu đồ biến động giá cổ phiếu tại thời điểm ngày 30 tháng 12 năm 2020]",
    "Hình T.1c",
    "",
    "[Hình T.1d: Biểu đồ biến động giá cổ phiếu tại thời điểm ngày 10 tháng 5 năm 2021]",
    "Hình T.1d",
    "",
    "93",
    "| Thời gian | 10-6-2020 | 27-7-2020 | 30-12-2020 | 10-5-2021 |",
    "|---|:---:|:---:|:---:|:---:|",
    "| Giá mỗi cổ phiếu (đồng) | 102 200 | 86 000 | 108 800 | 91 000 |",
    "| Số cổ phiếu | 5 000 | 5 000 | 5 000 | 5 000 |",
    "| Tổng (đồng) | 511 000 000 | ? | ? | ? |",
    "",
    "a) Nếu cô Lan bán 5 000 cổ phiếu của công ty A vào các thời điểm sau thì tổng số tiền tương ứng cô Lan thu được là bao nhiêu?",
    "$$27-7-2020; \\quad 30-12-2020; \\quad 10-5-2021.$$",
    "b) Nếu ngày 10-6-2020 cô Lan dùng số tiền 511 000 000 đồng để gửi tiết kiệm với lãi suất 6%/năm cho kì hạn một tháng thì vào ngày 10-5-2021, tổng số tiền cô Lan nhận được là bao nhiêu?",
    "",
    "**TRAO ĐỔI**",
    "a) Với tình huống trên, cô Lan nên đầu tư như thế nào để hiệu quả nhất?",
    "b) Nếu so sánh giữa việc gửi tiết kiệm và đầu tư, cô Lan nên chọn hình thức nào?",
    "",
    "**Em có biết?**",
    "",
    "*Tiết kiệm và đầu tư là nền tảng cho các hoạt động về tài chính.*",
    "Về cơ bản, có thể hiểu tiết kiệm là việc lưu giữ giá trị, biến sức mua hiện tại thành sức mua trong tương lai; còn đầu tư là nhằm gia tăng giá trị. Đầu tư liên quan đến việc đưa tài chính vào các khoản đầu tư, chẳng hạn như cổ phiếu, với hy vọng tài chính sẽ tăng lên.",
    "",
    "**Vận dụng 1.** Anh Tiến có 898 200 000 đồng dự định đầu tư. Anh Tiến mong muốn sau 2 năm sẽ nhận được số tiền (cả gốc lẫn lãi) là 1 tỉ đồng. Ngày 9-12-2020, anh Tiến quyết định đầu tư mua cổ phiếu của công ty B. Giá mỗi cổ phiếu là 24 950 đồng. Biểu đồ chứng khoán của công ty B được cho trong Hình T.2.",
    "",
    "[Hình T.2: Biểu đồ chứng khoán của công ty B từ ngày 9 tháng 12 năm 2020 đến tháng 5]",
    "",
    "94",
    "Dựa vào biểu đồ trên, hãy tính số tiền mà anh Tiến thu được khi bán cổ phiếu của công ty B tại các thời điểm sau:",
    "a) 15-3-2021;",
    "b) 15-4-2021;",
    "c) 18-5-2021.",
    "",
    "## 2. THUẾ THU NHẬP CÁ NHÂN",
    "",
    "**HĐ3.** Thuế suất biểu luỹ tiến từng phần được phân loại chi tiết trong bảng sau:",
    "",
    "| Bậc thuế | Phần thu nhập tính thuế/tháng (triệu đồng) | Thuế suất (%) |",
    "|---|---|---|",
    "| 1 | Đến 5 | 5 |",
    "| 2 | Trên 5 đến 10 | 10 |",
    "| 3 | Trên 10 đến 18 | 15 |",
    "| 4 | Trên 18 đến 32 | 20 |",
    "| 5 | Trên 32 đến 52 | 25 |",
    "| 6 | Trên 52 đến 80 | 30 |",
    "| 7 | Trên 80 | 35 |",
    "",
    "*Chú thích:*",
    "- Thuế thu nhập cá nhân là khoản tiền (thuế) mà người có thu nhập phải trích nộp một phần vào ngân sách nhà nước sau khi đã tính các khoản được giảm trừ. Các khoản giảm trừ thông thường bao gồm:",
    "  - Giảm trừ bản thân;",
    "  - Giảm trừ người phụ thuộc.",
    "- Thuế suất thuế thu nhập cá nhân là tỉ lệ phần trăm dùng để tính số thuế phải nộp căn cứ vào phần thu nhập tính thuế của mỗi người.",
    "",
    "a) Hãy lập công thức hàm số bậc nhất mô tả sự phụ thuộc của thuế thu nhập cá nhân vào phần thu nhập tính thuế/tháng với mức thu nhập tính thuế/tháng không quá 5 triệu đồng và vẽ đồ thị hàm số này.",
    "b) Hãy lập công thức hàm số bậc nhất mô tả sự phụ thuộc của thuế thu nhập cá nhân vào phần thu nhập tính thuế/tháng với mức thu nhập tính thuế/tháng trên 5 triệu đồng và không quá 10 triệu đồng. Vẽ đồ thị hàm số này.",
    "c) Anh Nam làm việc ở một ngân hàng với mức thu nhập chịu thuế đều đặn là 28 triệu đồng/tháng và có một người phụ thuộc (một con nhỏ dưới 18 tuổi). Hãy giúp anh Nam tính số thuế thu nhập cá nhân mà anh phải nộp trong một năm, biết rằng các khoản giảm trừ được tính bao gồm giảm trừ bản thân cho anh Nam (11 triệu đồng/tháng) và giảm trừ người phụ thuộc (4,4 triệu đồng/tháng cho mỗi người phụ thuộc).",
    "",
    "*Công thức tính:*",
    "- $\\text{Thu nhập tính thuế} = \\text{Thu nhập chịu thuế} - \\text{Các khoản giảm trừ}.$",
    "- $\\text{Thuế thu nhập cá nhân} = \\text{Thu nhập tính thuế} \\times \\text{Thuế suất}.$",
    "",
    "**Vận dụng 2.** Hãy sử dụng bảng thuế suất biểu luỹ tiến từng phần được cho trong HĐ3 để xây dựng công thức tính thuế thu nhập cá nhân theo từng trường hợp (căn cứ vào phần thu nhập tính thuế).",
    "",
    "95"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'PRACTICE' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'TOAN10_T1')), 'HDTH2', 'Mạng xã hội: lợi và hại', 96, 21, $JSON$
{
  "content": [
    "# MẠNG XÃ HỘI: LỢI VÀ HẠI",
    "",
    "Ngày nay cùng với Internet, mạng xã hội đã trở nên quen thuộc với nhiều người. Một nhóm các bạn học sinh lớp 10A muốn tìm hiểu thực tế sử dụng mạng xã hội của các bạn trong lớp mình. Những vấn đề các bạn quan tâm là:",
    "1. Lợi ích, bất lợi lớn nhất khi dùng mạng xã hội là gì?",
    "2. Thời gian sử dụng mạng xã hội của các bạn trong lớp như thế nào?",
    "3. Các bạn nam và bạn nữ có thời gian sử dụng mạng xã hội khác nhau không?",
    "",
    "[Hình ảnh: Trái Đất kết nối mạng xã hội (Social Networks)]",
    "",
    "## 1. THU THẬP DỮ LIỆU",
    "",
    "Các bạn trong nhóm đã lập một phiếu khảo sát để thu thập dữ liệu như sau:",
    "",
    "**KHẢO SÁT VỀ SỬ DỤNG MẠNG XÃ HỘI**",
    "",
    "1. Giới tính của bạn:",
    "   * [ ] Nữ",
    "   * [ ] Nam",
    "",
    "2. Lợi ích lớn nhất mà mạng xã hội mang lại là (chọn một phương án):",
    "   A. Kết nối với bạn bè",
    "   B. Giải trí",
    "   C. Thu thập thông tin",
    "   D. Tìm hiểu thế giới xung quanh",
    "",
    "3. Điều bất lợi lớn nhất khi sử dụng mạng xã hội là (chọn một phương án):",
    "   A. Có nguy cơ tiếp xúc với những bài viết, hình ảnh, video, ý kiến tiêu cực, không thích hợp",
    "   B. Thông tin cá nhân bị đánh cắp",
    "   C. Có thể bị bắt nạt trên Internet",
    "   D. Mất thời gian sử dụng Internet",
    "",
    "4. Thời gian (ước lượng số phút) bạn sử dụng mạng xã hội trong một ngày:",
    "   ...........................................................................................................................",
    "",
    "96",
    "**HĐ1.** Hãy dùng phiếu khảo sát theo mẫu trên, tiến hành thu thập dữ liệu với ít nhất 30 phiếu và ghi lại dữ liệu theo mẫu sau:",
    "",
    "| STT | Giới tính | Thời gian dùng mạng xã hội | Lợi ích | Bất lợi |",
    "| :---: | :---: | :---: | :---: | :---: |",
    "| 1 | Nam | 60 | C | B |",
    "| | | | | |",
    "| | | | | |",
    "",
    "*Hình T.3*",
    "",
    "## 2. XỬ LÍ VÀ PHÂN TÍCH SỐ LIỆU",
    "",
    "**HĐ2. Lợi ích và bất lợi của mạng xã hội**",
    "",
    "Để biết các bạn học sinh tham gia khảo sát đánh giá thế nào về lợi ích và bất lợi của mạng xã hội, hãy thực hiện các yêu cầu sau:",
    "a) Lập bảng tần số của dữ liệu ý kiến về lợi ích/bất lợi của mạng xã hội theo mẫu sau:",
    "",
    "| Ý kiến | Kết nối với bạn bè | Giải trí | Thu thập thông tin | Tìm hiểu thế giới xung quanh |",
    "|---|:---:|:---:|:---:|:---:|",
    "| Số học sinh | | | | |",
    "",
    "*Bảng T.1*",
    "",
    "b) Rút ra nhận xét từ bảng tần số thu được.",
    "",
    "**HĐ3. Thời gian sử dụng mạng xã hội**",
    "",
    "Hãy tính một số số đo thống kê mô tả được liệt kê trong Bảng T.2 của mẫu số liệu về thời gian sử dụng mạng xã hội:",
    "",
    "| Giá trị nhỏ nhất | $Q_1$ | Số trung bình | Trung vị | $Q_3$ | Mốt | Giá trị lớn nhất |",
    "| :---: | :---: | :---: | :---: | :---: | :---: | :---: |",
    "| | | | | | | |",
    "",
    "*Bảng T.2*",
    "",
    "Dựa trên những số đặc trưng tính được, hãy nêu nhận xét về thời gian sử dụng mạng xã hội của các học sinh được khảo sát.",
    "",
    "**HĐ4. Thời gian sử dụng mạng xã hội của học sinh nam và học sinh nữ**",
    "",
    "a) Hãy tính số trung bình, trung vị, tứ phân vị của thời gian sử dụng mạng xã hội trên hai nhóm học sinh nữ và học sinh nam để so sánh thời gian sử dụng mạng xã hội của hai nhóm.",
    "",
    "| | Số trung bình | $Q_1$ | Trung vị ($Q_2$) | $Q_3$ |",
    "|---|:---:|:---:|:---:|:---:|",
    "| Nữ | | | | |",
    "| Nam | | | | |",
    "",
    "*Bảng T.3*",
    "",
    "97",
    "b) Hãy tính một vài số đo độ phân tán để so sánh sự biến động của thời gian sử dụng mạng xã hội trên hai nhóm học sinh.",
    "",
    "| | Khoảng biến thiên | Khoảng tứ phân vị | Độ lệch chuẩn |",
    "|---|:---:|:---:|:---:|",
    "| Nữ | | | |",
    "| Nam | | | |",
    "",
    "*Bảng T.4*",
    "",
    "## 3. GÓC CÔNG NGHỆ THÔNG TIN",
    "",
    "Ta có thể dùng máy tính cầm tay hoặc phần mềm bảng tính để tính các số đặc trưng của mẫu số liệu.",
    "",
    "**Sử dụng máy tính cầm tay**",
    "",
    "Giả sử khảo sát được thời gian sử dụng mạng xã hội của một số bạn như sau:",
    "$$60 \\quad 90 \\quad 120 \\quad 60 \\quad 15 \\quad 50 \\quad 80 \\quad 30 \\quad 120 \\quad 90.$$",
    "Sử dụng máy tính cầm tay để tính những số đặc trưng của mẫu số liệu trên:",
    "",
    "1. Vào chế độ thống kê:",
    "   `MODE` `3` `1`",
    "",
    "2. Nhập số liệu vào máy:",
    "   `6` `0` `=` `9` `0` `=` `1` `2` `0` `=` `6` `0` `=` `1` `5` `=` `5` `0` `=`",
    "   `8` `0` `=` `3` `0` `=` `1` `2` `0` `=` `9` `0` `=`",
    "",
    "3. Tính số trung bình:",
    "   `AC` `SHIFT` `1` `4` `2` `=`",
    "   Ta được kết quả số trung bình là 71,5.",
    "",
    "[Hình ảnh: Màn hình máy tính Casio hiển thị kết quả trung bình $\\bar{x} = 71.5$]",
    "",
    "4. Tính độ lệch chuẩn:",
    "   `AC` `SHIFT` `1` `4` `3` `=`",
    "   Ta được kết quả độ lệch chuẩn là $s = 33,32041416$.",
    "",
    "[Hình ảnh: Màn hình máy tính Casio hiển thị kết quả độ lệch chuẩn $\\sigma x = 33.32041416$]",
    "",
    "**Chú ý.** Để tính đại lượng:",
    "$$\\hat{s} = \\sqrt{\\frac{(x_1 - \\bar{x})^2 + (x_2 - \\bar{x})^2 + \\dots + (x_n - \\bar{x})^2}{n-1}}$$",
    "ta ấn `AC` `SHIFT` `1` `4` `4` `=`",
    "Kết quả là $\\hat{s} = 35,12280045$.",
    "",
    "98",
    "**Sử dụng phần mềm bảng tính**",
    "",
    "Với những mẫu số liệu lớn hơn, phần mềm thống kê sẽ giúp cho việc xử lí dữ liệu trở nên nhanh chóng và chính xác. Những hướng dẫn sau được minh hoạ trên số liệu về điểm thi khảo sát môn Tiếng Anh (thang điểm 100) của 45 học sinh:",
    "$$32 \\quad 75 \\quad 59 \\quad 66 \\quad 69 \\quad 44 \\quad 29 \\quad 66 \\quad 58 \\quad 72 \\quad 65 \\quad 62 \\quad 88 \\quad 71 \\quad 60$$",
    "$$64 \\quad 68 \\quad 69 \\quad 57 \\quad 60 \\quad 72 \\quad 54 \\quad 65 \\quad 62 \\quad 90 \\quad 61 \\quad 59 \\quad 68 \\quad 56 \\quad 42$$",
    "$$69 \\quad 67 \\quad 67 \\quad 55 \\quad 66 \\quad 72 \\quad 55 \\quad 61 \\quad 71 \\quad 70 \\quad 65 \\quad 61 \\quad 60 \\quad 60 \\quad 79$$",
    "",
    "### a) Dùng các hàm tính số đặc trưng",
    "",
    "Việc tính các số đặc trưng của một mẫu số liệu có thể thực hiện trên phần mềm bảng tính nhờ những hàm có sẵn. Chẳng hạn, để tính số trung bình ta làm như sau:",
    "",
    "1. Nhập số liệu vào một cột của bảng tính.",
    "2. Tại một ô trống để chứa kết quả gõ:",
    "   `= AVERAGE(vùng dữ liệu)`",
    "",
    "Trong ví dụ trên kết quả trả về giá trị trung bình của mẫu số liệu là 63,13 (H.T.4).",
    "",
    "[Hình T.4. Giao diện Excel minh hoạ công thức `=AVERAGE(A2:A46)` để tính trung bình cộng]",
    "",
    "Để tính những số đặc trưng khác em hãy thay hàm AVERAGE bởi hàm thích hợp theo bảng sau:",
    "",
    "**Bảng T.5. Danh sách hàm để tính số đo xu thế trung tâm**",
    "| Số đặc trưng | Hàm |",
    "|---|---|",
    "| Số trung bình | AVERAGE |",
    "| Trung vị | MEDIAN |",
    "| Mốt | MODE |",
    "| Tứ phân vị | QUARTILE |",
    "",
    "**Bảng T.6. Danh sách hàm để tính số đo độ phân tán**",
    "| Số đặc trưng | Hàm |",
    "|---|---|",
    "| Giá trị nhỏ nhất | MIN |",
    "| Giá trị lớn nhất | MAX |",
    "| Phương sai | VAR, VARP |",
    "| Độ lệch chuẩn | STDEV, STDEVP |",
    "",
    "99",
    "- Tính số trung bình, trung vị, mốt (H.T.5).",
    "",
    "[Hình T.5. Giao diện Excel tính toán Trung bình `=AVERAGE(A2:A46)`, Trung vị `=MEDIAN(A2:A46)`, Mốt `=MODE(A2:A46)`]",
    "",
    "**Chú ý.** Hàm MODE sẽ trả về giá trị #N/A nếu mẫu số liệu không có giá trị lặp lại. Trong trường hợp mẫu số liệu có nhiều mốt thì phần mềm bảng tính hiển thị giá trị mốt nhỏ nhất.",
    "",
    "- Tính tứ phân vị (H.T.6).",
    "",
    "[Hình T.6. Giao diện Excel tính toán Tứ phân vị thứ nhất `=QUARTILE(A2:A46,1)`, Tứ phân vị thứ hai `=QUARTILE(A2:A46,2)`, Tứ phân vị thứ ba `=QUARTILE(A2:A46,3)`]",
    "",
    "**Chú ý.** Kết quả tính tứ phân vị bằng phần mềm bảng tính có sự sai khác nhỏ so với cách tính được giới thiệu ở Bài 13 (do dùng công thức khác nhau).",
    "",
    "100",
    "- Tính phương sai, độ lệch chuẩn, khoảng biến thiên (H.T.7).",
    "",
    "[Hình T.7. Giao diện Excel tính toán Khoảng biến thiên `=MAX(A2:A46)-MIN(A2:A46)`, Phương sai `=VARP(A2:A46)`, Độ lệch chuẩn `=STDEVP(A2:A46)`]",
    "",
    "**Chú ý.** Để tính $\\hat{s}^2$ và $\\hat{s}$ ta thay VARP bởi VAR và thay STDEVP bởi STDEV.",
    "",
    "### b) Dùng chức năng phân tích dữ liệu trên thanh công cụ",
    "",
    "Ngoài các hàm tính các số đặc trưng riêng lẻ, phần mềm bảng tính cho phép in ra một bảng tổng hợp gồm nhiều số đặc trưng khác nhau. Cách thực hiện như sau:",
    "",
    "1. Nhập số liệu vào một cột.",
    "2. Trên menu chọn **Tools** $\\rightarrow$ **Data Analysis** $\\rightarrow$ **Descriptive Statistics**.",
    "3. Tại **Input Range** chọn vùng dữ liệu `(A1: A46)`. Nháy chọn **Label in first row**. Tại **Output Range** chọn một ô trống để xác định vị trí hiển thị kết quả tích và nháy chọn **Summary statistics**.",
    "",
    "[Hình T.8. Bảng tổng hợp Descriptive Statistics của Diem thi]",
    "",
    "| Diem thi | |",
    "|---|---|",
    "| Mean | 63.1333333 |",
    "| Standard Error | 1.70014854 |",
    "| Median | 65 |",
    "| Mode | 60 |",
    "| Standard Deviation | 11.4049431 |",
    "| Sample Variance | 130.072727 |",
    "| Kurtosis | 2.43808457 |",
    "| Skewness | -0.7116263 |",
    "| Range | 61 |",
    "| Minimum | 29 |",
    "| Maximum | 90 |",
    "| Sum | 2841 |",
    "| Count | 45 |",
    "",
    "**Chú ý**",
    "- Trong hình bên, phương sai và độ lệch chuẩn tính theo công thức tính $\\hat{s}^2$ và $\\hat{s}$ tương ứng. Có một vài số đặc trưng chưa được giới thiệu trong phạm vi Toán 10.",
    "- Để tính những số đặc trưng cho hai mẫu số liệu ta nhập số liệu vào hai cột và tiến hành tương tự.",
    "",
    "101"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

